30	/// Where a record's FIELD NAMES came from — the input to dataset clustering.
31	///
32	/// Clustering groups files by their field names (`dataset::cluster`), and the
33	/// dataset slug is an ingredient of every `_id` (`ids::doc_id`). So a name that
34	/// can appear or disappear because the EXTRACTOR changed — not because the file
35	/// changed — silently moves that file's documents to a different index and
36	/// orphans the ones already written under the old slug (issue #178).
37	///
38	/// `Data` names are read out of the file (JSON keys, CSV header, SQL columns,
39	/// HTML table headers, parsed log keys): two files that share them really do
40	/// share a schema, and the names change only when the file changes.
41	/// `Extractor` names are the extractor's own vocabulary (`title`/`body`,
42	/// `defs`/`symbols`/`symbol_count`, `page`/`section`) — they describe the tool,
43	/// not the data, so they are excluded from the clustering key.
44	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
45	#[serde(rename_all = "snake_case")]
46	pub enum FieldOrigin {
47	    /// Field names read out of the file itself.
48	    Data,
49	    /// Field names invented by the extractor.
50	    Extractor,
51	}
52	
53	/// One extracted record before coercion.
54	#[derive(Debug, Clone, Serialize, Deserialize)]
55	pub struct RawRecord {
56	    pub fields: Map<String, Value>,
57	    /// Canonical, content-positional locator (byte offset / ordinal /
58	    /// table+row) — the idempotent-_id ingredient.
59	    pub locator: String,
60	    /// Sub-dataset group within a file (table name for sql/sqlite).
61	    pub group: Option<String>,
62	    /// Whether `fields`' NAMES came from the file or from this extractor.
63	    /// Set it at every emit site: it decides whether those names are allowed
64	    /// to move the file between datasets.
65	    pub origin: FieldOrigin,
66	}
67	
68	#[derive(Debug, Default, Clone, Copy)]
69	pub struct ExtractStats {
70	    pub records: u64,
71	    pub junk: u64,
72	    /// Set when a per-file record cap (`MAX_RECORDS_PER_FILE`) stopped the
73	    /// split before the whole body was emitted (#381). Carried out so the
74	    /// truncation is reported, never silent.
75	    pub truncated: bool,
76	}
77	
78	/// Sink returns false to stop extraction early (sampling).
79	pub type Sink<'a> = &'a mut dyn FnMut(RawRecord) -> bool;
80	
81	pub const MAX_LINE: usize = 16 << 20; // 16MB line cap
82	pub const MAX_WHOLE_FILE: u64 = 64 << 20; // whole-file parse cap (json/html/yaml/txt)
83	/// Target characters per document section.
84	///
85	/// Was 32 KB, which is a *storage* granularity, not a *retrieval* one: BM25
86	/// scores per document, so a 32 KB section dilutes any match into noise and
87	/// every hit drags 32 KB through `_source`.  Measured on a 460-commit history
88	/// file, 32 KB sections produced 25 documents for 15,407 lines and the
89	/// relevant commit was not retrievable; at 2 KB with paragraph overlap it is.
90	///
91	/// 2 KB is roughly the 40-line window validated for line-oriented text, and
92	/// comfortably inside the 512-token limit of the built-in neural embedder, so
93	/// a section maps to one vector without truncation.
94	pub const SECTION_CHARS: usize = 2 << 10;
95	
96	/// Hard cap on section records one file may emit (#381).
97	///
98	/// A magic-less printable byte payload (a raw texture, a packed `.bytes` asset)
99	/// decodes under the text fallback, classifies as prose and is sectioned in
100	/// full — one record per `SECTION_CHARS`, so the 16 MiB txt read cap becomes
101	/// ~8k noise records with no ceiling of its own. This bounds that; the drop is
102	/// surfaced via `ExtractStats.truncated`, so a genuinely large *legitimate*
103	/// document is reported and never silently cut. A resource guard keyed off
104	/// record count only — never off byte statistics, which is what deleted CJK
105	/// text worldwide and was removed in #371.
106	pub const MAX_RECORDS_PER_FILE: usize = 4 << 10; // 4096
107	
108	/// Characters of the previous section repeated at the start of the next, so an
109	/// answer spanning a boundary stays retrievable from both sides.
110	pub const SECTION_OVERLAP: usize = 200;
111	
112	/// Open a (possibly gzipped) file as a buffered reader of DECODED-transparent
113	/// bytes, optionally capped at `limit` decoded bytes (sampling).
114	pub fn open_reader(path: &Path, gzip: bool, limit: Option<u64>) -> Result<Box<dyn BufRead + Send>> {
115	    let f = std::fs::File::open(path)?;
116	    let inner: Box<dyn Read + Send> = if gzip {
117	        Box::new(flate2::read::MultiGzDecoder::new(f))
118	    } else {
119	        Box::new(f)
120	    };
121	    // `Send` so a container extractor (mbox) can move the reader to its
122	    // splitter thread; every concrete reader here is.
123	    let inner: Box<dyn Read + Send> = match limit {
124	        Some(n) => Box::new(inner.take(n)),
125	        None => Box::new(inner),
126	    };
127	    Ok(Box::new(BufReader::with_capacity(256 << 10, inner)))
128	}
129	
130	/// Read a whole (possibly gzipped) file, capped; None if over cap.
131	pub fn read_whole(path: &Path, gzip: bool, cap: u64) -> Result<Option<Vec<u8>>> {
132	    let mut r = open_reader(path, gzip, Some(cap + 1))?;
133	    let mut buf = Vec::new();
134	    r.read_to_end(&mut buf)?;
135	    if buf.len() as u64 > cap {
136	        return Ok(None);
137	    }
138	    Ok(Some(buf))
139	}
