141	/// Render a file as a DOCUMENT (title = file stem, body = decoded text,
142	/// section-split), regardless of its format family. This is how demoted
143	/// one-off config files (`dataset` module docs, #173) are indexed: their
144	/// key sets are configuration, not a schema, so their retrievable value is
145	/// the text itself. Emits the same `title`/`body`/`section` vocabulary as
146	/// every other document extractor (`FieldOrigin::Extractor`).
147	pub fn extract_as_document(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
148	    extract_as_document_with_name(path, path, gzip, sink)
149	}
150	
151	/// [`extract_as_document`], but the title comes from `logical_path` rather
152	/// than `content_path`. The `--no-graph` generated pipeline reads a
153	/// SEALED SNAPSHOT — a real file on disk, but under its own ordinal name
154	/// (`prepared/00000000`, …), not the source's — so deriving the title from
155	/// `content_path` there produced `"00000000"` instead of the file's own
156	/// name (#722). Mirrors `sniff::sniff_with_name`'s split for exactly the
157	/// same reason.
158	pub fn extract_as_document_with_name(
159	    content_path: &Path,
160	    logical_path: &Path,
161	    gzip: bool,
162	    sink: Sink,
163	) -> Result<ExtractStats> {
164	    let mut stats = ExtractStats::default();
165	    let Some(bytes) = read_whole(content_path, gzip, MAX_WHOLE_FILE)? else {
166	        stats.junk += 1;
167	        return Ok(stats);
168	    };
169	    let (text, _) = crate::sniff::decode_text(&bytes);
170	    if text.trim().is_empty() {
171	        stats.junk += 1;
172	        return Ok(stats);
173	    }
174	    let title = logical_path
175	        .file_stem()
176	        .map(|s| s.to_string_lossy().to_string())
177	        .unwrap_or_else(|| "untitled".into());
178	    emit_document(
179	        &title,
180	        &[],
181	        text.trim(),
182	        MAX_RECORDS_PER_FILE,
183	        sink,
184	        &mut stats,
185	    );
186	    Ok(stats)
187	}
