189	/// Dispatch to the family extractor. `limit_bytes` bounds SAMPLING reads;
190	/// `None` = full stream.
191	pub fn extract(
192	    path: &Path,
193	    sn: &Sniffed,
194	    limit_bytes: Option<u64>,
195	    sink: Sink,
196	) -> Result<ExtractStats> {
197	    match sn.family {
198	        Family::Jsonl => jsonl::extract(path, sn.gzip, limit_bytes, sink),
199	        Family::Json => json::extract(path, sn.gzip, sink),
200	        Family::Csv => csv_x::extract(path, sn, limit_bytes, sink),
201	        Family::Logs => logs::extract(path, sn.gzip, limit_bytes, sink),
202	        Family::Xml => xml_x::extract(path, sn.gzip, sink),
203	        Family::Html => html::extract(path, sn.gzip, sink),
204	        Family::Yaml => yaml_x::extract(path, sn.gzip, sink),
205	        Family::TxtProse => txt::extract_prose(path, sn.gzip, sink),
206	        Family::TxtLines => txt::extract_lines(path, sn.gzip, limit_bytes, sink),
207	        Family::Pdf => pdf::extract(path, sink),
208	        Family::Eml => eml::extract(path, sn.gzip, sink),
209	        Family::Mbox => mbox::extract(path, sn.gzip, limit_bytes, sink),
210	        Family::Docx => docx::extract(path, sink),
211	        Family::Sqlite => sqlite_x::extract(path, limit_bytes.map(|_| 500), sink),
212	        Family::SqlDump => sqldump::extract(path, sn.gzip, limit_bytes, sink),
213	        Family::Code => code::extract(path, sn, sink),
214	        Family::UnityYaml => unity::extract_unity(path, sn.gzip, limit_bytes, sink),
215	        Family::UnityMeta => unity::extract_meta(path, sn.gzip, sink),
216	        Family::Bvh => bvh::extract(path, sn.gzip, sink),
217	        // `--stub`-designated file: one name card, the file is never opened.
218	        Family::Stub => {
219	            let mut stats = ExtractStats::default();
220	            let mut fields = Map::new();
221	            // The name card is this record's ENTIRE content, so it must come
222	            // from the logical name. Under durable preparation `path` is a
223	            // content-addressed blob and would title every stub `00000000`.
224	            let named = sn.logical_name.as_deref().unwrap_or(path);
225	            let title = named
226	                .file_name()
227	                .and_then(|n| n.to_str())
228	                .unwrap_or("file")
229	                .to_string();
230	            fields.insert("title".into(), Value::String(title));
231	            stats.records += 1;
232	            sink(RawRecord {
233	                fields,
234	                locator: "stub".into(),
235	                group: None,
236	                origin: FieldOrigin::Extractor,
237	            });
238	            Ok(stats)
239	        }
240	        Family::Binary => Ok(ExtractStats::default()),
241	    }
242	}
