244	// ─── shared helpers ──────────────────────────────────────────────────────
245	
246	pub const MAX_FIELDS_PER_RECORD: usize = 512;
247	
248	/// Flatten a JSON object into a flat field map: up to TWO levels of nesting
249	/// become `a_b_c` keys; deeper structure and arrays-of-objects are stored as
250	/// JSON strings; arrays of scalars stay as arrays. Fields named `ax_*` are
251	/// renamed `ax__*` (provenance namespace collision).
252	pub fn flatten_object(obj: Map<String, Value>) -> Map<String, Value> {
253	    let mut out = Map::new();
254	    for (k, v) in obj {
255	        flatten_into(&sanitize_collision(&k), v, 0, &mut out);
256	        if out.len() >= MAX_FIELDS_PER_RECORD {
257	            break;
258	        }
259	    }
260	    out
261	}
262	
263	fn sanitize_collision(k: &str) -> String {
264	    if k.starts_with("ax_") {
265	        // Data field collides with the ax_* provenance namespace — move it
266	        // out (recorded in the catalog as a rename note).
267	        format!("data_{k}")
268	    } else {
269	        k.to_string()
270	    }
271	}
272	
273	fn flatten_into(key: &str, v: Value, depth: usize, out: &mut Map<String, Value>) {
274	    if out.len() >= MAX_FIELDS_PER_RECORD {
275	        return;
276	    }
277	    match v {
278	        Value::Object(m) => {
279	            if depth < 2 {
280	                for (k, vv) in m {
281	                    flatten_into(&format!("{key}_{k}"), vv, depth + 1, out);
282	                }
283	            } else {
284	                out.insert(
285	                    key.to_string(),
286	                    Value::String(serde_json::to_string(&m).unwrap_or_default()),
287	                );
288	            }
289	        }
290	        Value::Array(a) => {
291	            if a.iter().all(|e| !e.is_object() && !e.is_array()) {
292	                out.insert(key.to_string(), Value::Array(a));
293	            } else {
294	                out.insert(
295	                    key.to_string(),
296	                    Value::String(serde_json::to_string(&a).unwrap_or_default()),
297	                );
298	            }
299	        }
300	        other => {
301	            out.insert(key.to_string(), other);
302	        }
303	    }
304	}
