306	/// Convert a parsed YAML value into JSON (shared by the YAML and Unity
307	/// extractors). Tagged values unwrap to their inner value; non-string mapping
308	/// keys are stringified.
309	pub(crate) fn yaml_to_json(v: serde_yaml::Value) -> Value {
310	    match v {
311	        serde_yaml::Value::Null => Value::Null,
312	        serde_yaml::Value::Bool(b) => Value::Bool(b),
313	        serde_yaml::Value::Number(n) => {
314	            if let Some(i) = n.as_i64() {
315	                Value::Number(i.into())
316	            } else if let Some(u) = n.as_u64() {
317	                Value::Number(u.into())
318	            } else {
319	                serde_json::Number::from_f64(n.as_f64().unwrap_or(0.0))
320	                    .map(Value::Number)
321	                    .unwrap_or(Value::Null)
322	            }
323	        }
324	        serde_yaml::Value::String(s) => Value::String(s),
325	        serde_yaml::Value::Sequence(seq) => {
326	            Value::Array(seq.into_iter().map(yaml_to_json).collect())
327	        }
328	        serde_yaml::Value::Mapping(m) => {
329	            let mut out = Map::new();
330	            for (k, vv) in m {
331	                let key = match k {
332	                    serde_yaml::Value::String(s) => s,
333	                    other => serde_yaml::to_string(&other)
334	                        .unwrap_or_else(|_| "key".into())
335	                        .trim()
336	                        .to_string(),
337	                };
338	                out.insert(key, yaml_to_json(vv));
339	            }
340	            Value::Object(out)
341	        }
342	        serde_yaml::Value::Tagged(t) => yaml_to_json(t.value),
343	    }
344	}
