346	/// Sanitize a discovered field/column name to a safe ES field name.
347	pub fn sanitize_field_name(name: &str) -> String {
348	    let mut s: String = name
349	        .trim()
350	        .chars()
351	        .map(|c| {
352	            if c.is_ascii_alphanumeric() || c == '_' || c == '@' {
353	                c
354	            } else {
355	                '_'
356	            }
357	        })
358	        .collect();
359	    while s.contains("__") {
360	        s = s.replace("__", "_");
361	    }
362	    let s = s.trim_matches('_').to_string();
363	    if s.is_empty() {
364	        "field".to_string()
365	    } else {
366	        sanitize_collision(&s)
367	    }
368	}
