370	/// Last `n` bytes of `s`, snapped back to a char boundary.
371	fn tail(s: &str, n: usize) -> String {
372	    if s.len() <= n {
373	        return s.to_string();
374	    }
375	    let start = s
376	        .char_indices()
377	        .rev()
378	        .take_while(|(i, _)| s.len() - *i <= n)
379	        .last()
380	        .map(|(i, _)| i)
381	        .unwrap_or(0);
382	    s[start..].to_string()
383	}
384	
385	/// Smallest char boundary of `s` that is `>= i` (`s.len()` if `i` is past the
386	/// end). Used for the hard-split cut so a multi-byte char is never severed.
387	fn ceil_boundary(s: &str, i: usize) -> usize {
388	    if i >= s.len() {
389	        return s.len();
390	    }
391	    let mut i = i;
392	    while i < s.len() && !s.is_char_boundary(i) {
393	        i += 1;
394	    }
395	    i
396	}
397	
398	/// Largest char boundary of `s` that is `<= i` (`s.len()` if `i` is past the
399	/// end).
400	fn floor_boundary(s: &str, i: usize) -> usize {
401	    if i >= s.len() {
402	        return s.len();
403	    }
404	    let mut i = i;
405	    while i > 0 && !s.is_char_boundary(i) {
406	        i -= 1;
407	    }
408	    i
409	}
