411	/// Top up `cur` from the front of `rest` until it holds `want` bytes, moving
412	/// whole chars only. Guarantees progress: if `want - cur.len()` lands inside
413	/// the next char, that whole char moves anyway.
414	fn fill_window(cur: &mut String, rest: &mut &str, want: usize) {
415	    if rest.is_empty() || cur.len() >= want {
416	        return;
417	    }
418	    let need = want - cur.len();
419	    let mut take = floor_boundary(rest, need.min(rest.len()));
420	    if take == 0 {
421	        take = rest
422	            .chars()
423	            .next()
424	            .map(|c| c.len_utf8())
425	            .unwrap_or(rest.len());
426	    }
427	    cur.push_str(&rest[..take]);
428	    *rest = &rest[take..];
429	}
