431	/// Stream `text` as retrieval-sized sections, split at paragraph boundaries and
432	/// repeating `SECTION_OVERLAP` characters across each boundary. `emit` returns
433	/// false to stop; `for_each_section` then returns false without doing the rest
434	/// of the work.
435	///
436	/// Linear in `text.len()` in both time and allocation. The predecessor built a
437	/// `Vec` with `String::split_off` per section, which re-copied the whole
438	/// remaining paragraph each time *and* left every emitted section carrying the
439	/// capacity of that paragraph: a 16 MiB paragraph with no blank line cost
440	/// 16.3 s and 65.6 GB peak RSS (issue #239). Sections are cut out of a window
441	/// that never exceeds `2 * SECTION_CHARS + 4` bytes, and the paragraph itself
442	/// stays borrowed from `text`.
443	pub fn for_each_section(text: &str, emit: &mut dyn FnMut(String) -> bool) -> bool {
444	    if text.len() <= SECTION_CHARS {
445	        return emit(text.to_string());
446	    }
447	    // One byte past the largest section the loop below will ever hold, so a
448	    // full window always trips the hard-split condition.
449	    let window = 2 * SECTION_CHARS + 1;
450	    let mut cur = String::new();
451	
452	    for para in text.split("\n\n") {
453	        if !cur.is_empty() && cur.len() + para.len() > SECTION_CHARS {
454	            let done = std::mem::take(&mut cur);
455	            let carry = tail(&done, SECTION_OVERLAP);
456	            if !emit(done) {
457	                return false;
458	            }
459	            if !carry.is_empty() {
460	                cur.push_str(&carry);
461	            }
462	        }
463	        if !cur.is_empty() {
464	            cur.push_str("\n\n");
465	        }
466	        // `rest` is the not-yet-buffered remainder of this paragraph, borrowed
467	        // from `text` — it is never copied wholesale into `cur`.
468	        let mut rest = para;
469	        loop {
470	            fill_window(&mut cur, &mut rest, window);
471	            // Identical test to the old `while cur.len() > 2 * SECTION_CHARS`,
472	            // where `cur` was the whole `cur ++ rest` concatenation.
473	            if cur.len() + rest.len() <= 2 * SECTION_CHARS {
474	                break;
475	            }
476	            let cut = ceil_boundary(&cur, SECTION_CHARS);
477	            let section = cur[..cut].to_string();
478	            cur.drain(..cut);
479	            if !emit(section) {
480	                return false;
481	            }
482	        }
483	    }
484	    if !cur.trim().is_empty() {
485	        return emit(cur);
486	    }
487	    true
488	}
489	
490	/// Collecting wrapper over [`for_each_section`], for callers that need every
491	/// section at once. Prefer the streaming form for whole-file bodies.
492	pub fn split_sections(text: &str) -> Vec<String> {
493	    let mut out: Vec<String> = Vec::new();
494	    for_each_section(text, &mut |s| {
495	        out.push(s);
496	        true
497	    });
498	    out
499	}
500	
501	fn section_record(
502	    title: &str,
503	    headings: &[String],
504	    i: usize,
505	    multi: bool,
506	    section: String,
507	) -> RawRecord {
508	    let mut fields = Map::new();
509	    fields.insert("title".into(), Value::String(title.to_string()));
510	    if !headings.is_empty() {
511	        fields.insert(
512	            "headings".into(),
513	            Value::Array(headings.iter().map(|h| Value::String(h.clone())).collect()),
514	        );
515	    }
516	    if multi {
517	        fields.insert("section".into(), Value::Number((i as u64).into()));
518	    }
519	    fields.insert("body".into(), Value::String(section));
520	    RawRecord {
521	        fields,
522	        locator: format!("s{i}"),
523	        group: None,
524	        // title/headings/section/body are this function's vocabulary, and
525	        // `headings`/`section` come and go — never a clustering key.
526	        origin: FieldOrigin::Extractor,
527	    }
528	}
529	
530	/// Emit a document (title/body/headings) as one or more section records.
531	///
532	/// Streams: sections are cut one at a time, so a sink that stops early (phase-A
533	/// `--sample`) stops the split too instead of paying for the whole body first.
534	pub fn emit_document(
535	    title: &str,
536	    headings: &[String],
537	    body: &str,
538	    max_records: usize,
539	    sink: Sink,
540	    stats: &mut ExtractStats,
541	) -> bool {
542	    // One section of lookahead: the `section` field is only present when the
543	    // document actually splits, which is not known until a second one arrives.
544	    let mut pending: Option<String> = None;
545	    let mut next: usize = 0;
546	    let mut alive = true;
547	    for_each_section(body, &mut |sec| {
548	        let Some(prev) = pending.replace(sec) else {
549	            return true;
550	        };
551	        // #381: bound noise from a misclassified payload. Stopping the split
552	        // (not just the sink) also stops paying to section the rest of the body.
553	        if next >= max_records {
554	            stats.truncated = true;
555	            return false;
556	        }
557	        let i = next;
558	        next += 1;
559	        stats.records += 1;
560	        alive = sink(section_record(title, headings, i, true, prev));
561	        alive
562	    });
563	    // A sink that stopped early (sampling) sets `alive = false`; the cap leaves
564	    // it true and sets `truncated` instead. Distinguish so a capped run still
565	    // reports success and does NOT emit the over-cap `pending` tail section.
566	    if !alive {
567	        return false;
568	    }
569	    if stats.truncated {
570	        return true;
571	    }
572	    match pending {
573	        Some(last) => {
574	            if next >= max_records {
575	                stats.truncated = true;
576	                return true;
577	            }
578	            stats.records += 1;
579	            sink(section_record(title, headings, next, next > 0, last))
580	        }
581	        None => true,
582	    }
