585	/// [`emit_document`] for a document that carries FIELDS of its own: emit `body`
586	/// as one or more section records, each stamped with `base_fields` (an email's
587	/// headers, an attachment's link-back fields, a note's labels) plus
588	/// `title`/`body`/`section`. Locators are `{loc_prefix}-s{i}`.
589	///
590	/// Returns the sink's last answer: `false` = stop extracting.
591	pub(crate) fn emit_document_with_fields(
592	    base_fields: &Map<String, Value>,
593	    title: &str,
594	    body: &str,
595	    loc_prefix: &str,
596	    sink: Sink,
597	    stats: &mut ExtractStats,
598	) -> bool {
599	    // Collect sections first so we know whether to stamp a `section` field.
600	    // One past the cap is collected so that "exactly at the cap" and "over the
601	    // cap" are distinguishable: only the latter dropped anything (#381).
602	    let mut secs: Vec<String> = Vec::new();
603	    for_each_section(body, &mut |s| {
604	        secs.push(s);
605	        secs.len() <= MAX_RECORDS_PER_FILE
606	    });
607	    if secs.len() > MAX_RECORDS_PER_FILE {
608	        secs.truncate(MAX_RECORDS_PER_FILE);
609	        stats.truncated = true;
610	    }
611	    if secs.is_empty() {
612	        secs.push(String::new());
613	    }
614	    let multi = secs.len() > 1;
615	    for (i, sec) in secs.into_iter().enumerate() {
616	        let mut fields = base_fields.clone();
617	        fields.insert("title".into(), Value::String(title.to_string()));
618	        fields.insert("body".into(), Value::String(sec));
619	        if multi {
620	            fields.insert("section".into(), Value::Number((i as u64).into()));
621	        }
622	        stats.records += 1;
623	        if !sink(RawRecord {
624	            fields,
625	            locator: format!("{loc_prefix}-s{i}"),
626	            group: None,
627	            origin: FieldOrigin::Extractor,
628	        }) {
629	            return false;
630	        }
631	    }
632	    true
633	}
