721	    /// The pre-#239 implementation, kept verbatim as an oracle. It is quadratic
722	    /// — only ever call it on inputs of a few hundred KB.
723	    fn legacy_split_sections(text: &str) -> Vec<String> {
724	        if text.len() <= SECTION_CHARS {
725	            return vec![text.to_string()];
726	        }
727	        let mut out: Vec<String> = Vec::new();
728	        let mut cur = String::new();
729	        for para in text.split("\n\n") {
730	            if !cur.is_empty() && cur.len() + para.len() > SECTION_CHARS {
731	                let done = std::mem::take(&mut cur);
732	                let carry = tail(&done, SECTION_OVERLAP);
733	                out.push(done);
734	                if !carry.is_empty() {
735	                    cur.push_str(&carry);
736	                }
737	            }
738	            if !cur.is_empty() {
739	                cur.push_str("\n\n");
740	            }
741	            cur.push_str(para);
742	            while cur.len() > 2 * SECTION_CHARS {
743	                let cut = cur
744	                    .char_indices()
745	                    .take_while(|(i, _)| *i < SECTION_CHARS)
746	                    .last()
747	                    .map(|(i, c)| i + c.len_utf8())
748	                    .unwrap_or(cur.len());
749	                let rest = cur.split_off(cut);
750	                out.push(std::mem::replace(&mut cur, rest));
751	            }
752	        }
753	        if !cur.trim().is_empty() {
754	            out.push(cur);
755	        }
756	        out
757	    }
