763	    fn matches_the_pre_fix_implementation_byte_for_byte() {
764	        let mut cases: Vec<String> = vec![
765	            String::new(),
766	            "one paragraph only".into(),
767	            "\n\n\n\n".into(),
768	            "   \n\n   ".into(),
769	            "z".repeat(SECTION_CHARS),
770	            "z".repeat(SECTION_CHARS + 1),
771	            "z".repeat(2 * SECTION_CHARS),
772	            "z".repeat(2 * SECTION_CHARS + 1),
773	            "z".repeat(10 * SECTION_CHARS),
774	            doc(200, 400),
775	            doc(60, 300),
776	            doc(3, 9000),
777	            // Multi-byte, with the cut landing inside a char: 3-byte and 4-byte
778	            // sequences do not divide SECTION_CHARS evenly.
779	            "é".repeat(4 * SECTION_CHARS),
780	            "设".repeat(4 * SECTION_CHARS),
781	            "🦀".repeat(4 * SECTION_CHARS),
782	            format!("{}{}", "a", "😀".repeat(3 * SECTION_CHARS)),
783	            format!("{}{}", "ab", "ا".repeat(3 * SECTION_CHARS)),
784	            // Mixed: paragraph path and hard-split path interleaved.
785	            format!(
786	                "{}\n\n{}\n\n{}",
787	                "x".repeat(300),
788	                "設定".repeat(2 * SECTION_CHARS),
789	                doc(5, 500)
790	            ),
791	        ];
792	        // Every offset around a section boundary, so an off-by-one in the cut
793	        // shows up.
794	        for d in 0..8usize {
795	            cases.push("q".repeat(2 * SECTION_CHARS + d));
796	            cases.push(format!(
797	                "{}{}",
798	                "w".repeat(d),
799	                "é".repeat(2 * SECTION_CHARS)
800	            ));
801	        }
802	        for t in &cases {
803	            assert_eq!(
804	                split_sections(t),
805	                legacy_split_sections(t),
806	                "section output diverged for a {}-byte input",
807	                t.len()
808	            );
809	        }
810	    }
