817	    fn section_capacity_tracks_content_not_input_size() {
818	        // ~1 MB as a single paragraph — no blank line anywhere.
819	        let text = "lorem ipsum dolor sit amet ".repeat((1 << 20) / 27 + 1);
820	        assert!(text.len() >= 1 << 20, "test input too small");
