42	const JOURNAL_FILESYSTEM_HEADROOM: u64 = 64 << 20;
43	// Preserve a base allowance for the journal/lock/model/runtime plus four
44	// descriptors per general and PDF worker for staging, sockets, and pipes.
45	const MIN_DESCRIPTOR_HEADROOM: u64 = 64;
46	const DESCRIPTOR_HEADROOM_PER_WORKER: u64 = 4;
