81	/// Run the isolated parser once and retain its bounded protocol response in an
82	/// anonymous, run-local file for Phase B.
83	///
84	/// The spool is deliberately not durable state. A process restart has a frozen
85	/// inference plan but no trusted open handle, so it parses the PDF again. This
86	/// avoids coupling extraction cache recovery to the publication journal.
87	pub(crate) fn extract_and_spool(
88	    path: &Path,
89	    state_dir: &Path,
90	    source_size: u64,
91	    source_digest: &str,
92	    budget: &Arc<ExtractionSpoolBudget>,
93	    sink: Sink,
94	) -> Result<(ExtractStats, Option<ExtractionSpool>, Option<SpoolFallback>)> {
95	    let _permit = worker_gate().acquire();
96	    let response = spawn_worker(path)?;
97	    // Counted only once the worker has produced a usable protocol response.
98	    // An invocation that spawned and then failed, timed out, or was killed is
99	    // deliberately excluded — hence `..._responses` and not `..._calls` in the
100	    // report. Total parser *invocations* are not a number this counter can
101	    // honestly supply.
102	    budget.record_phase_a_parse();
103	    let (spool, fallback) =
104	        try_spool_response(state_dir, source_size, source_digest, budget, &response);
105	    let stats = deliver(response, sink);
106	    Ok((stats, spool, fallback))
107	}
