109	pub(crate) struct SpoolFallback {
110	    pub(crate) category: &'static str,
111	    pub(crate) message: String,
112	}
113	
114	fn try_spool_response(
115	    state_dir: &Path,
116	    source_size: u64,
117	    source_digest: &str,
118	    budget: &Arc<ExtractionSpoolBudget>,
119	    response: &WorkerResponse,
120	) -> (Option<ExtractionSpool>, Option<SpoolFallback>) {
121	    let reservation = budget.try_reserve(MAX_WORKER_OUTPUT as u64);
122	    match reservation {
123	        Ok(reservation) => {
124	            match spool_response(state_dir, source_size, source_digest, response, reservation) {
125	                Ok(spool) => {
126	                    budget.record_artifact_accepted(spool.bytes);
127	                    (Some(spool), None)
128	                }
129	                Err(error) => {
130	                    budget.record_io_fallback();
131	                    budget.record_fallback_category("artifact_io");
132	                    budget.record_artifact_rejected();
133	                    (
134	                        None,
135	                        Some(SpoolFallback {
136	                            category: "artifact_io",
137	                            message: format!(
138	                                "could not retain the run-local extraction artifact: {error:#}"
139	                            ),
140	                        }),
141	                    )
142	                }
143	            }
144	        }
145	        Err(category) => (
146	            {
147	                budget.record_artifact_rejected();
148	                budget.record_fallback_category(category);
149	                None
150	            },
151	            Some(SpoolFallback {
152	                category,
153	                message: format!(
154	                    "admission refused ({category}); snapshot headroom or the bounded {} MiB/{}-artifact ceiling would be exceeded",
155	                    budget.limit >> 20, budget.max_spools
156	                ),
157	            }),
158	        ),
159	    }
160	}
161	
162	fn spool_response(
163	    state_dir: &Path,
164	    source_size: u64,
165	    source_digest: &str,
166	    response: &WorkerResponse,
167	    mut reservation: ExtractionSpoolReservation,
168	) -> Result<ExtractionSpool> {
169	    validate_response_identity(response)?;
170	    let mut file = tempfile::tempfile_in(state_dir).with_context(|| {
171	        format!(
172	            "create anonymous PDF extraction spool under {}",
173	            state_dir.display()
174	        )
175	    })?;
176	    {
177	        let mut writer = BufWriter::new(&mut file);
178	        serde_json::to_writer(&mut writer, &response)
179	            .context("serialize validated PDF extraction spool")?;
180	        writer.flush().context("flush PDF extraction spool")?;
181	    }
182	    let bytes = file
183	        .stream_position()
184	        .context("measure PDF extraction spool")?;
185	    if bytes > MAX_WORKER_OUTPUT as u64 {
186	        return Err(anyhow!(
187	            "validated PDF extraction spool exceeded the {} MiB parent-memory safety limit",
188	            MAX_WORKER_OUTPUT >> 20
189	        ));
190	    }
191	    let artifact_digest = artifact_digest(&mut file, bytes)?;
192	    reservation.shrink_to(bytes);
193	    file.rewind().context("rewind PDF extraction spool")?;
194	    Ok(ExtractionSpool {
195	        file: Mutex::new(file),
196	        source_size,
197	        source_digest: source_digest.to_owned(),
198	        bytes,
199	        artifact_digest,
200	        _reservation: reservation,
201	    })
202	}
203	
204	fn artifact_digest(file: &mut File, bytes: u64) -> Result<u128> {
205	    file.rewind().context("rewind PDF extraction spool")?;
206	    let mut hash = Xxh3::new();
207	    let mut remaining = bytes;
208	    let mut buffer = [0u8; 64 * 1024];
209	    while remaining > 0 {
210	        let limit = usize::try_from(remaining.min(buffer.len() as u64))
211	            .context("size PDF extraction spool digest buffer")?;
212	        let read = file
213	            .read(&mut buffer[..limit])
214	            .context("read PDF extraction spool for digest")?;
215	        anyhow::ensure!(read > 0, "PDF extraction spool was truncated while hashing");
216	        hash.update(&buffer[..read]);
217	        remaining -= read as u64;
218	    }
219	    Ok(hash.digest128())
220	}
