307	    /// Derive an optimization budget from the resources shared with the
308	    /// correctness-critical journal, Phase-B staging files, HTTP sockets, and
309	    /// worker pipes. If either resource cannot preserve explicit headroom,
310	    /// admission is disabled and Phase B uses the existing safe reparse path.
311	    pub(crate) fn for_state_dir(
312	        state_dir: &Path,
313	        workers: usize,
314	        pdf_workers: usize,
315	        bulk_mb: usize,
316	    ) -> (Arc<Self>, Option<String>) {
317	        let available_bytes = match available_space_for(state_dir) {
318	            Ok(bytes) => bytes,
319	            Err(error) => {
320	                let mut budget = Self::new(0, 0);
321	                let inner = Arc::get_mut(&mut budget).expect("new budget has one owner");
322	                inner.capacity_status = "disabled";
323	                inner.capacity_reason = "free_space_probe_unavailable";
324	                return (
325	                    budget,
326	                    Some(format!(
327	                        "disabled because free space under {} could not be measured: {error}",
328	                        state_dir.display()
329	                    )),
330	                );
331	            }
332	        };
333	        let (descriptor_limit, open_descriptors) = descriptor_snapshot_for(state_dir);
334	        let capacity = derive_spool_capacity(
335	            available_bytes,
336	            descriptor_limit,
337	            open_descriptors,
338	            workers,
339	            pdf_workers,
340	            bulk_mb,
341	        );
342	        let warning = if capacity.bytes < MAX_WORKER_OUTPUT as u64 || capacity.handles == 0 {
343	            Some(format!(
344	                "disabled to preserve {} MiB filesystem and {} descriptor headroom \
345	                 ({} MiB free, descriptor limit {})",
346	                capacity.filesystem_headroom >> 20,
347	                capacity.descriptor_headroom,
348	                available_bytes >> 20,
349	                descriptor_limit
350	                    .map(|limit| limit.to_string())
351	                    .unwrap_or_else(|| "unavailable".into())
352	            ))
353	        } else if capacity.bytes < MAX_SPOOL_BYTES || capacity.handles < MAX_SPOOL_HANDLES {
354	            Some(format!(
355	                "limited to {} MiB and {} artifacts to preserve {} MiB filesystem and {} \
356	                 descriptor headroom",
357	                capacity.bytes >> 20,
358	                capacity.handles,
359	                capacity.filesystem_headroom >> 20,
360	                capacity.descriptor_headroom
361	            ))
362	        } else {
363	            None
364	        };
365	        let capacity_status = if capacity.bytes < MAX_WORKER_OUTPUT as u64 || capacity.handles == 0
366	        {
367	            "disabled"
368	        } else if capacity.bytes < MAX_SPOOL_BYTES || capacity.handles < MAX_SPOOL_HANDLES {
369	            "limited"
370	        } else {
371	            "enabled"
372	        };
373	        let capacity_reason = if descriptor_limit.is_none() || open_descriptors.is_none() {
374	            "descriptor_probe_unavailable"
375	        } else if capacity.bytes < MAX_WORKER_OUTPUT as u64 {
376	            "filesystem_headroom"
377	        } else if capacity.handles == 0 {
378	            "descriptor_headroom"
379	        } else if capacity_status == "limited" {
380	            "resource_share_limited"
381	        } else {
382	            "full_bounded_capacity"
383	        };
384	        let budget = Arc::new(Self {
385	            admission: Mutex::new(()),
386	            used: AtomicU64::new(0),
387	            spools: AtomicU64::new(0),
388	            limit: capacity.bytes,
389	            max_spools: capacity.handles,
390	            live_capacity: Some(LiveCapacity {
391	                state_dir: state_dir.to_owned(),
392	                filesystem_headroom: capacity.filesystem_headroom,
393	                descriptor_headroom: capacity.descriptor_headroom,
394	            }),
395	            reservations_started: AtomicU64::new(0),
396	            cumulative_reserved_bytes: AtomicU64::new(0),
397	            artifacts_created: AtomicU64::new(0),
398	            artifacts_not_created: AtomicU64::new(0),
399	            phase_b_eligible_artifacts: AtomicU64::new(0),
400	            artifacts_discarded_before_replay: AtomicU64::new(0),
401	            exact_artifact_bytes: AtomicU64::new(0),
402	            peak_retained_or_reserved_bytes: AtomicU64::new(0),
