424	    fn try_reserve(
425	        self: &Arc<Self>,
426	        bytes: u64,
427	    ) -> std::result::Result<ExtractionSpoolReservation, &'static str> {
428	        if let Some(live) = &self.live_capacity {
429	            let available = available_space_for(&live.state_dir).map_err(|_| {
430	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
431	                "free_space_probe_failed"
432	            })?;
433	            // `available` already excludes bytes occupied by retained spool
434	            // files; adding `used` again would double-count them.
435	            if available < live.filesystem_headroom.saturating_add(bytes) {
436	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
437	                return Err("filesystem_admission_floor");
438	            }
439	            let (Some(limit), Some(open)) = descriptor_snapshot_for(&live.state_dir) else {
440	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
441	                return Err("descriptor_probe_failed");
442	            };
443	            if open
444	                .saturating_add(live.descriptor_headroom)
445	                .saturating_add(1)
446	                > limit
447	            {
448	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
449	                return Err("descriptor_admission_floor");
450	            }
451	        }
452	        // Serialize the tiny accounting transition so a handle claim that is
453	        // subsequently rejected by the byte ceiling cannot inflate the
454	        // advertised live-artifact peak.
455	        let _admission = self.admission.lock().unwrap();
456	        let previous_spools = self
457	            .spools
458	            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |spools| {
459	                (spools < self.max_spools).then_some(spools + 1)
460	            })
461	            .map_err(|_| {
462	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
463	                "artifact_count_ceiling"
464	            })?;
465	        let mut used = self.used.load(Ordering::Acquire);
466	        loop {
467	            let Some(next) = used.checked_add(bytes) else {
468	                self.spools.fetch_sub(1, Ordering::AcqRel);
469	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
470	                return Err("byte_accounting_overflow");
471	            };
472	            if next > self.limit {
473	                self.spools.fetch_sub(1, Ordering::AcqRel);
474	                self.capacity_fallbacks.fetch_add(1, Ordering::Relaxed);
475	                return Err("byte_ceiling");
476	            }
477	            match self
478	                .used
479	                .compare_exchange_weak(used, next, Ordering::AcqRel, Ordering::Acquire)
480	            {
481	                Ok(_) => {
482	                    self.peak_live_artifacts
483	                        .fetch_max(previous_spools + 1, Ordering::Relaxed);
484	                    self.reservations_started.fetch_add(1, Ordering::Relaxed);
485	                    self.cumulative_reserved_bytes
486	                        .fetch_add(bytes, Ordering::Relaxed);
487	                    self.peak_retained_or_reserved_bytes
488	                        .fetch_max(next, Ordering::Relaxed);
489	                    return Ok(ExtractionSpoolReservation {
490	                        budget: Arc::clone(self),
491	                        bytes,
492	                        #[cfg(test)]
493	                        cleanup_probe: std::sync::atomic::AtomicBool::new(false),
494	                    });
495	                }
496	                Err(actual) => used = actual,
497	            }
498	        }
499	    }
