655	fn derive_spool_capacity(
656	    available_bytes: u64,
657	    descriptor_limit: Option<u64>,
658	    open_descriptors: Option<u64>,
659	    workers: usize,
660	    pdf_workers: usize,
661	    bulk_mb: usize,
662	) -> ExtractionSpoolCapacity {
663	    let workers = workers as u64;
664	    let pdf_workers = pdf_workers as u64;
665	    let bulk_bytes = (bulk_mb as u64).saturating_mul(1 << 20);
666	    let filesystem_headroom = MIN_FILESYSTEM_HEADROOM
667	        .max(available_bytes / 2)
668	        .max(JOURNAL_FILESYSTEM_HEADROOM.saturating_add(workers.saturating_mul(bulk_bytes)));
669	    let bytes = MAX_SPOOL_BYTES.min(available_bytes.saturating_sub(filesystem_headroom));
670	
671	    let descriptor_headroom = MIN_DESCRIPTOR_HEADROOM
672	        .saturating_add(workers.saturating_mul(DESCRIPTOR_HEADROOM_PER_WORKER))
673	        .saturating_add(pdf_workers.saturating_mul(DESCRIPTOR_HEADROOM_PER_WORKER));
674	    let handles = descriptor_limit
675	        .zip(open_descriptors)
676	        .map(|(limit, open)| {
677	            let live_cap = limit.saturating_sub(open.saturating_add(descriptor_headroom));
678	            MAX_SPOOL_HANDLES.min(live_cap)
679	        })
680	        .unwrap_or(0);
681	
682	    ExtractionSpoolCapacity {
683	        bytes,
684	        handles,
685	        filesystem_headroom,
686	        descriptor_headroom,
687	    }
688	}
