691	fn descriptor_soft_limit() -> Option<u64> {
692	    let mut limit = libc::rlimit {
693	        rlim_cur: 0,
694	        rlim_max: 0,
695	    };
696	    if unsafe { libc::getrlimit(libc::RLIMIT_NOFILE, &mut limit) } != 0 {
697	        return None;
698	    }
699	    if limit.rlim_cur == libc::RLIM_INFINITY {
700	        Some(u64::MAX)
701	    } else {
702	        Some(limit.rlim_cur)
703	    }
704	}
