732	impl ExtractionSpoolReservation {
733	    fn shrink_to(&mut self, bytes: u64) {
734	        debug_assert!(bytes <= self.bytes);
735	        let released = self.bytes - bytes;
736	        self.bytes = bytes;
737	        let previous = self.budget.used.fetch_sub(released, Ordering::AcqRel);
738	        debug_assert!(previous >= released);
739	    }
740	}
741	
742	impl Drop for ExtractionSpoolReservation {
743	    fn drop(&mut self) {
744	        let previous = self.budget.used.fetch_sub(self.bytes, Ordering::AcqRel);
745	        debug_assert!(previous >= self.bytes);
746	        let previous_spools = self.budget.spools.fetch_sub(1, Ordering::AcqRel);
747	        debug_assert!(previous_spools > 0);
748	        #[cfg(test)]
749	        if self.cleanup_probe.load(Ordering::SeqCst) {
750	            CORRUPTED_REPLAY_RESERVATION_DROPPED.store(true, Ordering::SeqCst);
751	        }
752	    }
753	}
