755	/// A validated worker response bound to one inventory generation.
756	///
757	/// `File` is anonymous and the mutex owns its single seek cursor. Phase A and
758	/// Phase B are sequential today, but cursor ownership remains explicit rather
759	/// than relying on cloned Unix file descriptors with shared offsets.
760	pub(crate) struct ExtractionSpool {
761	    file: Mutex<File>,
762	    source_size: u64,
763	    source_digest: String,
764	    bytes: u64,
765	    artifact_digest: u128,
766	    _reservation: ExtractionSpoolReservation,
767	}
768	
769	impl ExtractionSpool {
770	    /// Verify and deliver the retained response exactly once.
771	    ///
772	    /// Four checks can fail against a caller that routed the right artifact to
773	    /// the right file: the artifact's physical length, its content digest, its
774	    /// JSON decode, and the worker protocol identity inside it. The
775	    /// `source_size`/`source_digest` comparison below is a fifth check of a
776	    /// different kind — a binding assertion. Phase B derives both values from
777	    /// the same inventory entry that Phase A spooled under, so at the
778	    /// production call site it can only fire if an artifact were routed to the
779	    /// wrong file. Mutation of the *source* between phases is caught earlier
780	    /// and with full strength by the `content::verify` call that Phase B runs
781	    /// before extraction (`lib.rs`), not here.
782	    pub(crate) fn replay(
783	        self,
784	        source_size: u64,
785	        source_digest: &str,
786	        sink: Sink,
787	    ) -> Result<ExtractStats> {
788	        self.replay_with_gate(source_size, source_digest, sink, worker_gate())
789	    }
790	
791	    fn replay_with_gate(
792	        self,
793	        source_size: u64,
794	        source_digest: &str,
795	        sink: Sink,
796	        gate: &WorkerGate,
797	    ) -> Result<ExtractStats> {
798	        // JSON decoding materializes a bounded WorkerResponse just like the
799	        // parser protocol. Share the PDF gate so Phase B cannot multiply that
800	        // 32 MiB response bound by the general autoindex worker count.
801	        let _permit = gate.acquire();
802	        let ExtractionSpool {
803	            file,
804	            source_size: expected_size,
805	            source_digest: expected_digest,
806	            bytes,
807	            artifact_digest: expected_artifact_digest,
808	            _reservation: reservation,
809	        } = self;
810	        let budget = Arc::clone(&reservation.budget);
811	        let decoded = (|| -> Result<WorkerResponse> {
812	            // Binding assertion, not a source-mutation check — see `replay`.
813	            anyhow::ensure!(
814	                source_size == expected_size && source_digest == expected_digest,
815	                "PDF extraction spool belongs to a different source generation; retry extraction"
816	            );
817	            let mut file = file
818	                .into_inner()
819	                .map_err(|_| anyhow!("PDF extraction spool lock was poisoned"))?;
820	            #[cfg(test)]
821	            if CORRUPT_REPLAY_SOURCE_SIZE
822	                .compare_exchange(source_size, u64::MAX, Ordering::SeqCst, Ordering::SeqCst)
823	                .is_ok()
824	            {
825	                reservation.cleanup_probe.store(true, Ordering::SeqCst);
826	                file.set_len(8)
827	                    .context("inject PDF extraction spool truncation")?;
828	            }
829	            let actual_bytes = file
830	                .metadata()
831	                .context("measure PDF extraction spool before replay")?
832	                .len();
833	            anyhow::ensure!(
834	                actual_bytes == bytes,
835	                "PDF extraction spool length changed (expected {}, found {}); retry extraction",
836	                bytes,
837	                actual_bytes
838	            );
839	            let actual_digest = artifact_digest(&mut file, bytes)?;
840	            anyhow::ensure!(
841	                actual_digest == expected_artifact_digest,
842	                "PDF extraction spool content changed; retry extraction"
843	            );
844	            file.rewind().context("rewind PDF extraction spool")?;
845	            let response: WorkerResponse = serde_json::from_reader(BufReader::new(&mut file))
846	                .context("PDF extraction spool is malformed or truncated; retry extraction")?;
847	            validate_response_identity(&response)?;
848	            Ok(response)
849	        })();
850	        // The optional artifact and its reservation are gone before `deliver`
851	        // can expand records into the unbounded correctness-critical stage.
852	        // Replay is deliberately one-shot.
853	        drop(reservation);
854	        match decoded {
855	            Ok(response) => {
856	                budget.replay_verified.fetch_add(1, Ordering::Relaxed);
857	                Ok(deliver(response, sink))
858	            }
859	            Err(error) => {
860	                budget
861	                    .replay_integrity_failures
862	                    .fetch_add(1, Ordering::Relaxed);
863	                Err(error)
864	            }
865	        }
866	    }
867	}
868	
869	fn deliver(response: WorkerResponse, sink: Sink) -> ExtractStats {
870	    let mut stats = ExtractStats::default();
871	    for record in response.records {
872	        stats.records += 1;
873	        if !sink(record) {
874	            break;
875	        }
876	    }
877	    stats
878	}
