897	/// Hidden same-binary worker entry point. One invocation parses one document.
898	pub fn run_worker_cli() -> i32 {
899	    let mut args = std::env::args_os().skip(2);
900	    let Some(path) = args.next().map(PathBuf::from) else {
901	        eprintln!("PDF worker protocol error: missing input path");
902	        return 2;
903	    };
904	    if args.next().is_some() {
905	        eprintln!("PDF worker protocol error: unexpected arguments");
906	        return 2;
907	    }
908	    match extract_in_process(&path) {
909	        Ok(records) => {
910	            let response = WorkerResponse {
911	                schema: 1,
912	                extractor: format!("xerj-autoindex/{}", env!("CARGO_PKG_VERSION")),
913	                parser: format!("pdf_oxide/{}", pdf_oxide::VERSION),
914	                containment: containment_description().to_string(),
915	                records,
916	            };
917	            let result = (|| -> Result<()> {
918	                let mut stdout = std::io::stdout().lock();
919	                serde_json::to_writer(&mut stdout, &response)?;
920	                stdout.flush()?;
921	                Ok(())
922	            })();
923	            if let Err(error) = result {
924	                eprintln!("PDF worker could not write its bounded result: {error}");
925	                return 1;
926	            }
927	            0
928	        }
929	        Err(error) => {
930	            eprintln!("{error:#}");
931	            1
932	        }
933	    }
934	}
