936	fn spawn_worker(path: &Path) -> Result<WorkerResponse> {
937	    // Trusted developer/test hook. The selected executable runs with the
938	    // invoking user's authority and must implement this private protocol.
939	    let executable = std::env::var_os("XERJ_PDF_WORKER_BIN")
940	        .map(PathBuf::from)
941	        .or_else(|| std::env::current_exe().ok())
942	        .context("cannot locate the xerj executable for isolated PDF extraction")?;
943	    let mut command = Command::new(executable);
944	    command
945	        .arg("__extract-pdf")
946	        .arg(path)
947	        .stdin(Stdio::null())
948	        .stdout(Stdio::piped())
949	        .stderr(Stdio::piped());
950	    set_worker_memory_limit(&mut command);
951	    let mut child = command.spawn().with_context(|| {
952	        format!(
953	            "could not start the isolated PDF parser for {}; check process/resource limits",
954	            path.display()
955	        )
956	    })?;
957	    let stdout = child.stdout.take().expect("piped stdout");
958	    let stderr = child.stderr.take().expect("piped stderr");
959	    let out_reader = std::thread::spawn(move || read_capped(stdout, MAX_WORKER_OUTPUT));
960	    let err_reader = std::thread::spawn(move || read_capped(stderr, MAX_WORKER_STDERR as usize));
961	
962	    let started = Instant::now();
963	    let timeout = Duration::from_secs(WORKER_TIMEOUT_SECS.load(Ordering::Relaxed));
964	    let status = loop {
965	        match child.try_wait() {
966	            Ok(Some(status)) => break status,
967	            Ok(None) => {}
968	            Err(error) => {
969	                terminate_worker_tree(&mut child);
970	                let _ = out_reader.join();
971	                let _ = err_reader.join();
972	                return Err(error).with_context(|| {
973	                    format!("could not monitor PDF parser for {}", path.display())
974	                });
975	            }
976	        }
977	        if started.elapsed() >= timeout {
978	            terminate_worker_tree(&mut child);
979	            let _ = out_reader.join();
980	            let _ = err_reader.join();
981	            return Err(anyhow!(
982	                "PDF extraction timed out after {} seconds for {}; repair/split the PDF, or run OCR if it is image-only",
983	                timeout.as_secs(),
984	                path.display()
985	            ));
986	        }
987	        std::thread::sleep(Duration::from_millis(20));
988	    };
989	    terminate_worker_descendants(child.id());
990	    let stdout = out_reader
991	        .join()
992	        .map_err(|_| anyhow!("PDF parser output reader panicked"))??;
993	    let stderr = err_reader
994	        .join()
995	        .map_err(|_| anyhow!("PDF parser error reader panicked"))??;
996	    if stdout.overflow {
997	        return Err(anyhow!(
998	            "PDF parser output exceeded the {} MiB parent-memory safety limit for {}; split the document before indexing",
999	            MAX_WORKER_OUTPUT >> 20,
1000	            path.display()
1001	        ));
1002	    }
1003	    if stderr.overflow {
1004	        return Err(anyhow!(
1005	            "PDF parser error output exceeded the {} KiB safety limit for {}; the worker was excessively noisy and its truncated diagnostic is: {}",
1006	            MAX_WORKER_STDERR >> 10,
1007	            path.display(),
1008	            String::from_utf8_lossy(&stderr.prefix)
1009	        ));
1010	    }
1011	    let stderr = String::from_utf8_lossy(&stderr.prefix);
1012	    if !status.success() {
1013	        return Err(anyhow!(
1014	            "isolated PDF parser failed for {}{}{}; verify/decrypt the PDF, repair it, or run OCR for image-only input",
1015	            path.display(),
1016	            if stderr.trim().is_empty() { "" } else { ": " },
1017	            stderr.trim()
1018	        ));
1019	    }
1020	    let response: WorkerResponse = serde_json::from_slice(&stdout.prefix).with_context(|| {
1021	        format!(
1022	            "isolated PDF parser returned an invalid result for {}; this is an internal worker-protocol error",
1023	            path.display()
1024	        )
1025	    })?;
1026	    validate_response_identity(&response)?;
1027	    Ok(response)
