1055	struct CappedRead {
1056	    prefix: Vec<u8>,
1057	    overflow: bool,
1058	}
1059	
1060	fn read_capped(mut input: impl Read, cap: usize) -> Result<CappedRead> {
1061	    let mut prefix = Vec::with_capacity(cap.min(64 << 10));
1062	    let mut overflow = false;
1063	    let mut chunk = [0u8; 64 << 10];
1064	    loop {
1065	        let read = input
1066	            .read(&mut chunk)
1067	            .context("could not read isolated PDF parser output")?;
1068	        if read == 0 {
1069	            break;
1070	        }
1071	        let remaining = cap.saturating_sub(prefix.len());
1072	        let retain = remaining.min(read);
1073	        prefix.extend_from_slice(&chunk[..retain]);
1074	        overflow |= retain < read;
1075	        // Keep draining after overflow so the child can exit instead of
1076	        // blocking forever on a full pipe.
1077	    }
1078	    Ok(CappedRead { prefix, overflow })
1079	}
