1139	fn extract_in_process(path: &Path) -> Result<Vec<RawRecord>> {
1140	    let size = std::fs::metadata(path)?.len();
1141	    if size > PDF_CAP {
1142	        return Err(anyhow!(
1143	            "PDF is {:.1} MiB, above the 512 MiB safety limit; split or compress it before indexing",
1144	            size as f64 / (1 << 20) as f64
1145	        ));
1146	    }
1147	
1148	    pdf_oxide::fonts::global_cache::clear_global_font_cache();
1149	    let doc = PdfDocument::open(path).with_context(|| {

1150	        "PDF parser could not open the document; verify/repair damaged input, decrypt password-protected input, or run OCR for image-only input"
1151	    })?;
1152	    let pages = doc.page_count().with_context(|| {
1153	        "PDF parser could not read the page tree; verify the file or decrypt it first"
1154	    })?;
1155	    if pages == 0 {
1156	        return Err(anyhow!("PDF contains no pages"));
1157	    }
1158	    if pages > MAX_PAGES {
1159	        return Err(anyhow!(
1160	            "PDF declares {pages} pages, above the {MAX_PAGES}-page safety limit; split it before indexing"
1161	        ));
1162	    }
1163	
1164	    let title = path
1165	        .file_stem()
1166	        .map(|s| s.to_string_lossy().into_owned())
1167	        .filter(|s| !s.trim().is_empty())
1168	        .unwrap_or_else(|| "untitled".to_string());
1169	    let mut records = Vec::new();
1170	    let mut extracted_bytes = 0usize;
1171	    let mut failed_pages = Vec::new();
1172	    let mut omitted_pages = Vec::new();
1173	    let mut pages_with_text = 0usize;
1174	
1175	    for page_index in 0..pages {
1176	        let page = match doc.extract_text(page_index) {
1177	            Ok(text) => text,
1178	            Err(error) => {
1179	                failed_pages.push(format!("{} ({error})", page_index + 1));
1180	                continue;
1181	            }
1182	        };
1183	        let page = normalize_legacy_symbol_glyphs(&page);
1184	        let body = page.trim();
1185	        if body.is_empty() {
1186	            omitted_pages.push(page_index + 1);
1187	            continue;
1188	        }
1189	        if body.len() > MAX_PAGE_TEXT {
1190	            return Err(anyhow!(
1191	                "PDF page {} produced more than 16 MiB of text; split or repair the document before indexing",
1192	                page_index + 1
1193	            ));
1194	        }
1195	        if body.chars().filter(|ch| !ch.is_whitespace()).count() < 8 {
1196	            omitted_pages.push(page_index + 1);
1197	            continue;
1198	        }
1199	        validate_text_quality(body).with_context(|| {
1200	            format!(
1201	                "PDF page {} produced untrusted text; refusing to index possible binary/font garbage",
1202	                page_index + 1
1203	            )
1204	        })?;
1205	        extracted_bytes = extracted_bytes.saturating_add(body.len());
1206	        pages_with_text += 1;
1207	        if extracted_bytes > MAX_EXTRACTED_TEXT {
1208	            return Err(anyhow!(
1209	                "PDF extraction exceeded the 64 MiB text safety limit; split the document before indexing"
1210	            ));
1211	        }
1212	
1213	        for (section, text) in split_sections(body).into_iter().enumerate() {
1214	            let mut fields = Map::new();
1215	            fields.insert("title".into(), Value::String(title.clone()));
1216	            fields.insert(
1217	                "page".into(),
1218	                Value::Number(((page_index + 1) as u64).into()),
1219	            );
1220	            if section > 0 {
1221	                fields.insert("section".into(), Value::Number((section as u64).into()));
1222	            }
1223	            fields.insert("body".into(), Value::String(text));
1224	            records.push(RawRecord {
1225	                fields,
1226	                locator: format!("p{}-s{}", page_index + 1, section),
1227	                group: None,
1228	                // title/page/section/body plus the pdf_* counters are this
1229	                // extractor's vocabulary; `section` and `pdf_ocr_warning`
1230	                // appear only sometimes.
1231	                origin: FieldOrigin::Extractor,
1232	            });
1233	        }
1234	    }
1235	
1236	    if records.is_empty() {
1237	        if failed_pages.is_empty() {
1238	            return Err(anyhow!(
1239	                "PDF has no extractable text; it may be an image-only scan. Run OCR first, then autoindex the searchable PDF"
1240	            ));
1241	        }
1242	        return Err(anyhow!(
1243	            "PDF text extraction failed on every non-empty page ({}); verify/decrypt the PDF or run OCR before indexing",
1244	            failed_pages.iter().take(3).cloned().collect::<Vec<_>>().join(", ")
1245	        ));
1246	    }
1247	    if !failed_pages.is_empty() {
1248	        return Err(anyhow!(
1249	            "PDF extraction failed on {}/{} pages (first failures: {}); refusing a partial index. Repair/decrypt the PDF or run OCR first",
1250	            failed_pages.len(),
1251	            pages,
1252	            failed_pages.iter().take(3).cloned().collect::<Vec<_>>().join(", ")
1253	        ));
1254	    }
1255	    for record in &mut records {
1256	        record.fields.insert(
1257	            "pdf_pages_total".into(),
1258	            Value::Number((pages as u64).into()),
1259	        );
1260	        record.fields.insert(
1261	            "pdf_pages_with_text".into(),
1262	            Value::Number((pages_with_text as u64).into()),
1263	        );
1264	        record.fields.insert(
1265	            "pdf_pages_omitted".into(),
1266	            Value::Number((omitted_pages.len() as u64).into()),
1267	        );
1268	        if !omitted_pages.is_empty() {
1269	            record.fields.insert(
1270	                "pdf_ocr_warning".into(),
1271	                Value::String(format!(
1272	                    "{} page(s) had no usable text (first: {}); intentional blanks or scanned pages may need OCR",
1273	                    omitted_pages.len(),
1274	                    omitted_pages
1275	                        .iter()
1276	                        .take(8)
1277	                        .map(usize::to_string)
1278	                        .collect::<Vec<_>>()
1279	                        .join(", ")
1280	                )),
1281	            );
1282	        }
1283	    }
1284	    Ok(records)
1285	}
