1287	struct WorkerGate {
1288	    state: Mutex<(usize, usize)>,
1289	    ready: Condvar,
1290	}
1291	
1292	impl WorkerGate {
1293	    /// `limit` is the width the resource policy decided
1294	    /// (`crate::resources::plan`), already range-checked at the CLI — it is
1295	    /// taken as given, not re-clamped against a second opinion. Only zero is
1296	    /// corrected, because a gate of width 0 parks every parser forever.
1297	    fn new(limit: usize) -> Self {
1298	        Self {
1299	            state: Mutex::new((0, limit.max(1))),
1300	            ready: Condvar::new(),
1301	        }
1302	    }
1303	
1304	    fn set_limit(&self, limit: usize) {
1305	        self.state.lock().expect("PDF worker gate poisoned").1 = limit;
1306	        self.ready.notify_all();
1307	    }
1308	
1309	    fn acquire(&self) -> WorkerPermit<'_> {
1310	        let mut state = self.state.lock().expect("PDF worker gate poisoned");
1311	        while state.0 >= state.1 {
1312	            state = self.ready.wait(state).expect("PDF worker gate poisoned");
1313	        }
1314	        state.0 += 1;
1315	        WorkerPermit(self)
1316	    }
1317	}
1318	
1319	struct WorkerPermit<'a>(&'a WorkerGate);
1320	
1321	impl Drop for WorkerPermit<'_> {
1322	    fn drop(&mut self) {
1323	        let mut state = self.0.state.lock().expect("PDF worker gate poisoned");
1324	        state.0 -= 1;
1325	        self.0.ready.notify_one();
1326	    }
1327	}
