1329	fn worker_gate() -> &'static WorkerGate {
1330	    static GATE: OnceLock<WorkerGate> = OnceLock::new();
1331	    GATE.get_or_init(|| {
1332	        // Default only: `configure_workers` overwrites this with the run's
1333	        // plan (`crate::resources::plan`) before any extraction starts.
1334	        WorkerGate::new(xerj_common::resource::cores().min(crate::resources::MAX_PDF_WORKERS))
1335	    })
1336	}
