1338	fn normalize_legacy_symbol_glyphs(text: &str) -> String {
1339	    text.chars()
1340	        .map(|ch| match ch {
1341	            '\u{f0b7}' => '•',
1342	            '\u{f02d}' => '-',
1343	            '\u{f078}' | '\u{f0a8}' | '\u{f06f}' | '\u{f052}' | '\u{f0a3}' | '\u{f020}' => '□',
1344	            '\u{f0d2}' | '\u{f0d4}' | '\u{f0be}' => ' ',
1345	            other => other,
1346	        })
1347	        .collect()
1348	}
