1350	fn validate_text_quality(text: &str) -> Result<()> {
1351	    // Fail closed rather than embed broken font codes. On the pinned
1352	    // 368-document FinanceBench PDF corpus this 0.5% threshold accepted 367
1353	    // documents and rejected one; keep that false-rejection cost visible when
1354	    // recalibrating against broader labeled corpora.
1355	    let mut visible = 0usize;
1356	    let mut semantic = 0usize;
1357	    let mut suspicious = 0usize;
1358	    for ch in text.chars() {
1359	        if ch.is_whitespace() {
1360	            continue;
1361	        }
1362	        visible += 1;
1363	        if ch.is_alphanumeric() {
1364	            semantic += 1;
1365	        }
1366	        if ch == '\u{fffd}'
1367	            || ch.is_control()
1368	            || ('\u{e000}'..='\u{f8ff}').contains(&ch)
1369	            || ('\u{f0000}'..='\u{ffffd}').contains(&ch)
1370	            || ('\u{100000}'..='\u{10fffd}').contains(&ch)
1371	        {
1372	            suspicious += 1;
1373	        }
1374	    }
1375	    if visible < 8 {
1376	        return Err(anyhow!("too little visible text"));
1377	    }
1378	    if suspicious * 200 > visible {
1379	        return Err(anyhow!(
1380	            "more than 0.5% of visible characters are controls, replacement glyphs, or private-use codes"
1381	        ));
1382	    }
1383	    if semantic * 20 < visible {
1384	        return Err(anyhow!(
1385	            "fewer than 5% of visible characters are letters or numbers"
1386	        ));
1387	    }
1388	    Ok(())
1389	}
