1	//! DOCX — zip container, `word/document.xml` streamed through quick-xml.
2	//! Collects w:t runs, breaks paragraphs on w:p, records Heading-styled
3	//! paragraphs as headings. One document record (sectioned at 32KB).
4	
5	use super::{emit_document, ExtractStats, Sink, MAX_RECORDS_PER_FILE};
6	use anyhow::{Context, Result};
7	use quick_xml::events::Event;
8	use quick_xml::Reader;
9	use std::io::BufReader;
10	use std::path::Path;
11	
12	// SECURITY: bound the DECOMPRESSED read. `word/document.xml` inflates from
13	// the zip at whatever ratio the author chose — a ~400 KB docx can expand to
14	// hundreds of MB, and a single 400 MB `<w:t>` text run makes quick-xml
15	// allocate that whole run for one event (measured 1.68 GB RSS from an 815 KB
16	// file). Reading through a `Take` caps peak memory no matter the ratio; a
17	// real document's document.xml is far below this. Past the cap the reader
18	// hits EOF and the loop ends; quick-xml reports that as `Eof`, not an error,
19	// so the paragraphs read so far are emitted and the remainder is dropped
20	// silently — truncation is not counted as junk.
21	const MAX_DECOMPRESSED_BYTES: u64 = 72 << 20;
22	
23	/// Extraction body cap (also bounds any single paragraph — see the Text arm).
24	const MAX_BODY_BYTES: usize = 64 << 20;
25	
26	pub fn extract(path: &Path, sink: Sink) -> Result<ExtractStats> {
27	    extract_bounded(path, sink, MAX_DECOMPRESSED_BYTES, MAX_BODY_BYTES)
28	}
29	
30	/// Both caps are parameters so the truncation boundaries can be exercised with
31	/// kilobyte fixtures; production always passes the two constants above.
32	fn extract_bounded(
33	    path: &Path,
34	    sink: Sink,
35	    max_decompressed_bytes: u64,
36	    max_body_bytes: usize,
37	) -> Result<ExtractStats> {
38	    let mut stats = ExtractStats::default();
39	    let f = std::fs::File::open(path)?;
40	    let mut z = zip::ZipArchive::new(f).context("open docx container")?;
41	    let entry = match z.by_name("word/document.xml") {
42	        Ok(e) => e,
43	        Err(_) => {
44	            stats.junk += 1;
45	            return Ok(stats);
46	        }
47	    };
48	    let capped = std::io::Read::take(entry, max_decompressed_bytes);
49	    let mut reader = Reader::from_reader(BufReader::new(capped));
50	    reader.config_mut().trim_text(false);
51	
52	    let mut body = String::new();
53	    let mut headings: Vec<String> = Vec::new();
54	    let mut para = String::new();
55	    let mut para_is_heading = false;
56	    let mut buf = Vec::new();
57	    loop {
58	        match reader.read_event_into(&mut buf) {
59	            Ok(Event::Start(e)) | Ok(Event::Empty(e)) => {
60	                let name = e.name();
61	                let local = name.as_ref();
62	                if local == b"w:pStyle" {
63	                    for a in e.attributes().flatten() {
64	                        if a.key.as_ref() == b"w:val" {
65	                            let v = String::from_utf8_lossy(&a.value).to_string();
66	                            if v.to_lowercase().contains("heading")
67	                                || v.to_lowercase().contains("title")
68	                            {
69	                                para_is_heading = true;
70	                            }
71	                        }
72	                    }
73	                } else if local == b"w:br" || local == b"w:tab" {
74	                    para.push(' ');
75	                }
76	            }
77	            Ok(Event::Text(t)) => {
78	                // SECURITY: `para` only flushes into `body` (and gets length-
79	                // checked) at `</w:p>`. A crafted docx with a single never-closed
80	                // `<w:p>` — an 815 KB file whose document.xml inflates to
81	                // hundreds of MB inside one paragraph — otherwise grows `para`
82	                // without bound: measured 1.68 GB RSS from that 815 KB input.
83	                // Stop appending once one paragraph reaches the body cap; the
84	                // per-paragraph text a real document holds is far below it.
85	                if para.len() < max_body_bytes {
86	                    para.push_str(&t.xml10_content().unwrap_or_default());
87	                }
88	            }
89	            // quick-xml >= 0.38 emits `&amp;` and friends as their own event
90	            // instead of folding them into the neighbouring text, so a
91	            // paragraph containing an entity loses its `&`/`<`/`>` unless this
92	            // arm puts it back.
93	            Ok(Event::GeneralRef(r)) => {
94	                if para.len() < max_body_bytes {
95	                    if let Some(resolved) = super::xml_x::resolve_general_ref(&r) {
96	                        para.push_str(&resolved);
97	                    }
98	                }
99	            }
100	            Ok(Event::End(e)) => {
101	                if e.name().as_ref() == b"w:p" {
102	                    let text = para.trim().to_string();
103	                    if !text.is_empty() {
104	                        if para_is_heading {
105	                            headings.push(text.clone());
106	                        }
107	                        body.push_str(&text);
108	                        body.push_str("\n\n");
109	                    }
110	                    para.clear();
111	                    para_is_heading = false;
112	                }
113	            }
114	            Ok(Event::Eof) => break,
115	            Ok(_) => {}
116	            Err(_) => {
117	                stats.junk += 1;
118	                break;
119	            }
120	        }
121	        buf.clear();
122	        if body.len() > max_body_bytes {
123	            break;
124	        }
125	    }
126	    let body = body.trim();
127	    if body.is_empty() {
128	        stats.junk += 1;
129	        return Ok(stats);
130	    }
131	    let title = headings.first().cloned().unwrap_or_else(|| {
132	        body.lines()
133	            .find(|l| !l.trim().is_empty())
134	            .map(|l| l.trim().chars().take(200).collect())
135	            .unwrap_or_else(|| {
136	                path.file_stem()
137	                    .map(|s| s.to_string_lossy().to_string())
138	                    .unwrap_or_else(|| "untitled".into())
139	            })
140	    });
141	    emit_document(
142	        &title,
143	        &headings,
144	        body,
145	        MAX_RECORDS_PER_FILE,
146	        sink,
147	        &mut stats,
148	    );
149	    Ok(stats)
150	}
