164	    /// A docx is a zip; the extractor only ever looks at `word/document.xml`,
165	    /// so fixtures name their members explicitly.
166	    fn write_container(path: &Path, members: &[(&str, &str)]) {
167	        let mut z = zip::ZipWriter::new(std::fs::File::create(path).unwrap());
168	        let opts = zip::write::SimpleFileOptions::default()
169	            .compression_method(zip::CompressionMethod::Deflated);
170	        for (name, content) in members {
171	            z.start_file(*name, opts).unwrap();
172	            z.write_all(content.as_bytes()).unwrap();
173	        }
174	        z.finish().unwrap();
175	    }
176	
177	    fn write_docx(path: &Path, document_xml: &str) {
178	        write_container(path, &[("word/document.xml", document_xml)]);
179	    }
