181	    /// Section bodies in emission order, plus the stats the run reported.
182	    fn extract_sections(
183	        path: &Path,
184	        max_decompressed_bytes: u64,
185	        max_body_bytes: usize,
186	    ) -> (Vec<String>, ExtractStats) {
187	        let mut sections = Vec::new();
188	        let stats = extract_bounded(
189	            path,
190	            &mut |r| {
191	                sections.push(r.fields["body"].as_str().unwrap().to_string());
192	                true
193	            },
194	            max_decompressed_bytes,
195	            max_body_bytes,
196	        )
197	        .unwrap();
198	        (sections, stats)
199	    }
