207	    /// quick-xml >= 0.38 emits `&amp;` as its own `Event::GeneralRef` instead
208	    /// of folding it into the neighbouring `Event::Text`, so a reader that only
209	    /// handles `Event::Text` drops every ampersand, angle bracket and numeric
210	    /// character reference in the document — silently, since the surrounding
211	    /// words still arrive. This pins that they come back.
212	    #[test]
213	    fn entity_and_character_references_survive_extraction() {
214	        let xml = format!(
215	            "{XML_HEAD}{}{XML_TAIL}",
216	            r#"<w:p><w:r><w:t>Ben &amp; Jerry &lt;tag&gt; caf&#233;</w:t></w:r></w:p>"#
217	        );
218	        let dir = tempfile::tempdir().unwrap();
219	        let path = dir.path().join("entities.docx");
220	        write_docx(&path, &xml);
221	
222	        let (sections, stats) = extract_sections(&path, 1 << 20, 1 << 20);
223	        assert_eq!(stats.junk, 0);
224	        assert_eq!(
225	            sections.concat().trim(),
226	            "Ben & Jerry <tag> café",
227	            "entity and numeric character references must resolve, and the text \
228	             around them must not be re-split or lose its spaces"
229	        );
