232	    #[test]
233	    fn a_document_inflating_past_the_decompression_cap_is_truncated_at_the_byte_boundary() {
234	        const PARAS: usize = 20_000;
235	        // Repetitive filler is what gives a docx its inflation ratio; the
236	        // per-paragraph marker keeps every paragraph the same width.
237	        let para = |i: usize| {
238	            format!(
239	                "<w:p><w:r><w:t>{} {}</w:t></w:r></w:p>",
240	                marker(i),
241	                "filler ".repeat(24)
242	            )
243	        };
244	        let xml = format!(
245	            "{XML_HEAD}{}{XML_TAIL}",
246	            (0..PARAS).map(para).collect::<String>()
247	        );
248	
249	        let dir = tempfile::tempdir().unwrap();
250	        let path = dir.path().join("bomb.docx");
251	        write_docx(&path, &xml);
252	
253	        // The bomb shape: a small file on disk that inflates by orders of
254	        // magnitude. Without the cap the whole inflated stream is resident.
255	        let on_disk = std::fs::metadata(&path).unwrap().len();
256	        assert!(
257	            xml.len() as u64 > on_disk * 20,
258	            "fixture is not a compression bomb: {} inflated from {on_disk} on disk",
259	            xml.len()
260	        );
261	
262	        const CAP: u64 = 16 << 10;
263	        let (sections, stats) = extract_sections(&path, CAP, 64 << 20);
264	
265	        // Paragraphs are fixed width, so the last one wholly inside the cap is
266	        // arithmetic: the next one is at best half-read, never closes, and so
267	        // can never reach `body`.
268	        let last_whole = (CAP as usize - XML_HEAD.len()) / para(0).len();
269	        assert!(last_whole > 0 && last_whole < PARAS);
270	        assert!(stats.records > 0, "nothing was extracted before the cap");
271	        // Cutting the stream mid-tag reads as EOF to quick-xml, so truncation
272	        // is silent: the caller sees a clean document, just a shorter one.
273	        assert_eq!(stats.junk, 0);
274	        for present in [marker(0), marker(last_whole - 1)] {
275	            assert!(
276	                sections.iter().any(|s| s.contains(&present)),
277	                "{present} sits inside the cap but was not extracted"
278	            );
279	        }
280	        for absent in [marker(last_whole), marker(PARAS - 1)] {
281	            assert!(
282	                sections.iter().all(|s| !s.contains(&absent)),
283	                "{absent} sits past the {CAP}-byte cap but was still read"
284	            );
285	        }
286	        let extracted: usize = sections.iter().map(|s| s.len()).sum();
287	        assert!(
288	            extracted < xml.len() / 100,
289	            "extracted {extracted} bytes of a {}-byte stream: it was read whole",
290	            xml.len()
291	        );
292	    }
