297	        const RUNS: usize = 4_000;
298	        // Fixed-width runs with no whitespace between them: the paragraph
299	        // buffer holds exactly `i * run_bytes` before run `i` is considered.
300	        let run = |i: usize| format!("<w:r><w:t>{}{}</w:t></w:r>", marker(i), "x".repeat(57));
301	        let run_bytes = marker(0).len() + 57;
302	        let xml = format!(
303	            "{XML_HEAD}<w:p>{}</w:p>{XML_TAIL}",
304	            (0..RUNS).map(run).collect::<String>()
305	        );
306	
307	        let dir = tempfile::tempdir().unwrap();
308	        let path = dir.path().join("one-huge-paragraph.docx");
309	        write_docx(&path, &xml);
310	
311	        let (sections, stats) = extract_sections(&path, 64 << 20, CAP);
312	        assert!(stats.records > 0);
313	
314	        // A lone paragraph is only ever cut mid-paragraph, never overlapped, so
315	        // the sections concatenate back into exactly what the buffer held.
316	        let buffered = sections.concat();
317	        assert!(
318	            buffered.len() <= CAP + run_bytes,
319	            "paragraph buffer reached {} bytes against a {CAP}-byte cap",
320	            buffered.len()
321	        );
322	        let last_accepted = CAP / run_bytes - 1;
323	        assert!(buffered.contains(&marker(last_accepted)));
324	        assert!(!buffered.contains(&marker(last_accepted + 1)));
325	        assert!(!buffered.contains(&marker(RUNS - 1)));
326	    }
