1	//! SQLite databases — read-only immutable open (WAL/journal never touched);
2	//! one dataset (group) per table; locator = rowid where available.
3	
4	use super::{sanitize_field_name, ExtractStats, FieldOrigin, RawRecord, Sink};
5	use anyhow::{Context, Result};
6	use rusqlite::types::ValueRef;
7	use rusqlite::{Connection, OpenFlags};
8	use serde_json::{Map, Value};
9	use std::path::Path;
10	
11	pub fn extract(path: &Path, per_table_limit: Option<u64>, sink: Sink) -> Result<ExtractStats> {
12	    let mut stats = ExtractStats::default();
13	    let uri = format!(
14	        "file:{}?immutable=1&mode=ro",
15	        path.to_string_lossy().replace('?', "%3f")
16	    );
17	    let conn = Connection::open_with_flags(
18	        &uri,
19	        OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_URI,
20	    )
21	    .context("open sqlite (read-only immutable)")?;
22	
23	    let tables: Vec<String> = {
24	        let mut st = conn.prepare(
25	            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name",
26	        )?;
27	        let rows = st.query_map([], |r| r.get::<_, String>(0))?;
28	        rows.flatten().collect()
29	    };
30	
31	    'tables: for table in tables {
32	        let quoted = format!("\"{}\"", table.replace('"', "\"\""));
33	        // rowid may not exist (WITHOUT ROWID) — fall back to ordinal.
34	        let (sql, has_rowid) = (format!("SELECT rowid, * FROM {quoted}"), true);
35	        let mut stmt = match conn.prepare(&sql) {
36	            Ok(s) => (s, has_rowid),
37	            Err(_) => match conn.prepare(&format!("SELECT * FROM {quoted}")) {
38	                Ok(s) => (s, false),
39	                Err(_) => {
40	                    stats.junk += 1;
41	                    continue;
42	                }
43	            },
44	        };
45	        let has_rowid = stmt.1;
46	        let stmt = &mut stmt.0;
47	        let col_names: Vec<String> = stmt
48	            .column_names()
49	            .iter()
50	            .map(|c| sanitize_field_name(c))
51	            .collect();
52	        let ncols = col_names.len();
53	        let mut rows = match stmt.query([]) {
54	            Ok(r) => r,
55	            Err(_) => {
56	                stats.junk += 1;
57	                continue;
58	            }
59	        };
60	        let mut ordinal: u64 = 0;
61	        let mut emitted: u64 = 0;
62	        while let Ok(Some(row)) = rows.next() {
63	            let start_col = if has_rowid { 1 } else { 0 };
64	            let rowid: Option<i64> = if has_rowid { row.get(0).ok() } else { None };
65	            let mut fields = Map::new();
66	            for (i, name) in col_names.iter().enumerate().take(ncols).skip(start_col) {
67	                let v = match row.get_ref(i) {
68	                    Ok(v) => v,
69	                    Err(_) => continue,
70	                };
71	                match v {
72	                    ValueRef::Null => {}
73	                    ValueRef::Integer(n) => {
74	                        fields.insert(name.clone(), Value::Number(n.into()));
75	                    }
76	                    ValueRef::Real(f) => {
77	                        if let Some(n) = serde_json::Number::from_f64(f) {
78	                            fields.insert(name.clone(), Value::Number(n));
79	                        }
80	                    }
81	                    ValueRef::Text(t) => {
82	                        fields.insert(
83	                            name.clone(),
84	                            Value::String(String::from_utf8_lossy(t).to_string()),
85	                        );
86	                    }
87	                    ValueRef::Blob(_) => {} // skipped, non-text payload
88	                }
89	            }
90	            let loc = match rowid {
91	                Some(r) => format!("t{table}:r{r}"),
92	                None => format!("t{table}:o{ordinal}"),
93	            };
94	            ordinal += 1;
95	            if fields.is_empty() {
96	                continue;
97	            }
98	            stats.records += 1;
99	            emitted += 1;
100	            if !sink(RawRecord {
101	                fields,
102	                locator: loc,
103	                group: Some(table.clone()),
104	                origin: FieldOrigin::Data,
105	            }) {
106	                break 'tables;
107	            }
108	            if let Some(lim) = per_table_limit {
109	                if emitted >= lim {
110	                    break;
111	                }
112	            }
113	        }
114	    }
115	    Ok(stats)
116	}
