1	//! JSONL (newline-delimited JSON) — streaming, byte-offset locators.
2	
3	use super::{flatten_object, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_LINE};
4	use anyhow::Result;
5	use serde_json::Value;
6	use std::path::Path;
7	
8	pub fn extract(
9	    path: &Path,
10	    gzip: bool,
11	    limit_bytes: Option<u64>,
12	    sink: Sink,
13	) -> Result<ExtractStats> {
14	    let mut r = super::open_reader(path, gzip, limit_bytes)?;
15	    let mut stats = ExtractStats::default();
16	    let mut offset: u64 = 0;
17	    let mut line: Vec<u8> = Vec::new();
18	    loop {
19	        line.clear();
20	        let n = read_capped_line(&mut r, &mut line)?;
21	        if n == 0 {
22	            break;
23	        }
24	        let start = offset;
25	        offset += n as u64;
26	        let trimmed = trim_ws(&line);
27	        if trimmed.is_empty() {
28	            continue;
29	        }
30	        if line.len() >= MAX_LINE {
31	            stats.junk += 1;
32	            continue;
33	        }
34	        match serde_json::from_slice::<Value>(trimmed) {
35	            Ok(Value::Object(m)) => {
36	                stats.records += 1;
37	                if !sink(RawRecord {
38	                    fields: flatten_object(m),
39	                    locator: format!("b{start}"),
40	                    group: None,
41	                    origin: FieldOrigin::Data,
42	                }) {
43	                    break;
44	                }
45	            }
46	            Ok(_) | Err(_) => {
47	                // Truncated tail line under a sampling limit isn't junk.
48	                if limit_bytes.is_some() && offset >= limit_bytes.unwrap_or(0) {
49	                    break;
50	                }
51	                stats.junk += 1;
52	            }
53	        }
54	    }
55	    Ok(stats)
56	}
57	
58	/// read_until('\n') with a hard cap so a pathological line can't balloon RAM.
59	pub fn read_capped_line(r: &mut dyn std::io::BufRead, out: &mut Vec<u8>) -> Result<usize> {
60	    let mut total = 0usize;
61	    loop {
62	        let buf = r.fill_buf()?;
63	        if buf.is_empty() {
64	            return Ok(total);
65	        }
66	        match memchr::memchr(b'\n', buf) {
67	            Some(i) => {
68	                if out.len() < MAX_LINE {
69	                    out.extend_from_slice(&buf[..=i.min(MAX_LINE - 1)]);
70	                }
71	                r.consume(i + 1);
72	                return Ok(total + i + 1);
73	            }
74	            None => {
75	                let n = buf.len();
76	                if out.len() < MAX_LINE {
77	                    let take = n.min(MAX_LINE - out.len());
78	                    out.extend_from_slice(&buf[..take]);
79	                }
80	                r.consume(n);
81	                total += n;
82	            }
83	        }
84	    }
85	}
86	
87	pub(super) fn trim_ws(b: &[u8]) -> &[u8] {
88	    let start = b
89	        .iter()
90	        .position(|c| !c.is_ascii_whitespace())
91	        .unwrap_or(b.len());
92	    let end = b
93	        .iter()
94	        .rposition(|c| !c.is_ascii_whitespace())
95	        .map(|i| i + 1)
96	        .unwrap_or(start);
97	    &b[start..end]
98	}
