1	//! CSV with sniffed dialect (delimiter / header / decimal-comma), streaming.
2	
3	use super::{sanitize_field_name, ExtractStats, FieldOrigin, RawRecord, Sink};
4	use crate::sniff::Sniffed;
5	use anyhow::Result;
6	use serde_json::{Map, Value};
7	use std::path::Path;
8	
9	pub fn extract(
10	    path: &Path,
11	    sn: &Sniffed,
12	    limit_bytes: Option<u64>,
13	    sink: Sink,
14	) -> Result<ExtractStats> {
15	    let dialect = sn.csv.unwrap_or(crate::sniff::CsvDialect {
16	        delim: b',',
17	        has_header: true,
18	        decimal_comma: false,
19	    });
20	    let r = super::open_reader(path, sn.gzip, limit_bytes)?;
21	    let mut rdr = csv::ReaderBuilder::new()
22	        .delimiter(dialect.delim)
23	        .has_headers(dialect.has_header)
24	        .flexible(true)
25	        .from_reader(r);
26	    let headers: Vec<String> = if dialect.has_header {
27	        let h = rdr.headers()?.clone();
28	        let mut seen = std::collections::HashSet::new();
29	        h.iter()
30	            .map(|f| {
31	                let mut name = sanitize_field_name(f);
32	                while !seen.insert(name.clone()) {
33	                    name.push('_');
34	                    name.push('2');
35	                }
36	                name
37	            })
38	            .collect()
39	    } else {
40	        Vec::new()
41	    };
42	    let decimal_comma_re = regex::Regex::new(r"^-?\d{1,12},\d+$").unwrap();
43	    let mut stats = ExtractStats::default();
44	    for (i, rec) in rdr.into_records().enumerate() {
45	        let rec = match rec {
46	            Ok(r) => r,
47	            Err(_) => {
48	                stats.junk += 1;
49	                continue;
50	            }
51	        };
52	        let mut fields = Map::new();
53	        for (j, val) in rec.iter().enumerate() {
54	            let name = if j < headers.len() {
55	                headers[j].clone()
56	            } else {
57	                format!("col_{}", j + 1)
58	            };
59	            let mut v = val.trim().to_string();
60	            if v.is_empty() {
61	                continue;
62	            }
63	            if dialect.decimal_comma && decimal_comma_re.is_match(&v) {
64	                v = v.replace(',', ".");
65	            }
66	            fields.insert(name, Value::String(v));
67	        }
68	        if fields.is_empty() {
69	            continue;
70	        }
71	        stats.records += 1;
72	        if !sink(RawRecord {
73	            fields,
74	            locator: format!("r{i}"),
75	            group: None,
76	            origin: FieldOrigin::Data,
77	        }) {
78	            break;
79	        }
80	    }
81	    Ok(stats)
82	}
