1	//! XML — pull-parsed (quick-xml), O(depth) memory.
2	//! The record element is elected generically: the most frequent tag (in the
3	//! first 4096 start events) that carries structure (attributes or element
4	//! children), ties going to the outermost then the lowest-named tag. No
5	//! repeating structured tag → the whole document is one record.
6	
7	use super::{
8	    sanitize_field_name, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_FIELDS_PER_RECORD,
9	    MAX_LINE,
10	};
11	use anyhow::Result;
12	use quick_xml::events::{BytesRef, BytesStart, Event};
13	use quick_xml::Reader;
14	use serde_json::{Map, Value};
15	use std::collections::HashMap;
16	use std::path::Path;
17	
18	/// Resolve one `&…;` general reference to the text it stands for.
19	///
20	/// quick-xml >= 0.38 no longer folds entity references into the surrounding
21	/// `Event::Text`: it emits each one as its own `Event::GeneralRef`, so a
22	/// consumer that wants `5 &lt; 10` to read as `5 < 10` has to reassemble the
23	/// text itself. Predefined XML entities and numeric character references
24	/// resolve here; anything else (an entity a DTD we never read would have
25	/// declared) yields `None` and the reference is dropped.
26	///
27	/// Dropping just the reference is deliberately *better* than what 0.36 did:
28	/// there, one unknown entity failed `BytesText::unescape()` for the whole node
29	/// and `unwrap_or_default()` threw the entire text away.
30	pub(super) fn resolve_general_ref(r: &BytesRef) -> Option<String> {
31	    match r.resolve_char_ref() {
32	        Ok(Some(c)) => return Some(c.to_string()),
33	        Ok(None) => {}
34	        // Out-of-range or malformed `&#…;` — not text, so contribute nothing.
35	        Err(_) => return None,
36	    }
37	    let name = r.decode().ok()?;
38	    quick_xml::escape::resolve_predefined_entity(&name).map(str::to_string)
39	}
40	
41	struct State {
42	    record_tag: Option<String>,
43	    capture: Option<Map<String, Value>>,
44	    stack: Vec<String>,
45	    root_fields: Map<String, Value>,
46	    root_stack: Vec<String>,
47	    ordinal: u64,
48	}
49	
50	pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
51	    let mut stats = ExtractStats::default();
52	    let record_tag = elect_record_tag(path, gzip)?;
53	
54	    let r = super::open_reader(path, gzip, None)?;
55	    let mut reader = Reader::from_reader(r);
56	    // Deliberately NOT `trim_text(true)`: the reader trims each fragment
57	    // independently, and `5 &lt; 10` arrives as three fragments, so trimming
58	    // per fragment would splice it back together as `5<10`. Trim once, at the
59	    // element boundary, over the reassembled text instead.
60	    reader.config_mut().trim_text(false);
61	    let mut buf = Vec::new();
62	    // Character data accumulates here and is flushed as ONE value when the
63	    // next structural event arrives. Text, CDATA and entity references are all
64	    // fragments of the same logical value; emitting them separately would turn
65	    // every entity-bearing field into an array of pieces.
66	    let mut pending = String::new();
67	    let mut st = State {
68	        record_tag,
69	        capture: None,
70	        stack: Vec::new(),
71	        root_fields: Map::new(),
72	        root_stack: Vec::new(),
73	        ordinal: 0,
74	    };
75	
76	    loop {
77	        match reader.read_event_into(&mut buf) {
78	            Ok(Event::Start(e)) => {
79	                flush_text(&mut pending, &mut st);
80	                handle_open(&e, false, &mut st);
81	            }
82	            Ok(Event::Empty(e)) => {
83	                flush_text(&mut pending, &mut st);
84	                if let Some(fields) = handle_open(&e, true, &mut st) {
85	                    // `<record …/>` self-closing: complete record, no End event.
86	                    if !fields.is_empty() {
87	                        stats.records += 1;
88	                        let loc = format!("e{}", st.ordinal);
89	                        st.ordinal += 1;
90	                        if !sink(RawRecord {
91	                            fields,
92	                            locator: loc,
93	                            group: None,
94	                            origin: FieldOrigin::Data,
95	                        }) {
96	                            return Ok(stats);
97	                        }
98	                    }
99	                }
100	            }
101	            Ok(Event::End(e)) => {
102	                flush_text(&mut pending, &mut st);
103	                let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
104	                if let Some(m) = st.capture.as_mut() {
105	                    if st.stack.is_empty() && st.record_tag.as_deref() == Some(name.as_str()) {
106	                        let fields = std::mem::take(m);
107	                        st.capture = None;
108	                        if !fields.is_empty() {
109	                            stats.records += 1;
110	                            let loc = format!("e{}", st.ordinal);
111	                            st.ordinal += 1;
112	                            if !sink(RawRecord {
113	                                fields,
114	                                locator: loc,
115	                                group: None,
116	                                origin: FieldOrigin::Data,
117	                            }) {
118	                                return Ok(stats);
119	                            }
120	                        }
121	                    } else {
122	                        st.stack.pop();
123	                    }
124	                } else if st.record_tag.is_none() {
125	                    st.root_stack.pop();
126	                }
127	            }
128	            Ok(Event::Text(t)) => {
129	                push_text(&mut pending, &t.xml10_content().unwrap_or_default());
130	            }
131	            Ok(Event::GeneralRef(entity)) => {
132	                if let Some(resolved) = resolve_general_ref(&entity) {
133	                    push_text(&mut pending, &resolved);
134	                }
135	            }
136	            Ok(Event::CData(t)) => {
137	                push_text(&mut pending, &String::from_utf8_lossy(&t));
138	            }
139	            Ok(Event::Eof) => {
140	                flush_text(&mut pending, &mut st);
141	                break;
142	            }
143	            Ok(_) => {}
144	            Err(_) => {
145	                // Everything read before the break is still emitted, so the
146	                // text already buffered has to land before we stop.
147	                flush_text(&mut pending, &mut st);
148	                stats.junk += 1;
149	                break;
150	            }
151	        }
152	        buf.clear();
153	    }
154	
155	    if st.record_tag.is_none() && !st.root_fields.is_empty() {
156	        stats.records += 1;
157	        sink(RawRecord {
158	            fields: st.root_fields,
159	            locator: "doc".into(),
160	            group: None,
161	            origin: FieldOrigin::Data,
162	        });
163	    }
164	    Ok(stats)
165	}
166	
167	/// Returns Some(fields) when a self-closing record element completes
168	/// immediately (no End event will follow).
169	fn handle_open(e: &BytesStart, empty: bool, st: &mut State) -> Option<Map<String, Value>> {
170	    let name = String::from_utf8_lossy(e.name().as_ref()).to_string();
171	    let attrs: Vec<(String, String)> = e
172	        .attributes()
173	        .flatten()
174	        .map(|a| {
175	            (
176	                String::from_utf8_lossy(a.key.as_ref()).to_string(),
177	                String::from_utf8_lossy(&a.value).to_string(),
178	            )
179	        })
180	        .collect();
181	    if st.capture.is_none() && st.record_tag.as_deref() == Some(name.as_str()) {
182	        let mut m = Map::new();
183	        for (k, v) in &attrs {
184	            insert_field(&mut m, &sanitize_field_name(k), v);
185	        }
186	        if empty {
187	            return Some(m);
188	        }
189	        st.capture = Some(m);
190	        st.stack.clear();
191	    } else if st.capture.is_some() {
192	        if !empty {
193	            st.stack.push(name.clone());
194	        }
195	        let mut prefix_parts = st.stack.clone();
196	        if empty {
197	            prefix_parts.push(name.clone());
198	        }
199	        let prefix = prefix_parts.join("_");
200	        let m = st.capture.as_mut().unwrap();
201	        for (k, v) in &attrs {
202	            let key = if prefix.is_empty() {
203	                sanitize_field_name(k)
204	            } else {
205	                sanitize_field_name(&format!("{prefix}_{k}"))
206	            };
207	            insert_field(m, &key, v);
208	        }
209	    } else if st.record_tag.is_none() {
210	        if !empty {
211	            st.root_stack.push(name.clone());
212	        }
213	        let mut parts: Vec<String> = if st.root_stack.len() > 1 {
214	            st.root_stack[1..].to_vec()
215	        } else {
216	            Vec::new()
217	        };
218	        if empty && !st.root_stack.is_empty() {
219	            parts.push(name.clone());
220	        }
221	        let prefix = parts.join("_");
222	        for (k, v) in &attrs {
223	            let key = if prefix.is_empty() {
224	                sanitize_field_name(k)
225	            } else {
226	                sanitize_field_name(&format!("{prefix}_{k}"))
227	            };
228	            insert_field(&mut st.root_fields, &key, v);
229	        }
230	    }
231	    None
232	}
233	
234	/// Append one character-data fragment to the pending value.
235	///
236	/// SECURITY: the fragments of a single value are now concatenated rather than
237	/// emitted one at a time, so a document that never closes an element could
238	/// otherwise grow `pending` for the whole file. Stop appending at the same
239	/// 16 MB bound the line-oriented extractors use; no real XML text node is
240	/// anywhere near it.
241	fn push_text(pending: &mut String, fragment: &str) {
242	    if pending.len() < MAX_LINE {
243	        pending.push_str(fragment);
244	    }
245	}
246	
247	/// Emit whatever character data has accumulated as one value, keyed by the
248	/// element path that was open while it was read — so this must run *before*
249	/// the structural event that triggered it mutates the stack.
250	fn flush_text(pending: &mut String, st: &mut State) {
251	    let txt = pending.trim();
252	    if !txt.is_empty() {
253	        let txt = txt.to_string();
254	        handle_text(&txt, st);
255	    }
256	    pending.clear();
257	}
258	
259	fn handle_text(txt: &str, st: &mut State) {
260	    if let Some(m) = st.capture.as_mut() {
261	        let key = if st.stack.is_empty() {
262	            "text".to_string()
263	        } else {
264	            sanitize_field_name(&st.stack.join("_"))
265	        };
266	        insert_field(m, &key, txt);
267	    } else if st.record_tag.is_none() && !st.root_stack.is_empty() {
268	        let key = if st.root_stack.len() == 1 {
269	            "text".to_string()
270	        } else {
271	            sanitize_field_name(&st.root_stack[1..].join("_"))
272	        };
273	        insert_field(&mut st.root_fields, &key, txt);
274	    }
275	}
276	
277	/// Multi-valued fields become arrays.
278	fn insert_field(m: &mut Map<String, Value>, key: &str, v: &str) {
279	    if m.len() >= MAX_FIELDS_PER_RECORD && !m.contains_key(key) {
280	        return;
281	    }
282	    match m.get_mut(key) {
283	        None => {
284	            m.insert(key.to_string(), Value::String(v.to_string()));
285	        }
286	        Some(Value::Array(a)) => a.push(Value::String(v.to_string())),
287	        Some(prev) => {
288	            let old = prev.take();
289	            *prev = Value::Array(vec![old, Value::String(v.to_string())]);
290	        }
291	    }
292	}
