294	fn elect_record_tag(path: &Path, gzip: bool) -> Result<Option<String>> {
295	    let r = super::open_reader(path, gzip, Some(4 << 20))?;
296	    let mut reader = Reader::from_reader(r);
297	    reader.config_mut().trim_text(true);
298	    let mut buf = Vec::new();
299	    // tag -> (count, has_structure, shallowest depth seen)
300	    let mut counts: HashMap<String, (usize, bool, usize)> = HashMap::new();
301	    let mut parents: Vec<String> = Vec::new();
302	    let mut seen = 0usize;
303	    loop {
304	        let ev = reader.read_event_into(&mut buf);
305	        let (name, has_attr, empty) = match &ev {
306	            Ok(Event::Start(e)) => (
307	                String::from_utf8_lossy(e.name().as_ref()).to_string(),
308	                e.attributes().flatten().next().is_some(),
309	                false,
310	            ),
311	            Ok(Event::Empty(e)) => (
312	                String::from_utf8_lossy(e.name().as_ref()).to_string(),
313	                e.attributes().flatten().next().is_some(),
314	                true,
315	            ),
316	            Ok(Event::End(_)) => {
317	                parents.pop();
318	                buf.clear();
319	                continue;
320	            }
321	            Ok(Event::Eof) => break,
322	            Err(_) => break,
323	            _ => {
324	                buf.clear();
325	                continue;
326	            }
327	        };
328	        if !parents.is_empty() {
329	            let depth = parents.len();
330	            let entry = counts.entry(name.clone()).or_insert((0, false, depth));
331	            entry.0 += 1;
332	            entry.1 |= has_attr;
333	            entry.2 = entry.2.min(depth);
334	            if let Some(p) = parents.last() {
335	                if let Some(pe) = counts.get_mut(p) {
336	                    pe.1 = true;
337	                }
338	            }
339	        }
340	        if !empty {
341	            parents.push(name);
342	        }
343	        seen += 1;
344	        if seen >= 4096 {
345	            break;
346	        }
347	        buf.clear();
348	    }
349	    // The ordering must be TOTAL: `counts` is a HashMap, so any candidate left
350	    // tied would be settled by a per-map random hash seed and the same file
351	    // would index to a different shape on every run. Most occurrences wins;
352	    // a tie goes to the outermost tag (a wrapper that repeats as often as a
353	    // child is the record, and the child is one of its fields); a tie at the
354	    // same depth goes to the lowest name, which is arbitrary but stable.
355	    Ok(counts
356	        .into_iter()
357	        .filter(|(_, (n, structured, _))| *n >= 3 && *structured)
358	        .min_by(|(a_tag, (a_n, _, a_depth)), (b_tag, (b_n, _, b_depth))| {
359	            b_n.cmp(a_n)
360	                .then_with(|| a_depth.cmp(b_depth))
361	                .then_with(|| a_tag.cmp(b_tag))
362	        })
363	        .map(|(k, _)| k))
364	}
