1	//! Whole-value JSON files (object or array), capped at 64MB.
2	//! - array of objects  → one record per element
3	//! - object with a dominant top-level array of objects → one record per
4	//!   element, remaining top-level scalars merged in as shared fields
5	//! - a Google Keep note (Takeout `Keep/*.json`) → a DOCUMENT: `title`/`body`
6	//!   plus labels and dates — see [`keep_note`]
7	//! - anything else → a single record
8	
9	use super::{
10	    emit_document_with_fields, flatten_object, ExtractStats, FieldOrigin, RawRecord, Sink,
11	    MAX_LINE, MAX_WHOLE_FILE,
12	};
13	use anyhow::Result;
14	use serde_json::{Map, Value};
15	use std::path::Path;
16	
17	pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
18	    let mut stats = ExtractStats::default();
19	    let Some(bytes) = super::read_whole(path, gzip, MAX_WHOLE_FILE)? else {
20	        stats.junk += 1;
21	        return Ok(stats);
22	    };
23	    let v: Value = match serde_json::from_slice(&bytes) {
24	        Ok(v) => v,
25	        Err(_) => {
26	            // Not one JSON value. Before junking, try the file as JSONL:
27	            // a JSONL export whose FIRST line is longer than the sniff
28	            // prefix (8 KB) sniffs as `Json` — the sample holds zero
29	            // COMPLETE lines, so `classify_structured`'s per-line test
30	            // never runs and `looks_like_json_start` routes the whole
31	            // file here. Measured on the published rust-vulns pack:
32	            // osv/records.jsonl (735 records, first line ≥ 8 KB) was
33	            // junked as "no records extracted (json candidate family)"
34	            // and `xerj corpus index` accepted 1,230 of 1,963 records as
35	            // a success. A file that is neither one JSON value nor a
36	            // sequence of JSON lines junks exactly as before — every
37	            // line fails the per-line parse too.
38	            return jsonl_fallback(&bytes, sink);
39	        }
40	    };
41	    match v {
42	        Value::Array(arr) => {
43	            for (i, el) in arr.into_iter().enumerate() {
44	                if !emit(el, &format!("e{i}"), sink, &mut stats) {
45	                    break;
46	                }
47	            }
48	        }
49	        Value::Object(mut obj) => {
50	            // A Google Keep note is a document, not a row. Tested before the
51	            // array rule below, which would otherwise explode a checklist
52	            // note's `listContent` into one record per bullet.
53	            if let Some(note) = keep_note(&obj) {
54	                emit_document_with_fields(
55	                    &note.fields,
56	                    &note.title,
57	                    note.body.trim(),
58	                    "note",
59	                    sink,
60	                    &mut stats,
61	                );
62	                return Ok(stats);
63	            }
64	            // find the largest top-level array-of-objects
65	            let mut best: Option<(String, usize)> = None;
66	            for (k, vv) in obj.iter() {
67	                if let Value::Array(a) = vv {
68	                    if a.len() >= 2
69	                        && a.iter().all(|e| e.is_object())
70	                        && best.as_ref().map(|(_, n)| a.len() > *n).unwrap_or(true)
71	                    {
72	                        best = Some((k.clone(), a.len()));
73	                    }
74	                }
75	            }
76	            match best {
77	                Some((key, _)) => {
78	                    let Value::Array(arr) = obj.remove(&key).unwrap() else {
79	                        unreachable!()
80	                    };
81	                    let shared = flatten_object(obj);
82	                    for (i, el) in arr.into_iter().enumerate() {
83	                        if let Value::Object(m) = el {
84	                            let mut fields = shared.clone();
85	                            for (k, v) in flatten_object(m) {
86	                                fields.insert(k, v); // element wins collisions
87	                            }
88	                            stats.records += 1;
89	                            if !sink(RawRecord {
90	                                fields,
91	                                locator: format!("{key}:e{i}"),
92	                                group: None,
93	                                origin: FieldOrigin::Data,
94	                            }) {
95	                                break;
96	                            }
97	                        }
98	                    }
99	                }
100	                None => {
101	                    emit(Value::Object(obj), "doc", sink, &mut stats);
102	                }
103	            }
104	        }
105	        other => {
106	            let mut m = Map::new();
107	            m.insert("value".into(), other);
108	            emit(Value::Object(m), "doc", sink, &mut stats);
109	        }
110	    }
111	    Ok(stats)
112	}
