114	/// A Google Keep note, as a document.
115	struct KeepNote {
116	    title: String,
117	    body: String,
118	    fields: Map<String, Value>,
119	}
120	
121	/// Characters of a title-less note's first line used as its title.
122	const KEEP_TITLE_CHARS: usize = 80;
123	
124	/// Recognise a Google Keep note exported by Takeout (`Takeout/Keep/*.json`).
125	///
126	/// By CONTENT, like every other format here: the four keys tested are the ones
127	/// every Keep export carries (`createdTimestampUsec`, `userEditedTimestampUsec`,
128	/// `isTrashed`, and one of `textContent`/`listContent`), and no general-purpose
129	/// JSON document has all four by accident.
130	///
131	/// Why it is worth a branch: left to the generic rules a note indexes as a DATA
132	/// record whose text lives in a field called `textContent` — a name
133	/// `xerj search` does not query — and a checklist note becomes one record per
134	/// bullet. As a document it lands in the same `title`/`body` corpus as the mail
135	/// and files beside it. A trashed or archived note is still indexed, flagged
136	/// (`keep_trashed`/`keep_archived`) rather than silently dropped: what to
137	/// exclude is the reader's decision.
138	///
139	/// The field names are the extractor's vocabulary (`FieldOrigin::Extractor`,
140	/// via `emit_document_with_fields`), so a folder of notes joins the scope's
141	/// document dataset instead of forming a schema cluster of its own.
142	fn keep_note(obj: &Map<String, Value>) -> Option<KeepNote> {
143	    let created = obj.get("createdTimestampUsec")?.as_i64()?;
144	    let edited = obj.get("userEditedTimestampUsec")?.as_i64()?;
145	    let trashed = obj.get("isTrashed")?.as_bool()?;
146	    let text = obj.get("textContent").and_then(Value::as_str);
147	    let list = obj.get("listContent").and_then(Value::as_array);
148	    if text.is_none() && list.is_none() {
149	        return None;
150	    }
151	
152	    let mut body = text.unwrap_or("").to_string();
153	    for item in list.into_iter().flatten() {
154	        let Some(line) = item.get("text").and_then(Value::as_str) else {
155	            continue;
156	        };
157	        let checked = item.get("isChecked").and_then(Value::as_bool) == Some(true);
158	        if !body.is_empty() {
159	            body.push('\n');
160	        }
161	        body.push_str(if checked { "- [x] " } else { "- [ ] " });
162	        body.push_str(line);
163	    }
164	    // Link annotations: the URL and page title Keep attached to the note.
165	    for ann in obj
166	        .get("annotations")
167	        .and_then(Value::as_array)
168	        .into_iter()
169	        .flatten()
170	    {
171	        let url = ann.get("url").and_then(Value::as_str).unwrap_or("");
172	        let title = ann.get("title").and_then(Value::as_str).unwrap_or("");
173	        if url.is_empty() && title.is_empty() {
174	            continue;
175	        }
176	        body.push_str("\n\n");
177	        body.push_str(title);
178	        if !title.is_empty() && !url.is_empty() {
179	            body.push_str(" — ");
180	        }
181	        body.push_str(url);
182	    }
183	
184	    let title = obj
185	        .get("title")
186	        .and_then(Value::as_str)
187	        .map(str::trim)
188	        .filter(|t| !t.is_empty())
189	        .map(str::to_string)
190	        .unwrap_or_else(|| {
191	            // Cut by CHARS, never by bytes: a note that opens in Arabic or
192	            // Chinese must not be sliced mid-character (panic = abort).
193	            let first = body.lines().find(|l| !l.trim().is_empty()).unwrap_or("");
194	            let cut: String = first.trim().chars().take(KEEP_TITLE_CHARS).collect();
195	            if cut.is_empty() {
196	                "(untitled note)".to_string()
197	            } else {
198	                cut
199	            }
200	        });
201	
202	    let mut fields = Map::new();
203	    let labels: Vec<Value> = obj
204	        .get("labels")
205	        .and_then(Value::as_array)
206	        .into_iter()
207	        .flatten()
208	        .filter_map(|l| l.get("name").and_then(Value::as_str))
209	        .map(|n| Value::String(n.to_string()))
210	        .collect();
211	    if !labels.is_empty() {
212	        fields.insert("keep_labels".into(), Value::Array(labels));
213	    }
214	    for (name, usec) in [("keep_created", created), ("keep_edited", edited)] {
215	        if let Some(t) = chrono::DateTime::<chrono::Utc>::from_timestamp_micros(usec) {
216	            fields.insert(
217	                name.into(),
218	                Value::String(t.to_rfc3339_opts(chrono::SecondsFormat::Secs, true)),
219	            );
220	        }
221	    }
222	    fields.insert("keep_trashed".into(), Value::Bool(trashed));
223	    for (name, key) in [("keep_archived", "isArchived"), ("keep_pinned", "isPinned")] {
224	        if let Some(b) = obj.get(key).and_then(Value::as_bool) {
225	            fields.insert(name.into(), Value::Bool(b));
226	        }
227	    }
228	    Some(KeepNote {
229	        title,
230	        body,
231	        fields,
232	    })
233	}
