235	/// Largest file [`is_keep_note_file`] will open. Keep caps a note at roughly
236	/// 20k characters; a JSON file past this is not a note, and the walker must
237	/// not read megabytes per `.html` it meets just to find that out.
238	const KEEP_PROBE_MAX: u64 = 1 << 20;
239	
240	/// Is the file at `path` a Google Keep note? The SAME predicate the extractor
241	/// applies ([`keep_note`]), exposed for the walker's Takeout rule so the two
242	/// can never disagree about which `.html` has a JSON twin that will be indexed
243	/// as the note. Any error — unreadable, oversized, not JSON — is `false`: the
244	/// caller is deciding whether to SKIP a file, and doubt means index it.
245	pub(crate) fn is_keep_note_file(path: &Path) -> bool {
246	    let small = std::fs::metadata(path).is_ok_and(|m| m.is_file() && m.len() <= KEEP_PROBE_MAX);
247	    if !small {
248	        return false;
249	    }
250	    let Ok(bytes) = std::fs::read(path) else {
251	        return false;
252	    };
253	    match serde_json::from_slice::<Value>(&bytes) {
254	        Ok(Value::Object(obj)) => keep_note(&obj).is_some(),
255	        _ => false,
256	    }
257	}
258	
259	/// Whole-file parse failed — re-parse the same in-memory bytes line by
260	/// line under the JSONL contract (see the fallback note in [`extract`]).
261	/// Mirrors `jsonl::extract`'s per-line semantics: blank lines skip, a line
262	/// at the 16 MB cap junks, an object becomes one flattened record with a
263	/// byte-offset locator, anything else junks. No `limit_bytes` exists here
264	/// (the family reads the whole file), so there is no truncated-tail
265	/// exemption to carry over.
266	fn jsonl_fallback(bytes: &[u8], sink: Sink) -> Result<ExtractStats> {
267	    let mut stats = ExtractStats::default();
268	    let mut offset: u64 = 0;
269	    for line in bytes.split(|&b| b == b'\n') {
270	        let start = offset;
271	        offset += line.len() as u64 + 1;
272	        let trimmed = super::jsonl::trim_ws(line);
273	        if trimmed.is_empty() {
274	            continue;
275	        }
276	        if line.len() >= MAX_LINE {
277	            stats.junk += 1;
278	            continue;
279	        }
280	        match serde_json::from_slice::<Value>(trimmed) {
281	            Ok(Value::Object(m)) => {
282	                stats.records += 1;
283	                if !sink(RawRecord {
284	                    fields: flatten_object(m),
285	                    locator: format!("b{start}"),
286	                    group: None,
287	                    origin: FieldOrigin::Data,
288	                }) {
289	                    return Ok(stats);
290	                }
291	            }
292	            Ok(_) | Err(_) => {
293	                stats.junk += 1;
294	            }
295	        }
296	    }
297	    Ok(stats)
298	}
299	
300	fn emit(v: Value, locator: &str, sink: Sink, stats: &mut ExtractStats) -> bool {
301	    let fields = match v {
302	        Value::Object(m) => flatten_object(m),
303	        other => {
304	            let mut m = Map::new();
305	            m.insert("value".into(), other);
306	            m
307	        }
308	    };
309	    stats.records += 1;
310	    sink(RawRecord {
311	        fields,
312	        locator: locator.to_string(),
313	        group: None,
314	        origin: FieldOrigin::Data,
315	    })
316	}
