1	//! YAML — multi-document streams; each doc becomes a record (a top-level
2	//! sequence of mappings becomes per-element records). 16MB file cap.
3	
4	use super::{flatten_object, yaml_to_json, ExtractStats, FieldOrigin, RawRecord, Sink};
5	use anyhow::Result;
6	use serde_json::{Map, Value};
7	use std::path::Path;
8	
9	const YAML_CAP: u64 = 16 << 20;
10	
11	pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
12	    let mut stats = ExtractStats::default();
13	    let Some(bytes) = super::read_whole(path, gzip, YAML_CAP)? else {
14	        stats.junk += 1;
15	        return Ok(stats);
16	    };
17	    let (text, _) = crate::sniff::decode_text(&bytes);
18	    let mut any = false;
19	    for (d, de) in serde_yaml::Deserializer::from_str(&text).enumerate() {
20	        let yv: serde_yaml::Value = match serde_yaml::Value::deserialize(de) {
21	            Ok(v) => v,
22	            Err(_) => {
23	                // MUST break, never continue: serde_yaml's multi-document
24	                // iterator does not advance past a document that fails to
25	                // parse — `continue` re-yields the same broken document
26	                // forever (live hang: a markdown task list `- [ ] …` sniffed
27	                // as YAML spun autoindex phase A indefinitely). Junk-file the
28	                // rest of the stream instead; the loss is recorded, not
29	                // hidden.
30	                stats.junk += 1;
31	                break;
32	            }
33	        };
34	        any = true;
35	        let jv = yaml_to_json(yv);
36	        match jv {
37	            Value::Array(arr) if arr.iter().all(|e| e.is_object()) && !arr.is_empty() => {
38	                for (i, el) in arr.into_iter().enumerate() {
39	                    if let Value::Object(m) = el {
40	                        stats.records += 1;
41	                        if !sink(RawRecord {
42	                            fields: flatten_object(m),
43	                            locator: format!("d{d}e{i}"),
44	                            group: None,
45	                            origin: FieldOrigin::Data,
46	                        }) {
47	                            return Ok(stats);
48	                        }
49	                    }
50	                }
51	            }
52	            Value::Object(m) => {
53	                stats.records += 1;
54	                if !sink(RawRecord {
55	                    fields: flatten_object(m),
56	                    locator: format!("d{d}"),
57	                    group: None,
58	                    origin: FieldOrigin::Data,
59	                }) {
60	                    return Ok(stats);
61	                }
62	            }
63	            other => {
64	                let mut m = Map::new();
65	                m.insert("value".into(), other);
66	                stats.records += 1;
67	                if !sink(RawRecord {
68	                    fields: m,
69	                    locator: format!("d{d}"),
70	                    group: None,
71	                    origin: FieldOrigin::Data,
72	                }) {
73	                    return Ok(stats);
74	                }
75	            }
76	        }
77	    }
78	    if !any && stats.junk == 0 {
79	        stats.junk += 1;
80	    }
81	    Ok(stats)
82	}
