1	//! SQL dump — targeted streaming parser, O(1) memory per tuple.
2	//! No sqlparser: multi-row `INSERT … VALUES (…),(…)…` statements in dumps
3	//! can reach hundreds of MB; this lexer never materializes a statement.
4	//! Handles MySQL + Postgres dump styles: CREATE TABLE column capture, tuple
5	//! records with `''`/backslash escapes, NULL, numbers, hex literals.
6	//! One dataset (group) per table.
7	
8	use super::{sanitize_field_name, ExtractStats, FieldOrigin, RawRecord, Sink};
9	use anyhow::Result;
10	use serde_json::{Map, Value};
11	use std::collections::HashMap;
12	use std::io::Read;
13	use std::path::Path;
14	
15	const HEAD_CAP: usize = 1 << 20;
16	
17	#[derive(PartialEq, Debug, Clone, Copy)]
18	enum St {
19	    Head,      // accumulating statement text (CREATE/SET/…, or INSERT up to VALUES)
20	    SkipStmt,  // oversized/unparseable statement — discard to ';'
21	    TupleScan, // between tuples of an INSERT
22	    InTuple,   // inside (…)
23	    InString,  // inside '…'
24	    Bare,      // bare token value (number / NULL / hex)
25	}
26	
27	pub fn extract(
28	    path: &Path,
29	    gzip: bool,
30	    limit_bytes: Option<u64>,
31	    sink: Sink,
32	) -> Result<ExtractStats> {
33	    let mut r = super::open_reader(path, gzip, limit_bytes)?;
34	    let mut stats = ExtractStats::default();
35	
36	    let mut tables: HashMap<String, Vec<String>> = HashMap::new();
37	    let mut stmt_ord: HashMap<String, u64> = HashMap::new();
38	
39	    let mut state = St::Head;
40	    // Byte buffers, NOT `String`.  These accumulate raw input bytes; pushing
41	    // them as `b as char` (the previous form) reinterprets any byte >= 0x80 as
42	    // a Latin-1 codepoint that re-encodes to TWO UTF-8 bytes, so byte offsets
43	    // into the buffer stop being char boundaries.  `head[..6]` then panicked
44	    // on perfectly ordinary UTF-8 input — an em-dash in a comment was enough,
45	    // and because the workspace builds with `panic = "abort"` it killed the
46	    // whole `autoindex` run rather than skipping one file.  For `sval` the
47	    // same cast silently produced mojibake for every non-ASCII string value.
48	    let mut head: Vec<u8> = Vec::new();
49	    let mut head_quote: Option<u8> = None;
50	
51	    let mut cur_table = String::new();
52	    let mut cur_cols: Vec<String> = Vec::new();
53	    let mut cur_stmt = 0u64;
54	    let mut tuple_ord = 0u64;
55	    let mut values: Vec<Value> = Vec::new();
56	    let mut sval: Vec<u8> = Vec::new(); // current string value (raw bytes)
57	    let mut maybe_end = false; // saw closing ' — is it '' escape?
58	    let mut esc = false;
59	
60	    let mut chunk = vec![0u8; 256 << 10];
61	    let mut stop = false;
62	    'outer: loop {
63	        let n = r.read(&mut chunk)?;
64	        if n == 0 {
65	            break;
66	        }
67	        let mut i = 0usize;
68	        while i < n {
69	            let b = chunk[i];
70	            match state {
71	                St::Head => {
72	                    match head_quote {
73	                        Some(q) => {
74	                            if b == q {
75	                                head_quote = None;
76	                            }
77	                            if head.len() < HEAD_CAP {
78	                                head.push(b);
79	                            }
80	                        }
81	                        None => {
82	                            if b == b'\'' || b == b'"' {
83	                                head_quote = Some(b);
84	                                head.push(b);
85	                            } else if b == b';' {
86	                                process_statement_head(&head, &mut tables);
87	                                head.clear();
88	                            } else {
89	                                if head.len() >= HEAD_CAP {
90	                                    head.clear();
91	                                    state = St::SkipStmt;
92	                                    i += 1;
93	                                    continue;
94	                                }
95	                                head.push(b);
96	                                // did we just complete the VALUES keyword of an INSERT?
97	                                if (b == b'S' || b == b's') && head.len() >= 6 {
98	                                    let tail = &head[head.len() - 6..];
99	                                    let trimmed = trim_start_bytes(&head);
100	                                    if tail.eq_ignore_ascii_case(b"values")
101	                                        && trimmed.len() >= 6
102	                                        && trimmed[..6].eq_ignore_ascii_case(b"insert")
103	                                        && !head[..head.len() - 6]
104	                                            .last()
105	                                            .is_some_and(|c| c.is_ascii_alphanumeric())
106	                                    {
107	                                        if let Some((t, cols)) = parse_insert_head(&head) {
108	                                            cur_table = t;
109	                                            cur_cols = if cols.is_empty() {
110	                                                tables.get(&cur_table).cloned().unwrap_or_default()
111	                                            } else {
112	                                                cols
113	                                            };
114	                                            let e = stmt_ord.entry(cur_table.clone()).or_insert(0);
115	                                            cur_stmt = *e;
116	                                            *e += 1;
117	                                            tuple_ord = 0;
118	                                            state = St::TupleScan;
119	                                        } else {
120	                                            state = St::SkipStmt;
121	                                        }
122	                                        head.clear();
123	                                    }
124	                                }
125	                            }
126	                        }
127	                    }
128	                    i += 1;
129	                }
130	                St::SkipStmt => {
131	                    // discard to ';' (quote-aware)
132	                    match head_quote {
133	                        Some(q) => {
134	                            if b == q {
135	                                head_quote = None;
136	                            }
137	                        }
138	                        None => {
139	                            if b == b'\'' || b == b'"' {
140	                                head_quote = Some(b);
141	                            } else if b == b';' {
142	                                state = St::Head;
143	                            }
144	                        }
145	                    }
146	                    i += 1;
147	                }
148	                St::TupleScan => {
149	                    match b {
150	                        b'(' => {
151	                            values.clear();
152	                            state = St::InTuple;
153	                        }
154	                        b';' => {
155	                            state = St::Head;
156	                        }
157	                        _ => {} // commas, whitespace
158	                    }
159	                    i += 1;
160	                }
161	                St::InTuple => {
162	                    match b {
163	                        b'\'' => {
164	                            sval.clear();
165	                            esc = false;
166	                            maybe_end = false;
167	                            state = St::InString;
168	                            i += 1;
169	                        }
170	                        b')' => {
171	                            if !emit_tuple(
172	                                &cur_table,
173	                                &cur_cols,
174	                                &mut values,
175	                                cur_stmt,
176	                                &mut tuple_ord,
177	                                sink,
178	                                &mut stats,
179	                            ) {
180	                                stop = true;
181	                                break 'outer;
182	                            }
183	                            state = St::TupleScan;
184	                            i += 1;
185	                        }
186	                        b',' => {
187	                            i += 1; // empty slot separators handled by Bare/Str paths
188	                        }
189	                        c if c.is_ascii_whitespace() => {
190	                            i += 1;
191	                        }
192	                        _ => {
193	                            sval.clear();
194	                            state = St::Bare;
195	                            // do not advance — Bare consumes this byte
196	                        }
197	                    }
198	                }
199	                St::InString => {
200	                    if maybe_end {
201	                        maybe_end = false;
202	                        if b == b'\'' {
203	                            sval.push(b'\'');
204	                            i += 1;
205	                        } else {
206	                            // string finished; value complete. Reprocess b in InTuple.
207	                            values.push(Value::String(take_utf8(&mut sval)));
208	                            state = St::InTuple;
209	                        }
210	                    } else if esc {
211	                        esc = false;
212	                        let c = match b {
213	                            b'n' => b'\n',
214	                            b't' => b'\t',
215	                            b'r' => b'\r',
216	                            b'0' => 0u8,
217	                            other => other,
218	                        };
219	                        sval.push(c);
220	                        i += 1;
221	                    } else {
222	                        match b {
223	                            b'\\' => {
224	                                esc = true;
225	                                i += 1;
226	                            }
227	                            b'\'' => {
228	                                maybe_end = true;
229	                                i += 1;
230	                            }
231	                            _ => {
232	                                // Raw byte — multibyte UTF-8 arrives byte-by-byte
233	                                // and is decoded once, at value completion.
234	                                sval.push(b);
235	                                i += 1;
236	                            }
237	                        }
238	                    }
239	                }
240	                St::Bare => {
241	                    if matches!(b, b',' | b')') || b.is_ascii_whitespace() {
242	                        values.push(bare_value(&take_utf8(&mut sval)));
243	                        state = St::InTuple;
244	                        // reprocess delimiter in InTuple
245	                    } else {
246	                        if sval.len() < HEAD_CAP {
247	                            sval.push(b);
248	                        }
249	                        i += 1;
250	                    }
251	                }
252	            }
253	        }
254	    }
255	    // EOF with a dangling string value under sampling limits is expected —
256	    // discard silently when sampling, count as junk otherwise.
257	    if !stop && limit_bytes.is_none() && (state == St::InString || state == St::Bare) {
258	        stats.junk += 1;
259	    }
260	    Ok(stats)
261	}
