263	/// UTF-8 repair: strings were accumulated byte-as-char (latin-1); re-encode.
264	fn fix_utf8(s: &str) -> String {
265	    if s.is_ascii() {
266	        return s.to_string();
267	    }
268	    let bytes: Vec<u8> = s.chars().map(|c| c as u32 as u8).collect();
269	    match String::from_utf8(bytes) {
270	        Ok(fixed) => fixed,
271	        Err(_) => s.to_string(),
272	    }
273	}
