275	fn bare_value(tok: &str) -> Value {
276	    let t = tok.trim();
277	    if t.eq_ignore_ascii_case("null") {
278	        return Value::Null;
279	    }
280	    if t.eq_ignore_ascii_case("true") {
281	        return Value::Bool(true);
282	    }
283	    if t.eq_ignore_ascii_case("false") {
284	        return Value::Bool(false);
285	    }
286	    if let Ok(n) = t.parse::<i64>() {
287	        return Value::Number(n.into());
288	    }
289	    if let Ok(f) = t.parse::<f64>() {
290	        if let Some(n) = serde_json::Number::from_f64(f) {
291	            return Value::Number(n);
292	        }
293	    }
294	    Value::String(t.to_string())
295	}
