297	fn emit_tuple(
298	    table: &str,
299	    cols: &[String],
300	    values: &mut Vec<Value>,
301	    stmt: u64,
302	    tuple_ord: &mut u64,
303	    sink: Sink,
304	    stats: &mut ExtractStats,
305	) -> bool {
306	    let vals = std::mem::take(values);
307	    if table.is_empty() {
308	        stats.junk += 1;
309	        return true;
310	    }
311	    let mut fields = Map::new();
312	    for (j, v) in vals.into_iter().enumerate() {
313	        if v.is_null() {
314	            continue;
315	        }
316	        let name = cols
317	            .get(j)
318	            .cloned()
319	            .unwrap_or_else(|| format!("col_{}", j + 1));
320	        let v = match v {
321	            Value::String(s) => Value::String(fix_utf8(&s)),
322	            other => other,
323	        };
324	        fields.insert(name, v);
325	    }
326	    let loc = format!("t{table}:s{stmt}:t{tuple_ord}");
327	    *tuple_ord += 1;
328	    if fields.is_empty() {
329	        return true;
330	    }
331	    stats.records += 1;
332	    sink(RawRecord {
333	        fields,
334	        locator: loc,
335	        group: Some(table.to_string()),
336	        origin: FieldOrigin::Data,
337	    })
338	}
