340	/// `INSERT INTO `t` (a,b,c) VALUES` → (table, [cols])
341	fn parse_insert_head(head: &[u8]) -> Option<(String, Vec<String>)> {
342	    let head = &String::from_utf8_lossy(head);
343	    let re = regex::Regex::new(
344	        r#"(?is)^\s*insert\s+(?:ignore\s+)?into\s+[`"]?([A-Za-z0-9_.$-]+)[`"]?\s*(\(([^)]*)\))?\s*values\s*$"#,
345	    )
346	    .ok()?;
347	    let c = re.captures(head)?;
348	    let table = c.get(1)?.as_str().trim_matches('`').to_string();
349	    let cols = c
350	        .get(3)
351	        .map(|m| {
352	            m.as_str()
353	                .split(',')
354	                .map(|s| sanitize_field_name(s.trim().trim_matches(['`', '"', ' '])))
355	                .filter(|s| !s.is_empty())
356	                .collect()
357	        })
358	        .unwrap_or_default();
359	    Some((table, cols))
360	}
