362	/// Capture column names from a complete CREATE TABLE statement head.
363	fn process_statement_head(head: &[u8], tables: &mut HashMap<String, Vec<String>>) {
364	    let head = String::from_utf8_lossy(head);
365	    let trimmed = head.trim_start();
366	    // Compare as BYTES.  `trimmed.len()` is a byte length, so the old
367	    // `len() < 12 || !trimmed[..12]` guard admitted any input whose 12th byte
368	    // lands inside a multi-byte character and then panicked slicing it — the
369	    // same failure the buffer comment above describes, surviving here in `&str`
370	    // form.  Real input hit it: a ClickHouse fixture containing 'ا' and another
371	    // containing '设' each aborted the whole `autoindex` run (the workspace
372	    // builds with `panic = "abort"`, so one bad file kills every other file's
373	    // work).  `get(..12)` on `&[u8]` cannot split a character and returns None
374	    // when the input is short, folding both guards into one total operation.
375	    if !trimmed
376	        .as_bytes()
377	        .get(..12)
378	        .is_some_and(|b| b.eq_ignore_ascii_case(b"create table"))
379	    {
380	        return;
381	    }
382	    let name_re = regex::Regex::new(
383	        r#"(?is)^\s*create\s+table\s+(?:if\s+not\s+exists\s+)?[`"]?([A-Za-z0-9_.$-]+)[`"]?\s*\("#,
384	    )
385	    .unwrap();
386	    let Some(c) = name_re.captures(trimmed) else {
387	        return;
388	    };
389	    let table = c.get(1).unwrap().as_str().to_string();
390	    let body_start = c.get(0).unwrap().end();
391	    // matching close paren at depth 0
392	    let body = &trimmed[body_start..];
393	    let mut depth = 1i32;
394	    let mut end = body.len();
395	    let mut quote: Option<char> = None;
396	    for (i, ch) in body.char_indices() {
397	        match quote {
398	            Some(q) => {
399	                if ch == q {
400	                    quote = None;
401	                }
402	            }
403	            None => match ch {
404	                '\'' | '"' | '`' => quote = Some(ch),
405	                '(' => depth += 1,
406	                ')' => {
407	                    depth -= 1;
408	                    if depth == 0 {
409	                        end = i;
410	                        break;
411	                    }
412	                }
413	                _ => {}
414	            },
415	        }
416	    }
417	    let body = &body[..end];
418	    // split at top-level commas
419	    let mut cols = Vec::new();
420	    let mut depth = 0i32;
421	    let mut quote: Option<char> = None;
422	    let mut part = String::new();
423	    let mut parts: Vec<String> = Vec::new();
424	    for ch in body.chars() {
425	        match quote {
426	            Some(q) => {
427	                if ch == q {
428	                    quote = None;
429	                }
430	                part.push(ch);
431	            }
432	            None => match ch {
433	                '\'' | '"' | '`' => {
434	                    quote = Some(ch);
435	                    part.push(ch);
436	                }
437	                '(' => {
438	                    depth += 1;
439	                    part.push(ch);
440	                }
441	                ')' => {
442	                    depth -= 1;
443	                    part.push(ch);
444	                }
445	                ',' if depth == 0 => parts.push(std::mem::take(&mut part)),
446	                _ => part.push(ch),
447	            },
448	        }
449	    }
450	    parts.push(part);
451	    const NON_COLS: [&str; 8] = [
452	        "primary",
453	        "key",
454	        "unique",
455	        "constraint",
456	        "foreign",
457	        "index",
458	        "check",
459	        "fulltext",
460	    ];
461	    for p in parts {
462	        let p = p.trim();
463	        if p.is_empty() {
464	            continue;
465	        }
466	        let first_word: String = p
467	            .chars()
468	            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
469	            .collect::<String>()
470	            .to_lowercase();
471	        if p.starts_with('`') || p.starts_with('"') {
472	            let q = p.chars().next().unwrap();
473	            if let Some(e) = p[1..].find(q) {
474	                cols.push(sanitize_field_name(&p[1..1 + e]));
475	                continue;
476	            }
477	        }
478	        if !first_word.is_empty() && !NON_COLS.contains(&first_word.as_str()) {
479	            cols.push(sanitize_field_name(&first_word));
480	        }
481	    }
482	    if !cols.is_empty() {
483	        tables.insert(table, cols);
484	    }
485	}
