525	/// Leading-ASCII-whitespace trim over a raw byte buffer (the `str::trim_start`
526	/// equivalent that needs no UTF-8 validity).
527	fn trim_start_bytes(b: &[u8]) -> &[u8] {
528	    let mut i = 0;
529	    while i < b.len() && b[i].is_ascii_whitespace() {
530	        i += 1;
531	    }
532	    &b[i..]
533	}
