535	/// Drain a raw value buffer into a `String`, decoding UTF-8 once at the
536	/// boundary.  Invalid sequences become U+FFFD rather than mojibake — the
537	/// previous per-byte `as char` cast turned every multi-byte character into two
538	/// Latin-1 characters.
539	fn take_utf8(buf: &mut Vec<u8>) -> String {
540	    let s = String::from_utf8_lossy(buf).into_owned();
541	    buf.clear();
542	    s
543	}
