549	    /// Regression: the head/value buffers used to be `String`s fed with
550	    /// `b as char`, which turns any byte >= 0x80 into a Latin-1 codepoint that
551	    /// re-encodes to TWO UTF-8 bytes. Byte offsets into the buffer then stopped
552	    /// being char boundaries and `head[..6]` panicked — and with
553	    /// `panic = "abort"` that killed the entire `autoindex` run instead of
554	    /// skipping one file. An em-dash in a comment was enough to trigger it.
555	    #[test]
556	    fn trim_start_bytes_handles_multibyte_without_panicking() {
557	        // "  — INSERT INTO t VALUES" — the em-dash is 3 UTF-8 bytes.
558	        let raw = "  — INSERT INTO t VALUES".as_bytes();
559	        let t = trim_start_bytes(raw);
560	        assert!(!t.is_empty());
561	        assert!(!t[0].is_ascii_whitespace());
562	        // The slice that used to panic is now a plain byte slice.
563	        assert!(t.len() >= 6);
564	        let _ = &t[..6];
565	    }
566	
567	    /// Regression: `process_statement_head` guarded with `trimmed.len() < 12`
568	    /// (a BYTE length) and then sliced `trimmed[..12]` on a `&str`. Any head
569	    /// whose 12th byte lands inside a multi-byte character passed the guard and
570	    /// panicked on the slice. Found by indexing ClickHouse: fixtures containing
571	    /// 'ا' and '设' each aborted the whole `autoindex` run (`panic = "abort"`).
572	    /// Neither of these heads is a CREATE TABLE — the only correct behaviour is
573	    /// to return quietly, never to abort the process.
574	    #[test]
575	    fn statement_head_with_multibyte_at_byte_12_does_not_panic() {
576	        let mut tables: HashMap<String, Vec<String>> = HashMap::new();
577	        for head in [
578	            "-- comment ا rest of the line", // 'ا' spans bytes 11..13
579	            "-- comment 设计 rest",          // '设' spans bytes 11..14
580	            "  — leading em-dash then text", // multibyte before byte 12
581	            "短",                            // shorter than 12 bytes
582	            "",
583	        ] {
584	            process_statement_head(head.as_bytes(), &mut tables);
585	        }
586	        assert!(tables.is_empty(), "none of these heads declare a table");
587	    }
588	
589	    /// The byte-wise comparison must still accept a real CREATE TABLE, in any
590	    /// case, and must not regress into matching a mere prefix.
591	    #[test]
592	    fn statement_head_still_captures_create_table() {
593	        let mut tables: HashMap<String, Vec<String>> = HashMap::new();
594	        process_statement_head(b"  CrEaTe TaBlE users (id INT, name TEXT)", &mut tables);
595	        assert_eq!(
596	            tables.get("users").map(|c| c.len()),
597	            Some(2),
598	            "case-insensitive CREATE TABLE must still be captured"
599	        );
600	
601	        let mut other: HashMap<String, Vec<String>> = HashMap::new();
602	        process_statement_head("create tableX ا (id INT)".as_bytes(), &mut other);
603	        assert!(other.is_empty(), "`create tableX` is not `create table`");
604	    }
