628	                   //! No sqlparser: multi-row `INSERT … VALUES (…),(…)…` statements —\n\
629	                   //! parsed byte-by-byte.\n";
630	        // Drive the same keyword-detection logic the streaming loop runs.
631	        let mut head: Vec<u8> = Vec::new();
632	        for b in src.as_bytes() {
