1	//! Plain text: prose files become one document record (title = first line,
2	//! body split into ~32KB sections); line-oriented files become overlapping
3	//! line-window chunks.
4	//!
5	//! ## Why line-oriented text is chunked, not emitted per line
6	//!
7	//! `extract_lines` used to emit ONE record per line. That makes BM25 nearly
8	//! useless for anything but exact-substring lookup: relevance is scored per
9	//! document, so a single line can only match when it literally contains the
10	//! query terms. A question phrased in its own words — the normal case for an
11	//! agent — matches nothing, because no single line carries all of it.
12	//!
13	//! Measured on this repository (234 files, 170k LOC + docs + 460 commit
14	//! messages), answering 8 "where/why is X" questions:
15	//!
16	//!   one record per line ....... 3/8 answers found
17	//!   40-line windows, 10 overlap 8/8 answers found
18	//!
19	//! The window carries enough surrounding context that a natural-language
20	//! query matches the region, and the overlap stops an answer from being split
21	//! across a boundary. `start_line` / `end_line` travel with each chunk so a
22	//! caller can jump straight to the source — the old per-line record only
23	//! carried an opaque byte locator.
24	
25	use super::{emit_document, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_RECORDS_PER_FILE};
26	use anyhow::Result;
27	use serde_json::{Map, Value};
28	use std::path::Path;
29	
30	const TXT_CAP: u64 = 16 << 20;
31	
32	/// Lines per chunk, and how many of them the next chunk repeats.  40/10 is the
33	/// configuration measured at 8/8 answer recall (see module docs); the overlap
34	/// is what keeps an answer that straddles a boundary retrievable from both
35	/// sides.
36	const CHUNK_LINES: usize = 40;
37	const CHUNK_OVERLAP: usize = 10;
38	/// Byte ceiling per chunk, so a file of very long lines cannot produce a
39	/// multi-megabyte record that would blow up `_source` on every hit.
40	const CHUNK_MAX_BYTES: usize = 8 << 10;
41	
42	pub fn extract_prose(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
43	    let mut stats = ExtractStats::default();
44	    let Some(bytes) = super::read_whole(path, gzip, TXT_CAP)? else {
45	        stats.junk += 1;
46	        return Ok(stats);
47	    };
48	    let (text, _) = crate::sniff::decode_text(&bytes);
49	    let title = text
50	        .lines()
51	        .find(|l| !l.trim().is_empty())
52	        .map(|l| {
53	            let t = l.trim();
54	            let mut s: String = t.chars().take(200).collect();
55	            if s.len() < t.len() {
56	                s.push('…');
57	            }
58	            s
59	        })
60	        .unwrap_or_else(|| {
61	            path.file_stem()
62	                .map(|s| s.to_string_lossy().to_string())
63	                .unwrap_or_else(|| "untitled".into())
64	        });
65	    emit_document(
66	        &title,
67	        &[],
68	        text.trim(),
69	        MAX_RECORDS_PER_FILE,
70	        sink,
71	        &mut stats,
72	    );
73	    Ok(stats)
74	}
75	
76	pub fn extract_lines(
77	    path: &Path,
78	    gzip: bool,
79	    limit_bytes: Option<u64>,
80	    sink: Sink,
81	) -> Result<ExtractStats> {
82	    let mut r = super::open_reader(path, gzip, limit_bytes)?;
83	    let mut stats = ExtractStats::default();
84	    let mut offset = 0u64;
85	    let mut buf: Vec<u8> = Vec::new();
86	
87	    // Sliding window over non-blank lines.  Each entry carries the line's text,
88	    // its 1-based line number, and the byte offset it started at (the offset of
89	    // the window's first line becomes the chunk locator, so ids stay stable
90	    // across re-runs exactly like the old per-line records did).
91	    let mut window: Vec<(String, usize, u64)> = Vec::with_capacity(CHUNK_LINES);
92	    let mut line_no = 0usize;
93	    let mut stopped = false;
94	
95	    // Emit `window[..CHUNK_LINES]` as one record, then drop the non-overlapping
96	    // prefix.  Returns false when the sink asks us to stop.
97	    fn flush(
98	        window: &mut Vec<(String, usize, u64)>,
99	        drain: bool,
100	        stats: &mut ExtractStats,
101	        sink: Sink,
102	    ) -> bool {
103	        if window.is_empty() {
104	            return true;
105	        }
106	        let mut text = String::new();
107	        let mut used = 0usize;
108	        for (l, _, _) in window.iter() {
109	            if used > 0 && used + l.len() + 1 > CHUNK_MAX_BYTES {
110	                break;
111	            }
112	            if used > 0 {
113	                text.push('\n');
114	            }
115	            text.push_str(l);
116	            used += l.len() + 1;
117	        }
118	        if text.trim().is_empty() {
119	            return true;
120	        }
121	        let start_line = window[0].1;
122	        let start_byte = window[0].2;
123	        let end_line = window[window.len() - 1].1;
124	
125	        let mut fields = Map::new();
126	        fields.insert("text".into(), Value::String(text));
127	        fields.insert(
128	            "start_line".into(),
129	            Value::Number((start_line as u64).into()),
130	        );
131	        fields.insert("end_line".into(), Value::Number((end_line as u64).into()));
132	        stats.records += 1;
133	        let ok = sink(RawRecord {
134	            fields,
135	            locator: format!("b{start_byte}"),
136	            group: None,
137	            // text/start_line/end_line describe this chunker, not the file.
138	            origin: FieldOrigin::Extractor,
139	        });
140	        if drain {
141	            window.clear();
142	        } else {
143	            let keep = CHUNK_OVERLAP.min(window.len());
144	            window.drain(..window.len() - keep);
145	        }
146	        ok
147	    }
148	
149	    loop {
150	        buf.clear();
151	        let n = super::jsonl::read_capped_line(&mut r, &mut buf)?;
152	        if n == 0 {
153	            break;
154	        }
155	        let start = offset;
156	        offset += n as u64;
157	        line_no += 1;
158	        let (line, _) = crate::sniff::decode_text(&buf);
159	        let line = line.trim_end_matches(['\n', '\r']);
160	        if line.trim().is_empty() {
161	            continue;
162	        }
163	        window.push((line.to_string(), line_no, start));
164	        if window.len() >= CHUNK_LINES && !flush(&mut window, false, &mut stats, sink) {
165	            stopped = true;
166	            break;
167	        }
168	    }
169	    // Trailing partial window (also the whole-file case for short files).
170	    if !stopped {
171	        flush(&mut window, true, &mut stats, sink);
172	    }
173	    Ok(stats)
174	}
