217	    /// The property that fixed retrieval: consecutive chunks OVERLAP, so an
218	    /// answer straddling a boundary is findable from either side.
219	    #[test]
220	    fn consecutive_chunks_overlap_by_the_configured_amount() {
221	        let lines: Vec<String> = (1..=100).map(|i| format!("line {i}")).collect();
222	        let refs: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
223	        let out = run(&refs);
