211	pub fn extract(
212	    path: &Path,
213	    gzip: bool,
214	    limit_bytes: Option<u64>,
215	    sink: Sink,
216	) -> Result<ExtractStats> {
217	    let mut r = super::open_reader(path, gzip, limit_bytes)?;
218	    let mut stats = ExtractStats::default();
219	
220	    // Election pass state: elect from the first 200 parsed lines.
221	    let mut elected: Option<Kind> = None;
222	    let mut votes: std::collections::HashMap<Kind, usize> = Default::default();
223	    let mut seen = 0usize;
224	
225	    let mut offset: u64 = 0;
226	    let mut line_buf: Vec<u8> = Vec::new();
227	    let mut pending: Option<RawRecord> = None; // last record, may absorb continuations
228	
229	    loop {
230	        line_buf.clear();
231	        let n = super::jsonl::read_capped_line(&mut r, &mut line_buf)?;
232	        if n == 0 {
233	            break;
234	        }
235	        let start = offset;
236	        offset += n as u64;
237	        let (line, _) = crate::sniff::decode_text(&line_buf);
238	        let line = line.trim_end_matches(['\n', '\r']);
239	        if line.trim().is_empty() {
240	            continue;
241	        }
242	        let kind = match elected {
243	            Some(k) => parse_kind(line).filter(|&pk| pk == k).or(Some(k)),
244	            None => {
245	                let pk = parse_kind(line);
246	                if let Some(k) = pk {
247	                    *votes.entry(k).or_default() += 1;
248	                }
249	                seen += 1;
250	                if seen >= 200 || votes.values().sum::<usize>() >= 120 {
251	                    elected = elect_kind(&votes);
252	                }
253	                pk.or(elected)
254	            }
255	        };
256	        let parsed = kind.and_then(|k| parse_line(line, k));
257	        match parsed {
258	            Some(fields) => {
259	                if let Some(rec) = pending.take() {
260	                    stats.records += 1;
261	                    if !sink(rec) {
262	                        return Ok(stats);
263	                    }
264	                }
265	                pending = Some(RawRecord {
266	                    fields,
267	                    locator: format!("b{start}"),
268	                    group: None,
269	                    origin: FieldOrigin::Data,
270	                });
271	            }
272	            None => {
273	                // continuation line: append to previous message
274	                match pending.as_mut() {
275	                    Some(rec) => {
276	                        let msg = rec
277	                            .fields
278	                            .entry("message")
279	                            .or_insert(Value::String(String::new()));
280	                        if let Value::String(s) = msg {
281	                            if s.len() < super::MAX_LINE {
282	                                s.push('\n');
283	                                s.push_str(line);
284	                            }
285	                        }
286	                    }
287	                    None => stats.junk += 1,
288	                }
289	            }
290	        }
291	    }
292	    if let Some(rec) = pending {
293	        stats.records += 1;
294	        sink(rec);
295	    }
296	    Ok(stats)
297	}
