502	/// The message with an undeclared 8-bit HEADER BLOCK re-read as Windows-1252,
503	/// or `None` when the block is already UTF-8 (the overwhelmingly common case,
504	/// which costs one validation pass over the headers and no copy).
505	///
506	/// The block ends at the first empty line. Everything after it is copied
507	/// byte for byte, so part offsets inside the body keep their meaning.
508	fn transcode_8bit_headers(bytes: &[u8]) -> Option<Vec<u8>> {
509	    let end = header_block_end(bytes);
510	    let head = bytes.get(..end)?;
511	    if std::str::from_utf8(head).is_ok() {
512	        return None;
513	    }
514	    let (text, _) = encoding_rs::WINDOWS_1252.decode_without_bom_handling(head);
515	    let mut out = Vec::with_capacity(text.len() + bytes.len().saturating_sub(end));
516	    out.extend_from_slice(text.as_bytes());
517	    out.extend_from_slice(bytes.get(end..)?);
518	    Some(out)
519	}
