521	/// Index just past the header block: the first `\n` that is followed by an
522	/// empty line (`\n` or `\r\n`), or the whole input when there is none.
523	fn header_block_end(bytes: &[u8]) -> usize {
524	    // An input that OPENS with an empty line has no header block at all; what
525	    // follows is body, and the body has its own rule.
526	    if matches!(bytes, [b'\n', ..] | [b'\r', b'\n', ..]) {
527	        return 0;
528	    }
529	    let mut from = 0usize;
530	    while let Some(i) = memchr::memchr(b'\n', bytes.get(from..).unwrap_or(&[])) {
531	        let nl = from + i;
532	        match bytes.get(nl + 1..) {
533	            Some([b'\n', ..]) | Some([b'\r', b'\n', ..]) => return nl + 1,
534	            _ => from = nl + 1,
535	        }
536	    }
537	    bytes.len()
538	}
