1	//! Email (RFC 5322 / MIME) extraction.
2	//!
3	//! An `.eml` (or any `message/rfc822`) file used to fall through to the prose
4	//! extractor: its headers were dumped as body text, its MIME structure was left
5	//! raw, and a base64 attachment was indexed verbatim as gibberish — one message
6	//! exploding into many noise records. This parses the message properly and emits:
7	//!
8	//! - ONE (or, for a long body, a few section) record(s) for the MESSAGE itself,
9	//!   carrying decoded header fields (`email_from`/`email_to`/`email_subject`/
10	//!   `email_date`/`email_message_id`/…) and the decoded plain-text body.
11	//! - ONE OR MORE records PER ATTACHMENT, indexed SEPARATELY and linked back to
12	//!   the parent by `email_message_id`/`email_subject`/`email_from`. A PDF
13	//!   attachment is routed through the real PDF extractor (per-page records); a
14	//!   text attachment is sectioned as a document; any other file gets a
15	//!   name/type/size card so it is still findable by name.
16	//!
17	//! Header/body field names are the extractor's own vocabulary
18	//! (`FieldOrigin::Extractor`): present on every email, so they never move a file
19	//! between datasets.
20	//!
21	//! The per-message work lives in [`emit_message`], which takes BYTES rather
22	//! than a path, so a container of messages (`extract::mbox` — a Google Takeout
23	//! or Thunderbird mailbox) produces records of exactly the same shape as a
24	//! standalone `.eml`: same fields, same locators, only namespaced by the
25	//! message's position in its container (`m{offset}-msg-s0` vs `msg-s0`).
26	
27	use super::{emit_document_with_fields, read_whole, ExtractStats, FieldOrigin, RawRecord, Sink};
28	use anyhow::Result;
29	use mail_parser::{MessageParser, MimeHeaders, PartType};
30	use serde_json::{Map, Value};
31	use std::path::Path;
32	
33	/// Whole-message read cap. Mailbox exports of a single message rarely approach
34	/// this; a message larger than it is treated as junk rather than parsed.
35	pub(crate) const MAX_EML: u64 = 64 << 20;
36	
37	/// A message with more parts than this has its tail dropped (reported via
38	/// `ExtractStats.truncated`) — a defensive bound on a pathological MIME bomb.
39	const MAX_ATTACHMENTS: usize = 256;
40	
41	/// Bytes of an attachment we are willing to route/section. Larger attachments
42	/// get a name card only (their bytes are not indexed).
43	const MAX_ATTACH_BYTES: usize = 24 << 20;
44	
45	/// `References:` ids kept per message. A thread hundreds of replies deep
46	/// carries one id per ancestor; the thread detector only ever needs the
47	/// nearest resolvable one, and the tail of the list is the nearest.
48	const MAX_REFERENCES: usize = 64;
49	
50	/// Bare addresses kept per address header (`email_to_address`, …). A mailing
51	/// list blast can name thousands of recipients; the full header text stays in
52	/// `email_to`, and the filterable list is bounded like every other per-message
53	/// list here.
54	const MAX_ADDRESSES: usize = 1024;
55	
56	/// Characters of the subject repeated at the head of the searchable body. The
57	/// whole subject is always in `email_subject`; this bounds what a pathological
58	/// 100 KB subject can add to the first section.
59	const SUBJECT_IN_BODY_CHARS: usize = 512;
