61	/// Where a message sits when it is not a file of its own.
62	#[derive(Debug, Default, Clone)]
63	pub(crate) struct MessageEnvelope<'a> {
64	    /// Prepended to every locator this message emits. Empty for a standalone
65	    /// `.eml`; `m{byte offset}-` inside an mbox, so two messages of one
66	    /// container can never collide on `msg-s0`.
67	    pub loc_prefix: &'a str,
68	    /// RFC 3339 delivery time from the container (the mbox `From ` line). Used
69	    /// for `email_date` ONLY when the message has no parseable `Date:` header
70	    /// of its own — the header is what the sender wrote and always wins.
71	    pub fallback_date: Option<String>,
72	}
