74	/// What [`emit_message`] did with the bytes it was handed.
75	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
76	pub(crate) enum MessageOutcome {
77	    /// Parsed and emitted. `alive` is the sink's last answer: `false` means the
78	    /// caller must stop extracting (phase-A sampling has what it needs).
79	    Emitted { alive: bool },
80	    /// Not parseable as a message at all; nothing was emitted. The caller
81	    /// decides the fallback (a file is re-read as prose, an mbox entry is
82	    /// indexed as raw text).
