86	pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
87	    let mut stats = ExtractStats::default();
88	    let Some(bytes) = read_whole(path, gzip, MAX_EML)? else {
89	        stats.junk += 1;
90	        return Ok(stats);
91	    };
92	    match emit_message(&bytes, &MessageEnvelope::default(), sink, &mut stats) {
93	        // Unparseable as a message — fall back to indexing it as prose rather
94	        // than dropping it, matching the never-fatal contract.
95	        MessageOutcome::Unparseable => super::extract_as_document(path, gzip, sink),
96	        MessageOutcome::Emitted { .. } => Ok(stats),
97	    }
98	}
