100	/// An unstructured header mail-parser has no registered grammar for, decoded.
101	///
102	/// The default parser leaves such headers RAW, and Gmail writes a non-ASCII
103	/// label as an RFC 2047 encoded-word (`=?UTF-8?B?…?=`). Registering a custom
104	/// grammar on the parser is not an option: a non-empty `header_map` REPLACES
105	/// the built-in dispatch, and `From`/`To`/`Date` silently stop being parsed.
106	/// `header_as` re-reads just this header's bytes as text instead.
107	fn text_header(msg: &mail_parser::Message<'_>, name: &'static str) -> Option<String> {
108	    msg.header_as(name, mail_parser::HeaderForm::Text)
109	        .into_iter()
110	        .find_map(|v| v.as_text().map(|t| t.trim().to_string()))
111	        .filter(|t| !t.is_empty())
112	}
