114	/// Parse ONE message from `bytes` and emit its message + attachment records.
115	///
116	/// Shared by the `.eml` path above and the mbox container (`extract::mbox`),
117	/// which is what keeps the two record shapes identical.
118	pub(crate) fn emit_message(
119	    bytes: &[u8],
120	    env: &MessageEnvelope<'_>,
121	    sink: Sink,
122	    stats: &mut ExtractStats,
123	) -> MessageOutcome {
124	    // Raw 8-bit bytes in the HEADER block (no RFC 2047 encoded-word, not
125	    // UTF-8) are what a generation of European desktop clients wrote. The
126	    // parser reads headers as UTF-8, so `Grüße` became `Gr\u{fffd}\u{fffd}e`
127	    // and `Zoë Müller` lost her name — while the body of the same message was
128	    // already rescued by `undeclared_8bit_body`. Same situation, same rule:
129	    // UTF-8, else Windows-1252. Only the header block is re-read; the body
130	    // bytes are passed through untouched so every MIME offset stays valid.
131	    let transcoded = transcode_8bit_headers(bytes);
132	    let bytes = transcoded.as_deref().unwrap_or(bytes);
133	    let Some(msg) = MessageParser::default().parse(bytes) else {
134	        return MessageOutcome::Unparseable;
135	    };
136	    let pre = env.loc_prefix;
137	
138	    // ── message header fields (decoded: encoded-words, charset) ──
139	    let subject = msg.subject().unwrap_or("").trim().to_string();
140	    let mut headers = Map::new();
141	    put(&mut headers, "email_subject", subject.clone());
142	    put(&mut headers, "email_from", addr_string(msg.from()));
143	    put(&mut headers, "email_to", addr_string(msg.to()));
144	    put(&mut headers, "email_cc", addr_string(msg.cc()));
145	    // `email_from` is the header as a person reads it — `Dana Klein
146	    // <dklein@amazon.com>` — and it is a keyword, so a `term` filter on the
147	    // bare address matches NOTHING (review finding on PR #949: the documented
148	    // "every message from one sender" query returned 0 hits on every mailbox
149	    // whose senders have display names, which is nearly all of them). The
150	    // bare, lower-cased addresses are what a filter is written against, so
151	    // they get fields of their own; the display form stays for reading.
152	    for (field, header) in [
153	        ("email_from_address", msg.from()),
154	        ("email_to_address", msg.to()),
155	        ("email_cc_address", msg.cc()),
156	    ] {
157	        let list = addr_list(header);
158	        if !list.is_empty() {
159	            headers.insert(field.into(), Value::Array(list));
160	        }
161	    }
162	    if let Some(d) = msg.date() {
163	        put(&mut headers, "email_date", d.to_rfc3339());
164	    }
165	    if let Some(id) = msg.message_id() {
166	        put(&mut headers, "email_message_id", id.to_string());
167	    }
168	    if let Some(irt) = msg.in_reply_to().as_text() {
169	        put(&mut headers, "email_in_reply_to", irt.to_string());
170	    }
171	    // `References:` — the ancestor chain, oldest first. Kept as a list so the
172	    // thread detector can still resolve a parent when `In-Reply-To` is absent
173	    // or names a message that is not in the corpus. The TAIL is kept when the
174	    // list is over the cap: the nearest ancestors are the useful ones.
175	    if let Some(refs) = msg.references().as_text_list() {
176	        let skip = refs.len().saturating_sub(MAX_REFERENCES);
177	        let ids: Vec<Value> = refs
178	            .iter()
179	            .skip(skip)
180	            .map(|r| r.trim())
181	            .filter(|r| !r.is_empty())
182	            .map(|r| Value::String(r.to_string()))
183	            .collect();
184	        if !ids.is_empty() {
185	            headers.insert("email_references".into(), Value::Array(ids));
186	        }
187	    }
188	    // Gmail (Google Takeout) stamps every exported message with its labels and
189	    // its conversation id. Labels are how a reader separates `Inbox` from
190	    // `Spam`/`Trash` in an "All mail Including Spam and Trash" export, so they
191	    // are indexed rather than used to silently drop mail. Absent everywhere
192	    // else, which is why both are optional fields and not part of the shape.
193	    if let Some(labels) = text_header(&msg, "X-Gmail-Labels") {
194	        let labels: Vec<Value> = labels
195	            .split(',')
196	            .map(str::trim)
197	            .filter(|l| !l.is_empty())
198	            .map(|l| Value::String(l.to_string()))
199	            .collect();
200	        if !labels.is_empty() {
201	            headers.insert("email_labels".into(), Value::Array(labels));
202	        }
203	    }
204	    if let Some(thread) = text_header(&msg, "X-GM-THRID") {
205	        // Gmail writes the conversation id in decimal; its own API and URLs
206	        // (`#all/18c0f2a5b3d4e6f7`) use the same number in hex. Hex is kept
207	        // because it is the form a user can paste back into Gmail, and because
208	        // a column of 19-digit decimals is inferred as `long`: the id is a
209	        // u64, and `coerce_value` sends a digit string past i64::MAX through
210	        // f64, where it SATURATES — every such thread would silently share
211	        // one id. A hex string is never inferred as a number.
212	        let id = thread
213	            .parse::<u64>()
214	            .map(|n| format!("{n:x}"))
215	            .unwrap_or(thread);
216	        put(&mut headers, "email_thread_id", id);
217	    }
218	
219	    let title = if subject.is_empty() {
220	        "(no subject)".to_string()
221	    } else {
222	        subject.clone()
223	    };
224	
225	    // ── message body: prefer decoded text/plain, else strip the HTML part ──
226	    let body = undeclared_8bit_body(&msg)
227	        .or_else(|| msg.body_text(0).map(|c| c.to_string()))
228	        .map(|t| unix_eol(&t))
229	        .or_else(|| msg.body_html(0).map(|h| strip_html(&h)))
230	        .unwrap_or_default();
231	
232	    // Nothing at all: no header this extractor reads, no body text, no parts.
233	    // mail-parser accepts a lone blank line as a (header-less, body-less)
234	    // message, which is what a separator-only mbox entry or a truncated file
235	    // hands it — and "(no subject)" with an empty body is not a document, it
236	    // is a hole in every result list. The caller's fallback decides: a file is
237	    // re-read as prose, an mbox entry with no text is junk.
238	    //
239	    // Tested BEFORE the container's fallback date is applied: that date comes
240	    // from the mbox separator, not from the message, and every mbox entry has
241	    // one — counting it would make an empty entry look like it had a header.
242	    if headers.is_empty() && body.trim().is_empty() && msg.attachments().next().is_none() {
243	        return MessageOutcome::Unparseable;
244	    }
245	    if !headers.contains_key("email_date") {
246	        if let Some(fallback) = env.fallback_date.as_deref() {
247	            put(&mut headers, "email_date", fallback.to_string());
248	        }
249	    }
250	
251	    // The subject opens the searchable text. `title` and `email_subject` are
252	    // inferred as KEYWORD on a mailbox (few distinct values per record: every
253	    // section and attachment of a thread repeats them), and a keyword matches
254	    // only as a whole — so `xerj search Rechnung` and `match` on any field
255	    // found nothing for a word that was only in a Subject, which is the first
256	    // place a person looks (review finding on PR #949). A subject is a line of
257	    // the message a reader sees above the body, so that is where it goes: the
258	    // first paragraph of the first section, once, never on attachments.
259	    let searchable = with_subject(&subject, body.trim());
260	
261	    // Emit the message itself as document section(s) carrying the headers.
262	    if !emit_document_with_fields(
263	        &headers,
264	        &title,
265	        &searchable,
266	        &format!("{pre}msg"),
267	        sink,
268	        stats,
269	    ) {
270	        return MessageOutcome::Emitted { alive: false };
271	    }
272	
273	    // ── attachments — each indexed as its own document(s) ──
274	    for (n, part) in msg.attachments().enumerate() {
275	        if n >= MAX_ATTACHMENTS {
276	            stats.truncated = true;
277	            break;
278	        }
279	        let name = part
280	            .attachment_name()
281	            .map(str::to_string)
282	            .unwrap_or_else(|| format!("attachment-{n}"));
283	        let ctype = part
284	            .content_type()
285	            .map(|c| {
286	                let mut s = c.ctype().to_string();
287	                if let Some(sub) = c.subtype() {
288	                    s.push('/');
289	                    s.push_str(sub);
290	                }
291	                s
292	            })
293	            .unwrap_or_default();
294	        let data: &[u8] = match &part.body {
295	            PartType::Binary(b) | PartType::InlineBinary(b) => b.as_ref(),
296	            PartType::Text(t) | PartType::Html(t) => t.as_bytes(),
297	            _ => &[],
298	        };
299	        let link = attach_link(&headers, &name, &ctype, data.len());
300	
301	        let alive = if is_pdf(&name, data) && data.len() <= MAX_ATTACH_BYTES {
302	            route_pdf(data, &format!("{pre}att{n}-"), &link, sink, stats)
303	        } else if is_texty(&ctype, data) && data.len() <= MAX_ATTACH_BYTES {
304	            let text = unix_eol(&String::from_utf8_lossy(data));
305	            emit_document_with_fields(
306	                &link,
307	                &name,
308	                text.trim(),
309	                &format!("{pre}att{n}"),
310	                sink,
311	                stats,
312	            )
313	        } else {
314	            // Unindexable body — a name/type/size card keeps it discoverable.
315	            stats.records += 1;
316	            sink(RawRecord {
317	                fields: link,
318	                locator: format!("{pre}att{n}-card"),
319	                group: None,
320	                origin: FieldOrigin::Extractor,
321	            })
322	        };
323	        if !alive {
324	            return MessageOutcome::Emitted { alive: false };
325	        }
326	    }
327	
328	    MessageOutcome::Emitted { alive: true }
329	}
