331	/// Route a PDF attachment's bytes through the real PDF extractor, re-tagging
332	/// each emitted page record with the parent-email link fields and a locator
333	/// namespaced to this attachment (`prefix` = `att{n}-`, or `m{offset}-att{n}-`
334	/// inside an mbox).
335	///
336	/// Returns the sink's last answer: `false` = stop extracting.
337	fn route_pdf(
338	    data: &[u8],
339	    prefix: &str,
340	    link: &Map<String, Value>,
341	    sink: Sink,
342	    stats: &mut ExtractStats,
343	) -> bool {
344	    use std::io::Write;
345	    let Ok(mut tmp) = tempfile::Builder::new().suffix(".pdf").tempfile() else {
346	        stats.junk += 1;
347	        return true;
348	    };
349	    if tmp.write_all(data).is_err() {
350	        stats.junk += 1;
351	        return true;
352	    }
353	    let mut alive = true;
354	    let mut pages = 0u64;
355	    let mut inner = |mut rec: RawRecord| -> bool {
356	        for (k, v) in link.iter() {
357	            rec.fields.entry(k.clone()).or_insert_with(|| v.clone());
358	        }
359	        // The PDF extractor titles a page after its file's stem, and the file
360	        // here is a temp file: every page was titled `.tmpXXXXXX`, a different
361	        // name on every run. The attachment has a real name — the same title a
362	        // text attachment gets — and it makes the record stream deterministic.
363	        if let Some(name) = link.get("attachment_name") {
364	            rec.fields.insert("title".into(), name.clone());
365	        }
366	        rec.locator = format!("{prefix}{}", rec.locator);
367	        rec.origin = FieldOrigin::Extractor;
368	        pages += 1;
369	        alive = sink(rec);
370	        alive
371	    };
372	    // The PDF extractor increments its own record count; we count via `inner`
373	    // instead, so start from what it reports and keep only the delta semantics
374	    // simple: ignore its stats.records, trust `inner`.
375	    let parsed = super::pdf::extract(tmp.path(), &mut inner);
376	    stats.records += pages;
377	    if pages == 0 && alive {
378	        // The parser failed, timed out, or found no text layer (a scanned
379	        // PDF). The attachment still EXISTS, and "the contract Dana sent" has
380	        // to stay findable by name — so it gets the same name/type/size card
381	        // any other unindexable attachment gets, instead of vanishing. Counted
382	        // as junk only when the parser actually errored: an image-only PDF is
383	        // not a failure of the file.
384	        if parsed.is_err() {
385	            stats.junk += 1;
386	        }
387	        stats.records += 1;
388	        alive = sink(RawRecord {
389	            fields: link.clone(),
390	            locator: format!("{prefix}card"),
391	            group: None,
392	            origin: FieldOrigin::Extractor,
393	        });
394	    }
395	    alive
396	}
