101	/// Bytes of a line held back while deciding whether it is a separator or a
102	/// quoted `>From `. A real separator is well under 200 bytes; a line that is
103	/// still going after this many bytes is body, whatever it starts with.
104	const HEAD_CAP: usize = 1024;
105	
106	/// UTF-8 byte-order mark.
