135	/// Streaming mbox splitter. `next_message` yields one message at a time.
136	pub struct Splitter<R> {
137	    reader: R,
138	    /// Offset of the next unread byte.
139	    offset: u64,
140	    head: Vec<u8>,
141	    cur: Option<RawMessage>,
142	    cap: usize,
143	    /// Bytes that preceded the first separator (or every byte, in a file with
144	    /// no separator at all). Not part of any message; reported, never indexed.
145	    pub preamble_bytes: u64,
146	    /// The reader is exhausted; only the message in flight is left to yield.
147	    eof: bool,
148	}
149	
150	enum Head {
151	    /// The whole line, including its `\n`, is in `head`.
152	    Complete,
153	    /// `HEAD_CAP` bytes are in `head` and the line is still going.
154	    Partial,
155	    /// Input ended. `head` holds a final unterminated line, or nothing.
156	    Eof,
157	}
158	
159	impl<R: BufRead> Splitter<R> {
160	    pub fn new(reader: R) -> Self {
161	        Self::with_cap(reader, MAX_EML as usize)
162	    }
163	
164	    /// `cap` bounds the bytes retained per message (tests shrink it).
165	    pub fn with_cap(reader: R, cap: usize) -> Self {
166	        Self {
167	            reader,
168	            offset: 0,
169	            head: Vec::with_capacity(HEAD_CAP),
170	            cur: None,
171	            cap,
172	            preamble_bytes: 0,
173	            eof: false,
174	        }
175	    }
176	
177	    /// Bytes consumed from the reader so far.
178	    pub fn consumed(&self) -> u64 {
179	        self.offset
180	    }
181	
182	    fn read_head(&mut self) -> std::io::Result<Head> {
183	        self.head.clear();
184	        loop {
185	            let buf = self.reader.fill_buf()?;
186	            if buf.is_empty() {
187	                return Ok(Head::Eof);
188	            }
189	            let room = HEAD_CAP - self.head.len();
190	            let window = &buf[..buf.len().min(room)];
191	            match memchr::memchr(b'\n', window) {
192	                Some(i) => {
193	                    self.head.extend_from_slice(&window[..=i]);
194	                    self.reader.consume(i + 1);
195	                    return Ok(Head::Complete);
196	                }
197	                None => {
198	                    let n = window.len();
199	                    self.head.extend_from_slice(window);
200	                    self.reader.consume(n);
201	                    if self.head.len() >= HEAD_CAP {
202	                        return Ok(Head::Partial);
203	                    }
204	                }
205	            }
206	        }
207	    }
208	
209	    /// Append to the message in flight, never past the cap. `total_len` keeps
210	    /// counting so an oversized message is reported with its real size.
211	    fn push(cur: &mut RawMessage, cap: usize, bytes: &[u8]) {
212	        cur.total_len += bytes.len() as u64;
213	        let room = cap.saturating_sub(cur.bytes.len());
214	        if bytes.len() > room {
215	            cur.capped = true;
216	        }
217	        if room > 0 {
218	            cur.bytes.extend_from_slice(&bytes[..bytes.len().min(room)]);
219	        }
220	    }
221	
222	    /// Stream the remainder of an over-long line (everything up to and
223	    /// including its `\n`) into the message in flight, chunk by chunk.
224	    fn drain_line(&mut self) -> std::io::Result<()> {
225	        loop {
226	            let buf = self.reader.fill_buf()?;
227	            if buf.is_empty() {
228	                return Ok(());
229	            }
230	            let (take, done) = match memchr::memchr(b'\n', buf) {
231	                Some(i) => (i + 1, true),
232	                None => (buf.len(), false),
233	            };
234	            match self.cur.as_mut() {
235	                Some(cur) => Self::push(cur, self.cap, &buf[..take]),
236	                None => self.preamble_bytes += take as u64,
237	            }
238	            self.offset += take as u64;
239	            self.reader.consume(take);
240	            if done {
241	                return Ok(());
242	            }
243	        }
244	    }
245	
246	    fn finish(mut msg: RawMessage) -> RawMessage {
247	        // Writers append one blank line after every message; it belongs to the
248	        // container, not to the message. The message's own final newline stays.
249	        // Only when nothing was cut: a capped message does not end where it ends.
250	        if !msg.oversized() {
251	            let strip = if msg.bytes.ends_with(b"\r\n\r\n") {
252	                2
253	            } else if msg.bytes.ends_with(b"\n\n") {
254	                1
255	            } else {
256	                0
257	            };
258	            msg.bytes.truncate(msg.bytes.len() - strip);
259	            msg.total_len -= strip as u64;
260	        }
261	        msg
262	    }
263	
264	    /// The next message, or `None` at end of input.
265	    pub fn next_message(&mut self) -> std::io::Result<Option<RawMessage>> {
266	        if self.eof {
267	            return Ok(self.cur.take().map(Self::finish));
268	        }
269	        loop {
270	            let line_start = self.offset;
271	            let kind = self.read_head()?;
272	            self.offset += self.head.len() as u64;
273	            let complete = !matches!(kind, Head::Partial);
274	            if matches!(kind, Head::Eof) && self.head.is_empty() {
275	                self.eof = true;
276	                return Ok(self.cur.take().map(Self::finish));
277	            }
278	            // A UTF-8 byte-order mark in front of the FIRST separator. Some
279	            // Windows tools write one when they save or convert a mailbox, and
280	            // with it the first line is not `From …`: the whole first message
281	            // was preamble, and `sniff` junked the file before it got here
282	            // (review finding on PR #949). Dropped at offset 0 only — anywhere
283	            // else `EF BB BF` is three bytes of somebody's text.
284	            if line_start == 0 && self.head.starts_with(UTF8_BOM) {
285	                self.head.drain(..UTF8_BOM.len());
286	            }
287	            if complete && is_from_line(&self.head) {
288	                let done = self.cur.take().map(Self::finish);
289	                self.cur = Some(RawMessage {
290	                    offset: line_start,
291	                    from_line: String::from_utf8_lossy(trim_eol(&self.head)).into_owned(),
292	                    bytes: Vec::new(),
293	                    total_len: 0,
294	                    capped: false,
295	                });
296	                if matches!(kind, Head::Eof) {
297	                    self.eof = true;
298	                }
299	                if done.is_some() {
300	                    return Ok(done);
301	                }
302	                if self.eof {
303	                    return Ok(self.cur.take().map(Self::finish));
304	                }
305	                continue;
306	            }
307	            match self.cur.as_mut() {
308	                Some(cur) => {
309	                    // mboxrd/mboxo: `^>+From ` loses exactly one `>`.
310	                    let skip = usize::from(is_quoted_from(&self.head));
311	                    Self::push(cur, self.cap, &self.head[skip..]);
312	                }
313	                None => self.preamble_bytes += self.head.len() as u64,
314	            }
315	            match kind {
316	                Head::Partial => self.drain_line()?,
317	                Head::Eof => {
318	                    self.eof = true;
319	                    return Ok(self.cur.take().map(Self::finish));
320	                }
321	                Head::Complete => {}
322	            }
323	        }
324	    }
325	}
