332	/// `^>+From ` — a body line a writer quoted so it would not read as a separator.
333	fn is_quoted_from(line: &[u8]) -> bool {
334	    let gt = line.iter().take_while(|b| **b == b'>').count();
335	    gt > 0 && line[gt..].starts_with(b"From ")
336	}
337	
338	const WEEKDAYS: [&[u8]; 7] = [b"mon", b"tue", b"wed", b"thu", b"fri", b"sat", b"sun"];
339	const MONTHS: [&[u8]; 12] = [
340	    b"jan", b"feb", b"mar", b"apr", b"may", b"jun", b"jul", b"aug", b"sep", b"oct", b"nov", b"dec",
341	];
342	
343	fn token_in(tok: &[u8], set: &[&[u8]]) -> Option<usize> {
344	    // `Mon,` is tolerated; some writers keep the RFC 5322 comma.
345	    let tok = tok.strip_suffix(b",").unwrap_or(tok);
346	    set.iter().position(|w| tok.eq_ignore_ascii_case(w))
347	}
348	
349	fn ascii_number(tok: &[u8]) -> Option<u32> {
350	    if tok.is_empty() || tok.len() > 9 || !tok.iter().all(u8::is_ascii_digit) {
351	        return None;
352	    }
353	    // All-ASCII-digit and at most 9 bytes: valid UTF-8 and fits a u32.
354	    std::str::from_utf8(tok).ok()?.parse().ok()
355	}
356	
357	/// `H:MM` or `HH:MM:SS`.
358	fn parse_time(tok: &[u8]) -> Option<(u32, u32, u32)> {
359	    let mut parts = tok.split(|b| *b == b':');
360	    let h = ascii_number(parts.next()?)?;
361	    let m = ascii_number(parts.next()?)?;
362	    let s = match parts.next() {
363	        Some(p) => ascii_number(p)?,
364	        None => 0,
365	    };
366	    (parts.next().is_none() && h < 24 && m < 60 && s < 62).then_some((h, m, s))
367	}
368	
369	/// `+0000` / `-0700` → seconds east of UTC.
370	fn parse_zone(tok: &[u8]) -> Option<i32> {
371	    let (sign, digits) = match tok.split_first()? {
372	        (b'+', rest) => (1, rest),
373	        (b'-', rest) => (-1, rest),
374	        _ => return None,
375	    };
376	    if digits.len() != 4 {
377	        return None;
378	    }
379	    let hh = ascii_number(&digits[..2])? as i32;
380	    let mm = ascii_number(&digits[2..])? as i32;
381	    (hh < 24 && mm < 60).then_some(sign * (hh * 3600 + mm * 60))
382	}
