384	/// The date carried by a separator line, as (naive local time, zone offset in
385	/// seconds when the line names a numeric one).
386	fn from_line_date(line: &[u8]) -> Option<(chrono::NaiveDateTime, Option<i32>)> {
387	    let rest = line.strip_prefix(b"From ")?;
388	    let toks: Vec<&[u8]> = trim_eol(rest)
389	        .split(|b| b.is_ascii_whitespace())
390	        .filter(|t| !t.is_empty())
391	        .collect();
392	    // weekday month day time [zone] year — anywhere after `From `, because the
393	    // sender token is free-form (`-`, `MAILER-DAEMON`, `1699…@xxx`, or absent).
394	    for i in 0..toks.len() {
395	        if token_in(toks[i], &WEEKDAYS).is_none() || i + 4 >= toks.len() {
396	            continue;
397	        }
398	        let Some(month) = token_in(toks[i + 1], &MONTHS) else {
399	            continue;
400	        };
401	        let Some(day) = ascii_number(toks[i + 2]) else {
402	            continue;
403	        };
404	        let Some((h, m, s)) = parse_time(toks[i + 3]) else {
405	            continue;
406	        };
407	        let mut zone = None;
408	        for tok in &toks[i + 4..] {
409	            if let Some(z) = parse_zone(tok) {
410	                zone = Some(z);
411	                continue;
412	            }
413	            let Some(year) = ascii_number(tok).filter(|y| (1970..=9999).contains(y)) else {
414	                continue;
415	            };
416	            let date = chrono::NaiveDate::from_ymd_opt(year as i32, month as u32 + 1, day)?;
417	            // A leap second (`:60`) is legal in a date and not in chrono.
418	            let time = date.and_hms_opt(h, m, s.min(59))?;
419	            return Some((time, zone));
420	        }
421	    }
422	    None
423	}
