431	/// RFC 3339 form of a separator line's date, in UTC. A zone-less asctime date
432	/// is taken as UTC — the line does not say otherwise, and it is only ever a
433	/// fallback for a message with no `Date:` header of its own.
434	fn from_line_rfc3339(line: &[u8]) -> Option<String> {
435	    let (naive, zone) = from_line_date(line)?;
436	    let utc = naive.checked_sub_signed(chrono::Duration::seconds(i64::from(zone.unwrap_or(0))))?;
437	    Some(
438	        chrono::DateTime::<chrono::Utc>::from_naive_utc_and_offset(utc, chrono::Utc)
439	            .to_rfc3339_opts(chrono::SecondsFormat::Secs, true),
440	    )

440	    )
441	}
