443	/// The byte offset a record's locator carries: `m{offset}-msg-s0` → `offset`.
444	/// `None` for any locator this module did not write (`msg-s0` of a standalone
445	/// `.eml` starts with `m` too, and is not an offset).
446	///
447	/// Lives next to the code that WRITES the prefix (`format!("m{}-", msg.offset)`
448	/// in [`extract_from`]) so the two cannot drift. It is how Phase B reports
449	/// progress INSIDE a mailbox: each record says how far into the file its
450	/// message began, which costs nothing and needs no channel from the splitter.
451	///
452	/// Byte-safe: the prefix is ASCII (`m`, digits, `-`), and `strip_prefix` /
453	/// `split_once` only ever cut at the ASCII bytes they matched.
454	pub fn locator_offset(locator: &str) -> Option<u64> {
455	    let (digits, _rest) = locator.strip_prefix('m')?.split_once('-')?;
456	    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
457	        return None;
458	    }
459	    digits.parse().ok()
460	}
