462	/// Extract every message of the mailbox at `path`.
463	///
464	/// `limit_bytes` bounds a SAMPLING read (phase A): splitting stops once that
465	/// many bytes have been consumed. `None` streams the whole file.
466	pub fn extract(
467	    path: &Path,
468	    gzip: bool,
469	    limit_bytes: Option<u64>,
470	    sink: Sink,
471	) -> Result<ExtractStats> {
472	    // No `take()` on the reader: a byte limit that cut the stream mid-message
473	    // would hand the MIME parser a torso. The limit is checked BETWEEN
474	    // messages instead, so every sampled message is whole.
475	    let reader = open_reader(path, gzip, None)?;
