503	/// A counting gate: `limit` permits, taken one per message being parsed.
504	struct Gate {
505	    /// (in use, limit)
506	    state: Mutex<(usize, usize)>,
507	    ready: Condvar,
508	}
509	
510	impl Gate {
511	    fn new(limit: usize) -> Self {
512	        Self {
513	            state: Mutex::new((0, limit.max(1))),
514	            ready: Condvar::new(),
515	        }
516	    }
517	
518	    fn set_limit(&self, limit: usize) {
519	        self.state.lock().expect("mbox gate poisoned").1 = limit.max(1);
520	        self.ready.notify_all();
521	    }
522	
523	    fn limit(&self) -> usize {
524	        self.state.lock().expect("mbox gate poisoned").1
525	    }
526	
527	    fn acquire(&self) -> GatePermit<'_> {
528	        let mut state = self.state.lock().expect("mbox gate poisoned");
529	        while state.0 >= state.1 {
530	            state = self.ready.wait(state).expect("mbox gate poisoned");
531	        }
532	        state.0 += 1;
533	        GatePermit(self)
534	    }
535	}
536	
537	struct GatePermit<'a>(&'a Gate);
538	
539	impl Drop for GatePermit<'_> {
540	    fn drop(&mut self) {
541	        let mut state = self.0.state.lock().expect("mbox gate poisoned");
542	        state.0 = state.0.saturating_sub(1);
543	        self.0.ready.notify_one();
544	    }
545	}
