547	/// Bytes admitted into the pipeline. `acquire` blocks while the request would
548	/// overflow the cap AND something is already in flight; with nothing in
549	/// flight any size goes through, which is what keeps an oversized message
550	/// from waiting forever.
551	struct Budget {
552	    used: Mutex<usize>,
553	    freed: Condvar,
554	    cap: usize,
555	}
556	
557	impl Budget {
558	    fn new(cap: usize) -> Self {
559	        Self {
560	            used: Mutex::new(0),
561	            freed: Condvar::new(),
562	            cap,
563	        }
564	    }
565	
566	    fn acquire(&self, bytes: usize) {
567	        let mut used = self.used.lock().expect("mbox budget poisoned");
568	        while *used > 0 && used.saturating_add(bytes) > self.cap {
569	            used = self.freed.wait(used).expect("mbox budget poisoned");
570	        }
571	        *used = used.saturating_add(bytes);
572	    }
573	
574	    fn release(&self, bytes: usize) {
575	        let mut used = self.used.lock().expect("mbox budget poisoned");
576	        *used = used.saturating_sub(bytes);
577	        drop(used);
578	        self.freed.notify_all();
579	    }
580	}
