582	/// THE byte budget: one for the process, like the parse gate. It used to be one
583	/// per `extract_parallel` call, which bounded a MAILBOX, not the run — Phase B
584	/// reads up to `--workers` files at once, so a tree of twelve Thunderbird
585	/// folders full of large attachments held twelve budgets (measured by the
586	/// review of PR #949: 1.71 GB of client RSS against the ~0.3 GB documented for
587	/// the one-mailbox Takeout case).
588	fn shared_budget() -> &'static Budget {
589	    static BUDGET: OnceLock<Budget> = OnceLock::new();
590	    BUDGET.get_or_init(|| Budget::new(IN_FLIGHT_BUDGET))
591	}
