593	/// One mailbox's claim on a shared [`Budget`]. Whatever it still holds when
594	/// the mailbox is done with — a splitter error, a sink that said stop, a job
595	/// that could not be handed over — goes back on drop, so no exit path of one
596	/// mailbox can shrink the budget for every mailbox after it.
597	struct Lease<'a> {
598	    budget: &'a Budget,
599	    held: Mutex<usize>,
600	}
601	
602	impl<'a> Lease<'a> {
603	    fn new(budget: &'a Budget) -> Self {
604	        Self {
605	            budget,
606	            held: Mutex::new(0),
607	        }
608	    }
609	
610	    fn acquire(&self, bytes: usize) {
611	        self.budget.acquire(bytes);
612	        let mut held = self.held.lock().expect("mbox lease poisoned");
613	        *held = held.saturating_add(bytes);
614	    }
615	
616	    fn release(&self, bytes: usize) {
617	        let bytes = {
618	            let mut held = self.held.lock().expect("mbox lease poisoned");
619	            let bytes = bytes.min(*held);
620	            *held -= bytes;
621	            bytes
622	        };
623	        self.budget.release(bytes);
624	    }
625	}
626	
627	impl Drop for Lease<'_> {
628	    fn drop(&mut self) {
629	        let rest = std::mem::take(&mut *self.held.lock().unwrap_or_else(|p| p.into_inner()));
630	        if rest > 0 {
631	            self.budget.release(rest);
632	        }
633	    }
634	}
