642	    Message {
643	        seq: u64,
644	        bytes: usize,
645	        records: Vec<RawRecord>,
646	        stats: ExtractStats,
647	    },
648	    /// The splitter failed after handing out `seq` messages.
649	    Error { seq: u64, error: std::io::Error },
650	    /// The splitter is done; `total` messages were handed out.
