654	/// Emit one split-out message through `sink`. Returns the sink's last answer
655	/// (`false` = stop). Shared by the sequential and the parallel path so the
656	/// two cannot drift.
657	fn emit_raw_message(msg: &RawMessage, sink: Sink, stats: &mut ExtractStats) -> bool {
658	    let prefix = format!("m{}-", msg.offset);
659	    if msg.oversized() {
660	        // Over the per-message cap: the head is parsed (headers, body and
661	        // whatever attachments fit), the tail is not. Reported, never
662	        // silent — the run names this file as truncated.
663	        stats.truncated = true;
664	    }
665	    let env = MessageEnvelope {
666	        loc_prefix: &prefix,
667	        fallback_date: from_line_rfc3339(msg.from_line.as_bytes()),
668	    };
669	    match emit_message(&msg.bytes, &env, sink, stats) {
670	        MessageOutcome::Emitted { alive } => alive,
671	        MessageOutcome::Unparseable => emit_unparseable(msg, &prefix, &env, sink, stats),
672	    }
673	}
