675	fn extract_from<R: BufRead + Send>(
676	    reader: R,
677	    limit_bytes: Option<u64>,
678	    sink: Sink,
679	) -> Result<ExtractStats> {
680	    // Sampling stays sequential: it stops at a byte limit, and which
681	    // messages it saw must be a function of the bytes, not of scheduling.
682	    let workers = if limit_bytes.is_some() {
683	        1
684	    } else {
685	        parallelism()
686	    };
687	    if workers <= 1 {
688	        extract_sequential(reader, limit_bytes, sink)
689	    } else {
690	        extract_parallel(reader, sink, workers)
691	    }
692	}
693	
694	fn extract_sequential<R: BufRead>(
695	    reader: R,
696	    limit_bytes: Option<u64>,
697	    sink: Sink,
698	) -> Result<ExtractStats> {
699	    let mut stats = ExtractStats::default();
700	    let mut split = Splitter::new(reader);
701	    while let Some(msg) = split.next_message()? {
702	        if !emit_raw_message(&msg, sink, &mut stats) {
703	            break;
704	        }
705	        if limit_bytes.is_some_and(|limit| split.consumed() >= limit) {
706	            break;
707	        }
708	    }
709	    Ok(stats)
710	}
