712	/// One message, parsed on a pool thread into a local buffer.
713	fn extract_one(msg: &RawMessage) -> (Vec<RawRecord>, ExtractStats) {
714	    let mut stats = ExtractStats::default();
715	    let mut records = Vec::new();
716	    let mut sink = |r: RawRecord| {
717	        records.push(r);
718	        true
719	    };
720	    emit_raw_message(msg, &mut sink, &mut stats);
721	    (records, stats)
722	}
