724	/// The pipeline described in the module docs: splitter thread → `workers`
725	/// parsers → this thread, which forwards records in message order.
726	///
727	/// Why it cannot deadlock: the forwarding thread blocks only on the result
728	/// channel; a parser blocks only on the job channel (closed by the splitter
729	/// when it ends) and on the process gate (released by other parsers); the
730	/// splitter blocks on the budget and on the job channel, both released by
731	/// the forwarding thread and the parsers respectively. When the sink says
732	/// stop, the splitter sees the flag on its next message, and this thread
733	/// keeps draining results — without forwarding — until the splitter's `End`
734	/// arrives, so nothing is left blocked on a channel this thread has dropped.
735	fn extract_parallel<R: BufRead + Send>(
736	    reader: R,
737	    sink: Sink,
738	    workers: usize,
739	) -> Result<ExtractStats> {
740	    let (job_tx, job_rx) = mpsc::sync_channel::<Job>(workers);
741	    let job_rx = Arc::new(Mutex::new(job_rx));
742	    let (done_tx, done_rx) = mpsc::channel::<Done>();
743	    let stop = AtomicBool::new(false);
744	    let budget = Lease::new(shared_budget());
745	    let mut stats = ExtractStats::default();
746	    let mut failure: Option<std::io::Error> = None;
747	
748	    std::thread::scope(|scope| {
749	        let splitter_tx = done_tx.clone();
750	        let (stop_ref, budget_ref) = (&stop, &budget);
751	        scope.spawn(move || {
752	            let mut split = Splitter::new(reader);
753	            let mut seq = 0u64;
754	            loop {
755	                if stop_ref.load(Ordering::Relaxed) {
756	                    break;
757	                }
758	                match split.next_message() {
759	                    Ok(Some(msg)) => {
760	                        budget_ref.acquire(msg.bytes.len());
761	                        if let Err(mpsc::SendError(job)) = job_tx.send(Job { seq, msg }) {
762	                            // Never handed over, so nobody will release it.
763	                            budget_ref.release(job.msg.bytes.len());
764	                            break;
765	                        }
766	                        seq += 1;
767	                    }
768	                    Ok(None) => break,
769	                    Err(error) => {
770	                        let _ = splitter_tx.send(Done::Error { seq, error });
771	                        break;
772	                    }
773	                }
774	            }
775	            let _ = splitter_tx.send(Done::End { total: seq });
776	            // `job_tx` drops here: the parsers drain what is queued and exit.
777	        });
778	        for _ in 0..workers {
779	            let job_rx = Arc::clone(&job_rx);
780	            let done_tx = done_tx.clone();
781	            scope.spawn(move || loop {
782	                // Hold the lock only while waiting for a job, never while
783	                // parsing one: the other parsers must be able to take theirs.
784	                let job = match job_rx.lock() {
785	                    Ok(rx) => rx.recv(),
786	                    Err(_) => return,
787	                };
788	                let Ok(Job { seq, msg }) = job else { return };
789	                let _slot = gate().acquire();
790	                let bytes = msg.bytes.len();
791	                let (records, stats) = extract_one(&msg);
792	                drop(msg);
793	                if done_tx
794	                    .send(Done::Message {
795	                        seq,
796	                        bytes,
797	                        records,
798	                        stats,
799	                    })
800	                    .is_err()
801	                {
802	                    return;
803	                }
804	            });
805	        }
806	        drop(done_tx);
807	
808	        let mut next = 0u64;
809	        let mut total: Option<u64> = None;
810	        let mut pending: BTreeMap<u64, (usize, Vec<RawRecord>, ExtractStats)> = BTreeMap::new();
811	        let mut alive = true;
812	        loop {
813	            if total.is_some_and(|t| next >= t) {
814	                break;
815	            }
816	            let Ok(done) = done_rx.recv() else { break };
817	            match done {
818	                Done::End { total: t } => total = Some(t),
819	                Done::Error { seq, error } => {
820	                    failure = Some(error);
821	                    total = Some(seq);
822	                }
823	                Done::Message {
824	                    seq,
825	                    bytes,
826	                    records,
827	                    stats,
828	                } => {
829	                    pending.insert(seq, (bytes, records, stats));
830	                }
831	            }
832	            while let Some((bytes, records, s)) = pending.remove(&next) {
833	                next += 1;
834	                budget.release(bytes);
835	                if !alive {
836	                    continue;
837	                }
838	                stats.records += s.records;
839	                stats.junk += s.junk;
840	                stats.truncated |= s.truncated;
841	                for record in records {
842	                    if !sink(record) {
843	                        alive = false;
844	                        stop.store(true, Ordering::Relaxed);
845	                        break;
846	                    }
847	                }
848	            }
849	        }
850	    });
851	    match failure {
852	        Some(error) => Err(error.into()),
853	        None => Ok(stats),
854	    }
855	}
