857	/// A mailbox entry the MIME parser refused outright. Its text is still in the
858	/// user's mailbox and still worth finding, so it is indexed as a plain
859	/// document rather than dropped; an entry with no text at all is junk.
860	fn emit_unparseable(
861	    msg: &RawMessage,
862	    prefix: &str,
863	    env: &MessageEnvelope<'_>,
864	    sink: Sink,
865	    stats: &mut ExtractStats,
866	) -> bool {
867	    let (text, _) = crate::sniff::decode_text(&msg.bytes);
868	    let text = text.trim();
869	    if text.is_empty() {
870	        stats.junk += 1;
871	        return true;
872	    }
873	    let mut fields = Map::new();
874	    if let Some(date) = &env.fallback_date {
875	        fields.insert("email_date".into(), Value::String(date.clone()));
876	    }
877	    emit_document_with_fields(
878	        &fields,
879	        "(unparseable message)",
880	        text,
881	        &format!("{prefix}raw"),
882	        sink,
883	        stats,
884	    )
885	}
