1	//! Unity text-serialized assets — streaming multi-document splitter — and
2	//! `.meta` sidecars.
3	//!
4	//! Unity YAML is a multi-document stream where every document opens with
5	//! `--- !u!<classId> &<fileID>` (optionally suffixed `stripped` for prefab
6	//! instances). serde_yaml cannot be used on the whole stream: it resolves
7	//! anchors internally and never exposes the anchor NAME, and the `fileID`
8	//! that makes Unity objects joinable lives in that anchor. So the splitter
9	//! owns the document boundaries (a cheap line prefix match) and hands each
10	//! body — plain YAML once the `%YAML`/`%TAG` header is dropped — to
11	//! serde_yaml individually. Owning the boundaries is also what makes it safe
12	//! to `continue` past a corrupt document: unlike `yaml_x`, there is no
13	//! iterator that would re-yield the same broken document forever.
14	//!
15	//! Files stream line-by-line (real scenes can exceed 200 MB; a single
16	//! AnimationClip document can be tens of MB), with a 16 MiB per-document
17	//! cap: over-cap documents are junked and skipped to the next boundary,
18	//! the rest of the file survives.
19	//!
20	//! Emitted fields per object document:
21	//! - `unity_class`      body's top-level key (authoritative), else class-id table
22	//! - `unity_class_id`   from the `!u!<id>` tag
23	//! - `file_id`          from the `&<anchor>` — the join key for local refs
24	//! - `stripped`         only present (true) on stripped prefab-instance docs
25	//! - `name`             `m_Name` when present
26	//! - `ref_guids`        deduped guids of every `{fileID, guid, type}` reference
27	//! - `script_guid`      the `m_Script` reference's guid (MonoBehaviour → .cs)
28	//! - flattened body fields
29	//!
30	//! KNOWN LIMITATION (engine-side, xerj-org/xerj#332): `ref_guids` is a
31	//! multi-valued keyword array and the FTS writer joins array elements into
32	//! ONE space-separated token, so a post-flush `term`/`match` on a single guid
33	//! does not match. `script_guid`, `script_path` and `script_class` are
34	//! single-valued and unaffected — the documented "which scenes use this
35	//! script?" query goes through those, not through `ref_guids`.
36	//!
37	//! `.meta` sidecars emit ONE record: `guid`, `asset_name`, `importer`, and
38	//! flattened settings. The root-relative `asset_path` (and the
39	//! `script_path`/`script_class` denormalization on MonoBehaviour records) is
40	//! stamped by the pipeline, which knows the walk root — extractors stay
41	//! per-file pure.
42	
43	use super::{flatten_object, yaml_to_json, ExtractStats, FieldOrigin, RawRecord, Sink, MAX_LINE};
44	use anyhow::Result;
45	use serde_json::{Map, Value};
46	use std::path::Path;
47	
48	/// Per-document cap. One logical unit follows the `MAX_LINE` convention;
49	/// 16 MiB covers large AnimationClip / font documents while bounding memory.
50	/// (A 4 MiB cap was considered and rejected: it junks those documents.)
51	const DOC_CAP: usize = 16 << 20;
52	
53	const META_CAP: u64 = 16 << 20;
54	
55	/// Field names this extractor invents on object records. A body field with
56	/// the same name (possible on MonoBehaviour custom fields) is renamed
57	/// `data_<name>` rather than dropped, mirroring the `ax_*` collision policy.
58	const RESERVED: &[&str] = &[
59	    "unity_class",
60	    "unity_class_id",
61	    "file_id",
62	    "stripped",
63	    "name",
64	    "ref_guids",
65	    "script_guid",
66	    "script_path",
67	    "script_class",
68	];
69	
70	pub fn extract_unity(
71	    path: &Path,
72	    gzip: bool,
73	    limit_bytes: Option<u64>,
74	    sink: Sink,
75	) -> Result<ExtractStats> {
76	    let mut r = super::open_reader(path, gzip, limit_bytes)?;
77	    let mut stats = ExtractStats::default();
78	    let mut offset: u64 = 0;
79	    let mut line: Vec<u8> = Vec::new();
80	    let mut doc: Vec<u8> = Vec::new();
81	    let mut header: Option<DocHeader> = None;
82	    let mut skipping = false;
83	    loop {
84	        line.clear();
85	        let n = super::jsonl::read_capped_line(&mut r, &mut line)?;
86	        let eof = n == 0;
87	        offset += n as u64;
88	        let boundary = if eof { None } else { parse_boundary(&line) };
89	        if eof || boundary.is_some() {
90	            if let Some(h) = header.take() {
91	                if skipping {
92	                    skipping = false;
93	                } else {
94	                    let truncated = eof && limit_bytes.is_some_and(|l| offset >= l);
95	                    if !emit_doc(&h, &doc, truncated, &mut stats, sink) {
96	                        return Ok(stats);
97	                    }
98	                }
99	            }
100	            doc.clear();
101	            header = boundary;
102	            if eof {
103	                break;
104	            }
105	            continue;
106	        }
107	        if header.is_none() || skipping {
108	            continue; // %YAML/%TAG preamble, or discarding an over-cap doc
109	        }
110	        if doc.len() + line.len() > DOC_CAP {
111	            stats.junk += 1;
112	            skipping = true;
113	            doc.clear();
114	            continue;
115	        }
116	        doc.extend_from_slice(&line);
117	    }
118	    // Empty yield from a FULL read means the file was preamble-only (or
119	    // junk-shaped throughout) — record it. A sampling read that truncated
120	    // before the first document completed is not evidence of anything.
121	    let truncated_run = limit_bytes.is_some_and(|l| offset >= l);
122	    if stats.records == 0 && stats.junk == 0 && !truncated_run {
123	        stats.junk += 1;
124	    }
125	    Ok(stats)
126	}
127	
128	struct DocHeader {
129	    class_id: i64,
130	    /// Raw anchor text (handles negative 64-bit ids verbatim).
131	    file_id: String,
132	    stripped: bool,
133	}
134	
135	/// `--- !u!<classId> &<fileID>[ stripped]` — cheap manual parse, no regex on
136	/// the hot per-line path.
137	fn parse_boundary(line: &[u8]) -> Option<DocHeader> {
138	    let s = std::str::from_utf8(line).ok()?.trim_end();
139	    let rest = s.strip_prefix("--- !u!")?;
140	    let (id_part, rest) = rest.split_once(" &")?;
141	    let class_id: i64 = id_part.trim().parse().ok()?;
142	    let (anchor, tail) = match rest.split_once(' ') {
143	        Some((a, t)) => (a, t.trim()),
144	        None => (rest, ""),
145	    };
146	    let anchor = anchor.trim();
147	    if anchor.is_empty() || !anchor.chars().all(|c| c.is_ascii_digit() || c == '-') {
148	        return None;
149	    }
150	    Some(DocHeader {
151	        class_id,
152	        file_id: anchor.to_string(),
153	        stripped: tail == "stripped",
154	    })
155	}
156	
157	fn emit_doc(
158	    h: &DocHeader,
159	    body: &[u8],
160	    truncated_by_sampling: bool,
161	    stats: &mut ExtractStats,
162	    sink: Sink,
163	) -> bool {
164	    let text = String::from_utf8_lossy(body);
165	    let parsed: serde_yaml::Value = match serde_yaml::from_str(&text) {
166	        Ok(v) => v,
167	        Err(_) => {
168	            if !truncated_by_sampling {
169	                stats.junk += 1;
170	            }
171	            return true;
172	        }
173	    };
174	    let jv = yaml_to_json(parsed);
175	    let (class_from_body, inner) = match jv {
176	        Value::Object(m) if m.len() == 1 => {
177	            let (k, v) = m.into_iter().next().expect("len checked");
178	            (Some(k), v)
179	        }
180	        other => (None, other),
181	    };
182	    let unity_class = class_from_body.unwrap_or_else(|| {
183	        class_name(h.class_id)
184	            .map(str::to_string)
185	            .unwrap_or_else(|| format!("class_{}", h.class_id))
186	    });
187	
188	    let mut refs: Vec<String> = Vec::new();
189	    let mut script_guid: Option<String> = None;
190	    collect_guid_refs(&inner, &mut refs);
191	    if let Some(script) = inner.get("m_Script") {
192	        if let Some(g) = script.get("guid").and_then(Value::as_str) {
193	            script_guid = Some(g.to_string());
194	        }
195	    }
196	
197	    let mut fields = match inner {
198	        Value::Object(m) => flatten_object(m),
199	        Value::Null => Map::new(),
200	        other => {
201	            let mut m = Map::new();
202	            m.insert("value".into(), other);
203	            m
204	        }
205	    };
206	    for k in RESERVED {
207	        if let Some(v) = fields.remove(*k) {
208	            fields.insert(format!("data_{k}"), v);
209	        }
210	    }
211	    if let Some(Value::String(n)) = fields.get("m_Name") {
212	        if !n.is_empty() {
213	            fields.insert("name".into(), Value::String(n.clone()));
214	        }
215	    }
216	    fields.insert("unity_class".into(), Value::String(unity_class.clone()));
217	    fields.insert("unity_class_id".into(), Value::Number(h.class_id.into()));
218	    fields.insert("file_id".into(), Value::String(h.file_id.clone()));
219	    if h.stripped {
220	        fields.insert("stripped".into(), Value::Bool(true));
221	    }
222	    if !refs.is_empty() {
223	        let mut seen = std::collections::HashSet::new();
224	        let deduped: Vec<Value> = refs
225	            .into_iter()
226	            .filter(|g| seen.insert(g.clone()))
227	            .map(Value::String)
228	            .collect();
229	        fields.insert("ref_guids".into(), Value::Array(deduped));
230	    }
231	    if let Some(g) = script_guid {
232	        fields.insert("script_guid".into(), Value::String(g));
233	    }
234	
235	    stats.records += 1;
236	    sink(RawRecord {
237	        fields,
238	        locator: format!("u{}", h.file_id),
239	        group: Some(unity_class),
240	        // Body field names are Unity's serialization vocabulary plus per-script
241	        // custom fields; letting them cluster would split MonoBehaviours into
242	        // schema-similarity datasets and re-home documents when scripts change
243	        // (issue #178). Family+group clustering gives one stable dataset per
244	        // Unity class instead.
245	        origin: FieldOrigin::Extractor,
246	    })
247	}
