249	/// Walk the parsed document for `{fileID, guid, type}` reference mappings and
250	/// collect every guid, including inside arrays (`m_Modifications` — prefab
251	/// overrides — is where the highest-value references live).
252	fn collect_guid_refs(v: &Value, out: &mut Vec<String>) {
253	    match v {
254	        Value::Object(m) => {
255	            if m.contains_key("fileID") {
256	                if let Some(g) = m.get("guid").and_then(Value::as_str) {
257	                    out.push(g.to_string());
258	                }
259	            }
260	            for vv in m.values() {
261	                collect_guid_refs(vv, out);
262	            }
263	        }
264	        Value::Array(a) => {
265	            for vv in a {
266	                collect_guid_refs(vv, out);
267	            }
268	        }
269	        _ => {}
270	    }
271	}
