273	pub fn extract_meta(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
274	    let mut stats = ExtractStats::default();
275	    let Some(bytes) = super::read_whole(path, gzip, META_CAP)? else {
276	        stats.junk += 1;
277	        return Ok(stats);
278	    };
279	    let (text, _) = crate::sniff::decode_text(&bytes);
280	    let text = text.trim_start_matches('\u{feff}');
281	    let parsed: serde_yaml::Value = match serde_yaml::from_str(text) {
282	        Ok(v) => v,
283	        Err(_) => {
284	            stats.junk += 1;
285	            return Ok(stats);
286	        }
287	    };
288	    let Value::Object(m) = yaml_to_json(parsed) else {
289	        stats.junk += 1;
290	        return Ok(stats);
291	    };
292	    let guid = m.get("guid").and_then(Value::as_str).map(str::to_string);
293	    let importer = m
294	        .keys()
295	        .find(|k| k.ends_with("Importer") || k.ends_with("importer"))
296	        .cloned();
297	    let mut fields = flatten_object(m);
298	    if let Some(g) = guid {
299	        fields.insert("guid".into(), Value::String(g));
300	    }
301	    if let Some(imp) = importer {
302	        fields.insert("importer".into(), Value::String(imp));
303	    }
304	    if let Some(name) = path
305	        .file_name()
306	        .and_then(|n| n.to_str())
307	        .and_then(|n| n.strip_suffix(".meta"))
308	    {
309	        fields.insert("asset_name".into(), Value::String(name.to_string()));
310	    }
311	    stats.records += 1;
312	    sink(RawRecord {
313	        fields,
314	        locator: "meta".into(),
315	        group: None,
316	        origin: FieldOrigin::Extractor,
317	    });
318	    Ok(stats)
319	}
