1	//! BVH motion capture — ONE metadata record per file, motion data never read.
2	//!
3	//! A BVH file is a small skeleton HIERARCHY header followed by a numeric
4	//! MOTION block that can run to hundreds of MB (one line per frame). The
5	//! frames carry no retrieval value — they are float soup — but the header
6	//! does: joint names make the skeleton searchable, and frame count/time give
7	//! the clip's duration. So this extractor streams the header, captures that
8	//! metadata, and STOPS as soon as the two `Frames:`/`Frame Time:` lines after
9	//! `MOTION` are read — the motion block is never pulled off disk.
10	//!
11	//! Emitted fields: `title`, `joints` (names, document order), `joint_count`,
12	//! `frames`, `frame_time_s`, `duration_s`. All extractor vocabulary
13	//! (`FieldOrigin::Extractor`), so every BVH file clusters into one dataset.
14	//!
15	//! KNOWN LIMITATION (engine-side, xerj-org/xerj#332): `joints` is a
16	//! multi-valued keyword array, and the FTS writer currently joins array
17	//! elements into ONE space-separated token. So after a segment flush,
18	//! `{"term": {"joints": "LeftHand"}}` does NOT match — there is no
19	//! per-element posting. `terms` and other clauses that take the stored-scan
20	//! path still match, and so does everything before the flush, which is why
21	//! this is easy to miss. "Which clips animate LeftHand?" is only a reliable
22	//! one-query answer once #332 lands; it is an engine API change (the FTS
23	//! writer input is `HashMap<String, String>`), not something this extractor
24	//! can work around.
25	
26	use super::{ExtractStats, FieldOrigin, RawRecord, Sink};
27	use anyhow::Result;
28	use serde_json::{Map, Value};
29	use std::path::Path;
30	
31	/// Skeleton headers are a few KB; a "header" that runs past this is not a
32	/// BVH we understand, and the file junks rather than streaming megabytes.
33	const HEADER_CAP: usize = 1 << 20;
34	
35	pub fn extract(path: &Path, gzip: bool, sink: Sink) -> Result<ExtractStats> {
36	    let mut stats = ExtractStats::default();
37	    let mut r = super::open_reader(path, gzip, None)?;
38	    let mut joints: Vec<String> = Vec::new();
39	    let mut frames: Option<i64> = None;
40	    let mut frame_time: Option<f64> = None;
41	    let mut in_motion = false;
42	    let mut consumed = 0usize;
43	    let mut line: Vec<u8> = Vec::new();
44	    loop {
45	        line.clear();
46	        let n = super::jsonl::read_capped_line(&mut r, &mut line)?;
47	        if n == 0 {
48	            break;
49	        }
50	        consumed += n;
51	        if consumed > HEADER_CAP {
52	            stats.junk += 1;
53	            return Ok(stats);
54	        }
55	        let text = String::from_utf8_lossy(&line);
56	        let t = text.trim();
57	        if !in_motion {
58	            if let Some(name) = t.strip_prefix("ROOT ").or_else(|| t.strip_prefix("JOINT ")) {
59	                let name = name.trim();
60	                if !name.is_empty() && name.len() <= 200 {
61	                    joints.push(name.to_string());
62	                }
63	            } else if t == "MOTION" {
64	                in_motion = true;
65	            }
66	            continue;
67	        }
68	        if let Some(v) = t.strip_prefix("Frames:") {
69	            frames = v.trim().parse().ok();
70	        } else if let Some(v) = t.strip_prefix("Frame Time:") {
71	            frame_time = v.trim().parse().ok();
72	        }
73	        if frames.is_some() && frame_time.is_some() {
74	            break; // metadata complete — the motion block is never read
75	        }
76	    }
77	    if joints.is_empty() {
78	        stats.junk += 1;
79	        return Ok(stats);
80	    }
81	
82	    let title = path
83	        .file_name()
84	        .and_then(|n| n.to_str())
85	        .unwrap_or("motion")
86	        .to_string();
87	    let mut fields = Map::new();
88	    fields.insert("title".into(), Value::String(title));
89	    fields.insert(
90	        "joints".into(),
91	        Value::Array(joints.iter().map(|j| Value::String(j.clone())).collect()),
92	    );
93	    fields.insert(
94	        "joint_count".into(),
95	        Value::Number((joints.len() as u64).into()),
96	    );
97	    if let Some(f) = frames {
98	        fields.insert("frames".into(), Value::Number(f.into()));
99	    }
100	    if let Some(ft) = frame_time {
101	        if let Some(num) = serde_json::Number::from_f64(ft) {
102	            fields.insert("frame_time_s".into(), Value::Number(num));
103	        }
104	        if let (Some(f), true) = (frames, ft.is_finite()) {
105	            if let Some(num) = serde_json::Number::from_f64(f as f64 * ft) {
106	                fields.insert("duration_s".into(), Value::Number(num));
107	            }
108	        }
109	    }
110	    stats.records += 1;
111	    sink(RawRecord {
112	        fields,
113	        locator: "bvh".into(),
114	        group: None,
115	        origin: FieldOrigin::Extractor,
116	    });
117	    Ok(stats)
118	}
