143	        let r = &recs[0];
144	        assert_eq!(r.fields["title"], "clip.bvh");
145	        assert_eq!(r.fields["joints"], serde_json::json!(["Hips", "LeftUpLeg"]));
146	        assert_eq!(r.fields["joint_count"], 2);
